NCTION dbo.fn_GheCoVeHieuLucSuatTuongLai(@GheID INT)\r\nRETURNS BIT\r\nAS\r\nBEGIN\r\n    DECLARE @CoVe BIT = 0;\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM dbo.CHITIETVE cv\r\n        INNER JOIN dbo.DONDATVE ddv ON ddv.DonDatVeID = cv.DonDatVeID\r\n        INNER JOIN dbo.SUATCHIEU sc ON sc.SuatChieuID = ddv.SuatChieuID\r\n        WHERE cv.GheID = @GheID\r\n          AND cv.TrangThai = N''Đã đặt''\r\n          AND sc.ThoiGianBatDau > dbo.fn_BayGio()\r\n          AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\r\n    ) SET @CoVe = 1;\r\n    RETURN @CoVe;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanDonDangGiu","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanDonDangGiu()\r\nRETURNS INT\r\nAS\r\nBEGIN\r\n    RETURN 3;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanGheMoiDon","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanGheMoiDon()\r\nRETURNS INT\r\nAS\r\nBEGIN\r\n    RETURN 10;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanGiamGiaPhanTram","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanGiamGiaPhanTram()\r\nRETURNS INT\r\nAS\r\nBEGIN\r\n    RETURN 99;  -- tối đa 99% (cũng là trần của khuyến mãi phần trăm, xem CK_KHUYENMAI_PhanTram99)\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanSoLuongSanPham","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanSoLuongSanPham()\r\nRETURNS INT\r\nAS\r\nBEGIN\r\n    RETURN 10;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioRap","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioRap(@UtcInstant DATETIME2(7))\nRETURNS DATETIMEOFFSET(7)\nAS\nBEGIN\n    -- Windows zone corresponding to the application''s Asia/Ho_Chi_Minh.\n    RETURN @UtcInstant AT TIME ZONE ''UTC'' AT TIME ZONE ''SE Asia Standard Time'';\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_HomNay","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_HomNay()\r\nRETURNS DATE\r\nAS\r\nBEGIN\r\n    RETURN dbo.fn_NgayKinhDoanh(dbo.fn_BayGio());\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_KiemTraQuanLyRapScope","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"-- Baseline: functions/02_functions.sql:304 (dbo.fn_KiemTraQuanLyRapScope)\nCREATE   FUNCTION dbo.fn_KiemTraQuanLyRapScope\n(\n    @NguoiDungID INT,\n    @RapID INT\n)\nRETURNS BIT\nAS\nBEGIN\n    -- Nếu là QUAN_LY_RAP, kiểm tra bảng PHANCONG_RAP còn hiệu lực\n    IF EXISTS (\n        SELECT 1\n        FROM dbo.PHANCONG_RAP pcr\n        INNER JOIN dbo.NGUOIDUNG nd ON pcr.NguoiDungID = nd.NguoiDungID\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE pcr.NguoiDungID = @NguoiDungID\n          AND pcr.RapID = @RapID\n          AND pcr.TrangThai = N''Hiệu lực''\n          AND dbo.fn_HomNay() >= pcr.NgayBatDau\n          AND (pcr.NgayKetThuc IS NULL OR dbo.fn_HomNay() <= pcr.NgayKetThuc)\n          AND nd.TrangThai = N''Hoạt động''\n          AND vt.MaVaiTro = ''QUAN_LY_RAP''\n    )\n    BEGIN\n        RETURN 1;\n    END\n\n    RETURN 0;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_KiemTraQuyenNguoiDung","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_KiemTraQuyenNguoiDung\n(\n    @NguoiDungID INT,\n    @MaQuyen VARCHAR(50)\n)\nRETURNS BIT\nAS\nBEGIN\n    DECLARE @HopLe BIT = 0;\n\n    -- Kiểm tra quyền cụ thể qua bảng nối VAITRO_QUYEN\n    IF EXISTS (\n        SELECT 1\n        FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO_QUYEN vq ON nd.VaiTroID = vq.VaiTroID\n        INNER JOIN dbo.QUYEN q ON vq.QuyenID = q.QuyenID\n        WHERE nd.NguoiDungID = @NguoiDungID\n          AND q.MaQuyen = @MaQuyen\n          AND nd.TrangThai = N''Hoạt động''\n    )\n    BEGIN\n        SET @HopLe = 1;\n    END\n\n    RETURN @HopLe;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_NgayKinhDoanh","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_NgayKinhDoanh(@UtcInstant DATETIME2(7))\nRETURNS DATE\nAS\nBEGIN\n    RETURN CONVERT(DATE, dbo.fn_GioRap(@UtcInstant));\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhGiaVe","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"-- ---------------------------------------------------------------------------------------------\r\n-- (2) Weekend independent of configuration.\r\n-- Rule kept exactly as before: Saturday and Sunday are \"Cuối tuần\" (DATEPART(dw) IN (1, 7) under the default\r\n-- DATEFIRST 7 / us_english). 1900-01-01 was a Monday, so DATEDIFF(DAY, ''19000101'', date) % 7 is 0 = Monday ...\r\n-- 5 = Saturday, 6 = Sunday, whatever DATEFIRST or the language is (style 112 is language independent too).\r\n-- Everything else in the function is unchanged from migration 012.\r\n-- ---------------------------------------------------------------------------------------------\r\nCREATE   FUNCTION dbo.fn_TinhGiaVe\r\n(\r\n    @SuatChieuID INT,\r\n    @GheID INT\r\n)\r\nRETURNS DECIMAL(18,2)\r\nAS\r\nBEGIN\r\n    DECLARE @GiaVeCoBan DECIMAL(18,2) = 0;\r\n    DECLARE @RapID INT;\r\n    DECLARE @DinhDang NVARCHAR(50);\r\n    DECLARE @ThoiGianBatDau DATETIME2;\r\n    DECLARE @LoaiGhe NVARCHAR(50);\r\n    DECLARE @LoaiNgay NVARCHAR(50);\r\n    DECLARE @NgayChieu DATE;\r\n    DECLARE @PhuThu DECIMAL(18,2) = 0;\r\n\r\n    SELECT\r\n        @GiaVeCoBan = sc.GiaVeCoBan,\r\n        @DinhDang = sc.DinhDang,\r\n        @ThoiGianBatDau = sc.ThoiGianBatDau,\r\n        @RapID = pc.RapID,\r\n        @NgayChieu = dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau)\n    FROM dbo.SUATCHIEU sc\r\n    INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\r\n    WHERE sc.SuatChieuID = @SuatChieuID;\r\n\r\n    IF @GiaVeCoBan IS NULL RETURN 0;\r\n\r\n    SELECT @LoaiGhe = LoaiGhe\r\n    FROM dbo.GHE\r\n    WHERE GheID = @GheID;\r\n\r\n    IF @LoaiGhe IS NULL SET @LoaiGhe = N''Thường'';\r\n\r\n    -- 5 = Saturday, 6 = Sunday counted from a Monday (independent of DATEFIRST and language)\r\n    IF DATEDIFF(DAY, CONVERT(DATE, ''19000101'', 112), @NgayChieu) % 7 IN (5, 6)\r\n        SET @LoaiNgay = N''Cuối tuần'';\r\n    ELSE\r\n        SET @LoaiNgay = N''Ngày thường'';\r\n\r\n    -- All matching surcharges are added (migration 012)\r\n    SELECT @PhuThu = ISNULL(SUM(PhuThu), 0)\r\n    FROM dbo.BANGGIA bg\r\n    WHERE bg.RapID = @RapID\r\n      AND bg.TrangThai = N''Áp dụng''\r\n      AND @NgayChieu >= bg.NgayBatDau\r\n      AND (@NgayChieu <= bg.NgayKetThuc OR bg.NgayKetThuc IS NULL)\r\n      AND (bg.LoaiGhe = @LoaiGhe OR bg.LoaiGhe = N''Tất cả'')\r\n      AND (bg.LoaiNgay = @LoaiNgay OR bg.LoaiNgay = N''Tất cả'')\r\n      AND (bg.DinhDang = @DinhDang OR bg.DinhDang = N''Tất cả'');\r\n\r\n    RETURN (@GiaVeCoBan + ISNULL(@PhuThu, 0));\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhTongTienDoAn","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhTongTienDoAn\r\n(\r\n    @DonDatVeID INT\r\n)\r\nRETURNS DECIMAL(18,2)\r\nAS\r\nBEGIN\r\n    DECLARE @TongTienDoAn DECIMAL(18,2) = 0;\r\n\r\n    SELECT @TongTienDoAn = ISNULL(SUM(SoLuong * DonGia), 0)\r\n    FROM dbo.CHITIETDOAN\r\n    WHERE DonDatVeID = @DonDatVeID;\r\n\r\n    RETURN @TongTienDoAn;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhTongTienDon","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhTongTienDon\r\n(\r\n    @DonDatVeID INT\r\n)\r\nRETURNS DECIMAL(18,2)\r\nAS\r\nBEGIN\r\n    DECLARE @TongTienVe DECIMAL(18,2) = 0;\r\n    DECLARE @TongTienDoAn DECIMAL(18,2) = 0;\r\n    DECLARE @TienGiamGia DECIMAL(18,2) = 0;\r\n    DECLARE @TongThanhToan DECIMAL(18,2) = 0;\r\n\r\n    SELECT\r\n        @TongTienVe = TongTienVe,\r\n        @TongTienDoAn = TongTienDoAn,\r\n        @TienGiamGia = TienGiamGia\r\n    FROM dbo.DONDATVE\r\n    WHERE DonDatVeID = @DonDatVeID;\r\n\r\n    SET @TongThanhToan = @TongTienVe + @TongTienDoAn - @TienGiamGia;\r\n\r\n    IF @TongThanhToan < 0 SET @TongThanhToan = 0;\r\n\r\n    RETURN @TongThanhToan;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhTongTienVe","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhTongTienVe\r\n(\r\n    @DonDatVeID INT\r\n)\r\nRETURNS DECIMAL(18,2)\r\nAS\r\nBEGIN\r\n    DECLARE @TongTienVe DECIMAL(18,2) = 0;\r\n\r\n    SELECT @TongTienVe = ISNULL(SUM(GiaVe), 0)\r\n    FROM dbo.CHITIETVE\r\n    WHERE DonDatVeID = @DonDatVeID\r\n      AND TrangThai <> N''Đã hủy'';\r\n\r\n    RETURN @TongTienVe;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_ThoiGianGiaHanThanhToanPhut","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_ThoiGianGiaHanThanhToanPhut()\r\nRETURNS INT\r\nAS\r\nBEGIN\r\n    RETURN 5;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_ThoiGianGiuChoPhut","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"-- ---------------------------------------------------------------------------------------------\r\n-- Single places for the rules (same pattern as fn_ThoiGianGiuChoPhut)\r\n-- ---------------------------------------------------------------------------------------------\r\nCREATE   FUNCTION dbo.fn_ThoiGianGiuChoPhut()\r\nRETURNS INT\r\nAS\r\nBEGIN\r\n    RETURN 5;   -- Điểm duy nhất cấu hình thời gian giữ ghế; không gia hạn\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_UtcTuGioRap","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_UtcTuGioRap(@LocalDateTime DATETIME2(7))\nRETURNS DATETIME2(7)\nAS\nBEGIN\n    RETURN CONVERT(DATETIME2(7), @LocalDateTime AT TIME ZONE ''SE Asia Standard Time'' AT TIME ZONE ''UTC'');\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_DanhSachGheSuatChieu","type":"IF","type_desc":"SQL_INLINE_TABLE_VALUED_FUNCTION","definition":"-- Baseline: functions/02_functions.sql:203 (dbo.fn_DanhSachGheSuatChieu)\r\nCREATE   FUNCTION dbo.fn_DanhSachGheSuatChieu\r\n(\r\n    @SuatChieuID INT\r\n)\r\nRETURNS TABLE\r\nAS\r\nRETURN\r\n(\r\n    WITH GhePhong AS (\r\n        SELECT\r\n            g.GheID,\r\n            g.PhongID,\r\n            g.HangGhe,\r\n            g.SoGhe,\r\n            (g.HangGhe + CAST(g.SoGhe AS VARCHAR(10))) AS TenGhe,\r\n            g.LoaiGhe,\r\n            g.TrangThai AS TrangThaiGheVatLy\r\n        FROM dbo.SUATCHIEU sc\r\n        INNER JOIN dbo.GHE g ON sc.PhongID = g.PhongID\r\n        WHERE sc.SuatChieuID = @SuatChieuID\r\n    ),\r\n    GheChiemCho AS (\r\n        -- Mức 2 = đã bán (đơn đã thanh toán), mức 1 = đang giữ chỗ chờ thanh toán\r\n        SELECT\r\n            cv.GheID,\r\n            MAX(CASE WHEN ddv.TrangThai = N''Chờ thanh toán'' THEN 1 ELSE 2 END) AS Muc\r\n        FROM dbo.CHITIETVE cv\r\n        INNER JOIN dbo.DONDATVE ddv ON cv.DonDatVeID = ddv.DonDatVeID\r\n        WHERE ddv.SuatChieuID = @SuatChieuID\r\n          AND cv.TrangThai <> N''Đã hủy''\r\n          AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\r\n        GROUP BY cv.GheID\r\n    )\r\n    SELECT\r\n        gp.GheID,\r\n        gp.PhongID,\r\n        gp.HangGhe,\r\n        gp.SoGhe,\r\n        gp.TenGhe,\r\n        gp.LoaiGhe,\r\n        dbo.fn_TinhGiaVe(@SuatChieuID, gp.GheID) AS GiaVe,\r\n        CASE\r\n            WHEN gp.TrangThaiGheVatLy <> N''Hoạt động'' THEN N''Bảo trì''\r\n            WHEN gdd.Muc = 2 THEN N''Đã đặt''\r\n            WHEN gdd.Muc = 1 THEN N''Đang giữ''\r\n            ELSE N''Trống''\r\n        END AS TrangThaiGhe\r\n    FROM GhePhong gp\r\n    LEFT JOIN GheChiemCho gdd ON gp.GheID = gdd.GheID\r\n);\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhBoiThuongVe","type":"IF","type_desc":"SQL_INLINE_TABLE_VALUED_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhBoiThuongVe (\n    @TongTienVe DECIMAL(18,2), @TongTienDoAn DECIMAL(18,2), @TienGiamGia DECIMAL(18,2)\n)\nRETURNS TABLE\nAS RETURN (\n    -- Proportional allocation: Ve - Giam * Ve / (Ve + DoAn).\n    -- Integer cents are exact DECIMAL values, not a monetary rounding step.\n    -- Use the remainder to avoid division rounding a sub-point value up before FLOOR.\n    SELECT CAST(ISNULL(n.TuSo / NULLIF(c.TongCent * CAST(100 AS DECIMAL(3,0)), 0), 0) AS DECIMAL(38,6)) AS TienVeThucTra,\n           CAST(FLOOR(ISNULL((n.TuSo - n.TuSo % NULLIF(p.MauDiem, 0)) / NULLIF(p.MauDiem, 0), 0)) AS BIGINT) AS DiemCong\n    FROM (SELECT CAST(ISNULL(@TongTienVe,0) * 100 AS DECIMAL(19,0)) AS VeCent,\n                 CAST((ISNULL(@TongTienVe,0) + ISNULL(@TongTienDoAn,0)) * 100 AS DECIMAL(19,0)) AS TongCent,\n                 CAST(ISNULL(@TienGiamGia,0) * 100 AS DECIMAL(19,0)) AS GiamCent) c\n    CROSS APPLY (SELECT CAST(CASE WHEN c.TongCent <= c.GiamCent OR c.VeCent <= 0 THEN 0\n                           ELSE c.VeCent * (c.TongCent - c.GiamCent) END AS DECIMAL(38,0)) AS TuSo) n\n    CROSS APPLY (SELECT CAST(c.TongCent * CAST(100000 AS DECIMAL(6,0)) AS DECIMAL(25,0)) AS MauDiem) p\n);\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_Create\n(\n    @ActorID INT,\n    @HoTen NVARCHAR(150),\n    @NgaySinh DATE = NULL,\n    @QuocTich NVARCHAR(100) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF @NgaySinh > dbo.fn_HomNay() THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n    INSERT INTO dbo.DIENVIEN (HoTen, NgaySinh, QuocTich) VALUES (@HoTen, @NgaySinh, @QuocTich);\n    SELECT DienVienID, HoTen, NgaySinh, QuocTich FROM dbo.DIENVIEN WHERE DienVienID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_Delete\n(\n    @ActorID INT,\n    @DienVienID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.DIENVIEN WHERE DienVienID = @DienVienID)\n    BEGIN\n        ;THROW 50100, N''Diễn viên không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.PHIM_DIENVIEN WHERE DienVienID = @DienVienID)\n    BEGIN\n        ;THROW 50101, N''Diễn viên đang tham gia phim nên không thể xóa.'', 1;\n    END\n\n    DELETE FROM dbo.DIENVIEN WHERE DienVienID = @DienVienID;\n    SELECT N''Đã xóa diễn viên.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_List\n\n    @ActorID INT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT DienVienID, HoTen, NgaySinh, QuocTich FROM dbo.DIENVIEN ORDER BY HoTen;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_Update\n(\n    @ActorID INT,\n    @DienVienID INT,\n    @HoTen NVARCHAR(150),\n    @NgaySinh DATE = NULL,\n    @QuocTich NVARCHAR(100) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.DIENVIEN WHERE DienVienID = @DienVienID)\n    BEGIN\n        ;THROW 50100, N''Diễn viên không tồn tại.'', 1;\n    END\n\n    IF @NgaySinh > dbo.fn_HomNay() THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n    UPDATE dbo.DIENVIEN SET HoTen = @HoTen, NgaySinh = @NgaySinh, QuocTich = @QuocTich WHERE DienVienID = @DienVienID;\n    SELECT DienVienID, HoTen, NgaySinh, QuocTich FROM dbo.DIENVIEN WHERE DienVienID = @DienVienID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Assignment_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Assignment_Create\n(\n    @ActorID INT,\n    @NguoiDungID INT,\n    @RapID INT,\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''PHANCONG_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    -- Kiểm tra tài khoản phải là QUAN_LY_RAP\n    IF NOT EXISTS (\n        SELECT 1\n        FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro = ''QUAN_LY_RAP''\n    )\n    BEGIN\n        ;THROW 50071, N''Tài khoản được phân công phải có vai trò QUAN_LY_RAP.'', 1;\n    END\n\n    DECLARE @OwnTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n    IF @OwnTran = 1 BEGIN TRANSACTION ELSE SAVE TRANSACTION AssignmentCreate;\n    -- Serialize equivalent creates and updates; do not invent a period-overlap restriction.\n    DECLARE @LockedRows BIGINT;\n    SELECT @LockedRows = COUNT_BIG(*) FROM dbo.PHANCONG_RAP WITH (TABLOCKX, HOLDLOCK);\n    IF @NgayKetThuc < @NgayBatDau THROW 50213, N''Khoảng thời gian phân công không hợp lệ.'', 1;\n    IF EXISTS (SELECT 1 FROM dbo.PHANCONG_RAP WHERE NguoiDungID = @NguoiDungID AND RapID = @RapID\n        AND NgayBatDau = @NgayBatDau AND (NgayKetThuc = @NgayKetThuc OR (NgayKetThuc IS NULL AND @NgayKetThuc IS NULL))\n        AND TrangThai = N''Hiệu lực'') THROW 50401, N''Phân công hoàn toàn giống nhau đã tồn tại.'', 1;\n    INSERT INTO dbo.PHANCONG_RAP (NguoiDungID, RapID, NgayBatDau, NgayKetThuc, TrangThai)\n    VALUES (@NguoiDungID, @RapID, @NgayBatDau, @NgayKetThuc, N''Hiệu lực'');\n\n    DECLARE @NewAssignmentID INT = SCOPE_IDENTITY();\n    IF @OwnTran = 1 COMMIT TRANSACTION;\n\n    SELECT\n        pcr.PhanCongID,\n        pcr.NguoiDungID,\n        nd.HoTen,\n        pcr.RapID,\n        r.TenRap,\n        pcr.NgayBatDau,\n        pcr.NgayKetThuc,\n        pcr.TrangThai\n    FROM dbo.PHANCONG_RAP pcr\n    INNER JOIN dbo.NGUOIDUNG nd ON pcr.NguoiDungID = nd.NguoiDungID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\n    WHERE pcr.PhanCongID = @NewAssignmentID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() = -1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE() = 1\n        BEGIN\n            IF @OwnTran = 1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION AssignmentCreate;\n        END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Assignment_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Assignment_List\n(\n    @ActorID INT,\n    @RapID INT = NULL,\n    @NguoiDungID INT = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''PHANCONG_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    SELECT\n        pcr.PhanCongID,\n        pcr.NguoiDungID,\n        nd.HoTen AS TenQuanLy,\n        nd.Email,\n        pcr.RapID,\n        r.TenRap,\n        r.ThanhPho,\n        pcr.NgayBatDau,\n        pcr.NgayKetThuc,\n        pcr.TrangThai\n    FROM dbo.PHANCONG_RAP pcr\n    INNER JOIN dbo.NGUOIDUNG nd ON pcr.NguoiDungID = nd.NguoiDungID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\n    WHERE (@RapID IS NULL OR pcr.RapID = @RapID)\n      AND (@NguoiDungID IS NULL OR pcr.NguoiDungID = @NguoiDungID)\n    ORDER BY pcr.NgayBatDau DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Cinema_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Cinema_Create\n(\n    @ActorID INT,\n    @TenRap NVARCHAR(150),\n    @DiaChi NVARCHAR(255),\n    @ThanhPho NVARCHAR(100),\n    @SoDienThoai VARCHAR(20) = NULL,\n    @MoTa NVARCHAR(500) = NULL,\n    @NgayHoatDong DATE = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    INSERT INTO dbo.RAPCHIEUPHIM (TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, NgayHoatDong, TrangThai)\n    VALUES (@TenRap, @DiaChi, @ThanhPho, @SoDienThoai, @MoTa, @NgayHoatDong, N''Hoạt động'');\n\n    SELECT RapID, TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, NgayHoatDong, TrangThai\n    FROM dbo.RAPCHIEUPHIM\n    WHERE RapID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Cinema_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Cinema_Delete\n\n    @ActorID INT,\n    @RapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.RAPCHIEUPHIM WHERE RapID = @RapID)\n        THROW 50095, N''Rạp không tồn tại.'', 1;\n    IF EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE RapID = @RapID)\n       OR EXISTS (SELECT 1 FROM dbo.PHANCONG_RAP WHERE RapID = @RapID)\n       OR EXISTS (SELECT 1 FROM dbo.BANGGIA WHERE RapID = @RapID)\n       OR EXISTS (SELECT 1 FROM dbo.HINHANH_RAPCHIEUPHIM WHERE RapID = @RapID)\n        THROW 50096, N''Rạp đã có dữ liệu phụ thuộc; hãy chuyển trạng thái sang Tạm đóng thay vì xóa.'', 1;\n    DELETE dbo.RAPCHIEUPHIM WHERE RapID = @RapID;\n    SELECT N''Đã xóa rạp.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Cinema_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Cinema_Update\n(\n    @ActorID INT,\n    @RapID INT,\n    @TenRap NVARCHAR(150),\n    @DiaChi NVARCHAR(255),\n    @ThanhPho NVARCHAR(100),\n    @SoDienThoai VARCHAR(20),\n    @MoTa NVARCHAR(500),\n    @TrangThai NVARCHAR(50)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    UPDATE dbo.RAPCHIEUPHIM\n    SET TenRap = @TenRap,\n        DiaChi = @DiaChi,\n        ThanhPho = @ThanhPho,\n        SoDienThoai = @SoDienThoai,\n        MoTa = @MoTa,\n        TrangThai = @TrangThai\n    WHERE RapID = @RapID;\n\n    IF @@ROWCOUNT = 0 THROW 50095, N''Rạp không tồn tại.'', 1;\n\n    SELECT RapID, TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, TrangThai\n    FROM dbo.RAPCHIEUPHIM\n    WHERE RapID = @RapID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Dashboard","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/admin/admin_procedures.sql:651 (dbo.sp_Admin_Dashboard)\nCREATE   PROCEDURE dbo.sp_Admin_Dashboard\n\n    @ActorID INT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''XEM_BAO_CAO_TOANHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    SELECT\n        (SELECT COUNT(*) FROM dbo.NGUOIDUNG WHERE TrangThai = N''Hoạt động'') AS TongNguoiDung,\n        (SELECT COUNT(*) FROM dbo.RAPCHIEUPHIM WHERE TrangThai = N''Hoạt động'') AS TongRap,\n        (SELECT COUNT(*) FROM dbo.PHONGCHIEU WHERE TrangThai = N''Hoạt động'') AS TongPhongChieu,\n        (SELECT COUNT(*) FROM dbo.PHIM WHERE TrangThai = N''Đang chiếu'') AS PhimDangChieu,\n        (SELECT COUNT(*) FROM dbo.SUATCHIEU WHERE dbo.fn_NgayKinhDoanh(ThoiGianBatDau) = dbo.fn_HomNay() AND TrangThai<>N''Đã hủy'') AS SuatChieuHomNay,\n        (SELECT COUNT(*) FROM dbo.DONDATVE WHERE TrangThai IN (N''Đã thanh toán'', N''Hoàn thành'')) AS TongDonThanhCong,\n        (SELECT ISNULL(SUM(SoTien), 0) FROM dbo.THANHTOAN WHERE TrangThai = N''Thành công'') AS TongDoanhThuToanThoiGian,\n        (SELECT COUNT(*) FROM dbo.KHIEUNAI WHERE TrangThai = N''Mới'') AS KhieuNaiChuaXuLy;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_Create\n(\n    @ActorID INT,\n    @TenTheLoai NVARCHAR(100)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF EXISTS (SELECT 1 FROM dbo.THELOAI WHERE TenTheLoai = @TenTheLoai)\n    BEGIN\n        ;THROW 50097, N''Thể loại đã tồn tại.'', 1;\n    END\n\n    INSERT INTO dbo.THELOAI (TenTheLoai) VALUES (@TenTheLoai);\n    SELECT TheLoaiID, TenTheLoai FROM dbo.THELOAI WHERE TheLoaiID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_Delete\n(\n    @ActorID INT,\n    @TheLoaiID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.THELOAI WHERE TheLoaiID = @TheLoaiID)\n    BEGIN\n        ;THROW 50098, N''Thể loại không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.PHIM_THELOAI WHERE TheLoaiID = @TheLoaiID)\n    BEGIN\n        ;THROW 50099, N''Thể loại đang được gán cho phim nên không thể xóa.'', 1;\n    END\n\n    DELETE FROM dbo.THELOAI WHERE TheLoaiID = @TheLoaiID;\n    SELECT N''Đã xóa thể loại.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    EXEC dbo.sp_Genre_List;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_Update\n(\n    @ActorID INT,\n    @TheLoaiID INT,\n    @TenTheLoai NVARCHAR(100)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.THELOAI WHERE TheLoaiID = @TheLoaiID)\n    BEGIN\n        ;THROW 50098, N''Thể loại không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.THELOAI WHERE TenTheLoai = @TenTheLoai AND TheLoaiID <> @TheLoaiID)\n    BEGIN\n        ;THROW 50097, N''Thể loại đã tồn tại.'', 1;\n    END\n\n    UPDATE dbo.THELOAI SET TenTheLoai = @TenTheLoai WHERE TheLoaiID = @TheLoaiID;\n    SELECT TheLoaiID, TenTheLoai FROM dbo.THELOAI WHERE TheLoaiID = @TheLoaiID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Movie_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Movie_Create\n(\n    @ActorID INT,\n    @TenPhim NVARCHAR(255),\n    @ThoiLuong INT,\n    @NgayKhoiChieu DATE,\n    @NgayKetThuc DATE = NULL,\n    @NgonNgu NVARCHAR(100) = NULL,\n    @PhuDe NVARCHAR(100) = NULL,\n    @DoTuoi NVARCHAR(20) = NULL,\n    @DaoDien NVARCHAR(150) = NULL,\n    @MoTa NVARCHAR(MAX) = NULL,\n    @PosterURL NVARCHAR(500) = NULL,\n    @TrailerURL NVARCHAR(500) = NULL,\n    @TheLoaiIdList VARCHAR(MAX) = NULL,\n    @NewPhimID INT OUTPUT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        INSERT INTO dbo.PHIM (TenPhim, ThoiLuong, NgayKhoiChieu, NgayKetThuc, NgonNgu, PhuDe, DoTuoi, DaoDien, MoTa, PosterURL, TrailerURL, TrangThai)\n        VALUES (@TenPhim, @ThoiLuong, @NgayKhoiChieu, @NgayKetThuc, @NgonNgu, @PhuDe, @DoTuoi, @DaoDien, @MoTa, @PosterURL, @TrailerURL, N''Đang chiếu'');\n\n        SET @NewPhimID = SCOPE_IDENTITY();\n\n        IF @TheLoaiIdList IS NOT NULL\n        BEGIN\n            INSERT INTO dbo.PHIM_THELOAI (PhimID, TheLoaiID)\n            SELECT DISTINCT @NewPhimID, CAST(value AS INT)\n            FROM STRING_SPLIT(@TheLoaiIdList, '','')\n            WHERE LTRIM(RTRIM(value)) <> '''';\n        END\n\n        COMMIT TRANSACTION;\n\n        EXEC dbo.sp_Movie_GetDetail @PhimID = @NewPhimID;\n\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Movie_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Movie_Delete\n(\n    @ActorID INT,\n    @PhimID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.PHIM WHERE PhimID = @PhimID)\n    BEGIN\n        ;THROW 50102, N''Phim không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.SUATCHIEU WHERE PhimID = @PhimID)\n       OR EXISTS (SELECT 1 FROM dbo.DANHGIAPHIM WHERE PhimID = @PhimID)\n    BEGIN\n        ;THROW 50104, N''Phim đã có suất chiếu hoặc đánh giá. Hãy chuyển trạng thái sang Ngừng chiếu thay vì xóa.'', 1;\n    END\n\n    DELETE FROM dbo.PHIM WHERE PhimID = @PhimID;\n    SELECT N''Đã xóa phim.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Movie_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Movie_Update\n(\n    @ActorID INT,\n    @PhimID INT,\n    @TenPhim NVARCHAR(255),\n    @ThoiLuong INT,\n    @NgayKhoiChieu DATE,\n    @NgayKetThuc DATE = NULL,\n    @NgonNgu NVARCHAR(100) = NULL,\n    @PhuDe NVARCHAR(100) = NULL,\n    @DoTuoi NVARCHAR(20) = NULL,\n    @DaoDien NVARCHAR(150) = NULL,\n    @MoTa NVARCHAR(MAX) = NULL,\n    @PosterURL NVARCHAR(500) = NULL,\n    @TrailerURL NVARCHAR(500) = NULL,\n    @TrangThai NVARCHAR(50),\n    @TheLoaiIdList VARCHAR(MAX) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        UPDATE dbo.PHIM\n        SET TenPhim = @TenPhim,\n            ThoiLuong = @ThoiLuong,\n            NgayKhoiChieu = @NgayKhoiChieu,\n            NgayKetThuc = @NgayKetThuc,\n            NgonNgu = @NgonNgu,\n            PhuDe = @PhuDe,\n            DoTuoi = @DoTuoi,\n            DaoDien = @DaoDien,\n            MoTa = @MoTa,\n            PosterURL = @PosterURL,\n            TrailerURL = @TrailerURL,\n            TrangThai = @TrangThai\n        WHERE PhimID = @PhimID;\n\n        IF @@ROWCOUNT = 0 THROW 50102, N''Phim không tồn tại.'', 1;\n\n        IF @TheLoaiIdList IS NOT NULL\n        BEGIN\n            DELETE FROM dbo.PHIM_THELOAI WHERE PhimID = @PhimID;\n\n            INSERT INTO dbo.PHIM_THELOAI (PhimID, TheLoaiID)\n            SELECT DISTINCT @PhimID, CAST(value AS INT)\n            FROM STRING_SPLIT(@TheLoaiIdList, '','')\n            WHERE LTRIM(RTRIM(value)) <> '''';\n        END\n\n        COMMIT TRANSACTION;\n\n        EXEC dbo.sp_Movie_GetDetail @PhimID = @PhimID;\n\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_MovieActor_Set","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_MovieActor_Set\n(\n    @ActorID INT,\n    @PhimID INT,\n    @DanhSachJson NVARCHAR(MAX)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SET XACT_ABORT ON;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.PHIM WHERE PhimID = @PhimID)\n    BEGIN\n        ;THROW 50102, N''Phim không tồn tại.'', 1;\n    END\n\n    IF @DanhSachJson IS NULL OR ISJSON(@DanhSachJson) <> 1\n    BEGIN\n        ;THROW 50103, N''Danh sách diễn viên phải là JSON hợp lệ.'', 1;\n    END\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        DELETE FROM dbo.PHIM_DIENVIEN WHERE PhimID = @PhimID;\n\n        INSERT INTO dbo.PHIM_DIENVIEN (PhimID, DienVienID, VaiDien)\n        SELECT @PhimID, j.DienVienID, MAX(j.VaiDien)\n        FROM OPENJSON(@DanhSachJson)\n             WITH (DienVienID INT ''$.DienVienID'', VaiDien NVARCHAR(150) ''$.VaiDien'') j\n        INNER JOIN dbo.DIENVIEN dv ON dv.DienVienID = j.DienVienID\n        GROUP BY j.DienVienID;\n\n        COMMIT TRANSACTION;\n\n        SELECT pd.PhimID, dv.DienVienID, dv.HoTen, pd.VaiDien\n        FROM dbo.PHIM_DIENVIEN pd\n        INNER JOIN dbo.DIENVIEN dv ON dv.DienVienID = pd.DienVienID\n        WHERE pd.PhimID = @PhimID;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_Create\n(\n    @ActorID INT,\n    @MaQuyen VARCHAR(50),\n    @TenQuyen NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF EXISTS (SELECT 1 FROM dbo.QUYEN WHERE MaQuyen = @MaQuyen)\n    BEGIN\n        ;THROW 50092, N''Mã quyền đã tồn tại.'', 1;\n    END\n\n    INSERT INTO dbo.QUYEN (MaQuyen, TenQuyen, MoTa) VALUES (@MaQuyen, @TenQuyen, @MoTa);\n    SELECT QuyenID, MaQuyen, TenQuyen, MoTa FROM dbo.QUYEN WHERE QuyenID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_Delete\n(\n    @ActorID INT,\n    @QuyenID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.QUYEN WHERE QuyenID = @QuyenID)\n    BEGIN\n        ;THROW 50093, N''Quyền không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.VAITRO_QUYEN WHERE QuyenID = @QuyenID)\n    BEGIN\n        ;THROW 50094, N''Quyền đang được gán cho vai trò nên không thể xóa.'', 1;\n    END\n\n    DELETE FROM dbo.QUYEN WHERE QuyenID = @QuyenID;\n    SELECT N''Đã xóa quyền.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_List\n\n    @ActorID INT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT QuyenID, MaQuyen, TenQuyen, MoTa FROM dbo.QUYEN ORDER BY MaQuyen;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_Update\n(\n    @ActorID INT,\n    @QuyenID INT,\n    @TenQuyen NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.QUYEN WHERE QuyenID = @QuyenID)\n    BEGIN\n        ;THROW 50093, N''Quyền không tồn tại.'', 1;\n    END\n\n    UPDATE dbo.QUYEN SET TenQuyen = @TenQuyen, MoTa = @MoTa WHERE QuyenID = @QuyenID;\n    SELECT QuyenID, MaQuyen, TenQuyen, MoTa FROM dbo.QUYEN WHERE QuyenID = @QuyenID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Product_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Product_Create\n(\n    @ActorID INT,\n    @TenSanPham NVARCHAR(150),\n    @LoaiSanPham NVARCHAR(50),\n    @Gia DECIMAL(18,2),\n    @MoTa NVARCHAR(255) = NULL,\n    @HinhAnh NVARCHAR(500) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    INSERT INTO dbo.SANPHAM (TenSanPham, LoaiSanPham, Gia, MoTa, HinhAnh, TrangThai)\n    VALUES (@TenSanPham, @LoaiSanPham, @Gia, @MoTa, @HinhAnh, N''Đang bán'');\n\n    SELECT SanPhamID, TenSanPham, LoaiSanPham, Gia, MoTa, HinhAnh, TrangThai\n    FROM dbo.SANPHAM\n    WHERE SanPhamID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Product_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Product_Delete\n(\n    @ActorID INT,\n    @SanPhamID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.SANPHAM WHERE SanPhamID = @SanPhamID)\n    BEGIN\n        ;THROW 50105, N''Sản phẩm không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.CHITIETDOAN WHERE SanPhamID = @SanPhamID)\n    BEGIN\n        ;THROW 50106, N''Sản phẩm đã có trong đơn hàng. Hãy chuyển trạng thái sang Ngừng bán thay vì xóa.'', 1;\n    END\n\n    DELETE FROM dbo.SANPHAM WHERE SanPhamID = @SanPhamID;\n    SELECT N''Đã xóa sản phẩm.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Product_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Product_Update\n(\n    @ActorID INT,\n    @SanPhamID INT,\n    @TenSanPham NVARCHAR(150),\n    @LoaiSanPham NVARCHAR(50),\n    @Gia DECIMAL(18,2),\n    @MoTa NVARCHAR(255),\n    @HinhAnh NVARCHAR(500),\n    @TrangThai NVARCHAR(50)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    UPDATE dbo.SANPHAM\n    SET TenSanPham = @TenSanPham,\n        LoaiSanPham = @LoaiSanPham,\n        Gia = @Gia,\n        MoTa = @MoTa,\n        HinhAnh = @HinhAnh,\n        TrangThai = @TrangThai\n    WHERE SanPhamID = @SanPhamID;\n\n    IF @@ROWCOUNT = 0 THROW 50105, N''Sản phẩm không tồn tại.'', 1;\n\n    SELECT SanPhamID, TenSanPham, LoaiSanPham, Gia, MoTa, HinhAnh, TrangThai\n    FROM dbo.SANPHAM\n    WHERE SanPhamID = @SanPhamID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_Create\n(\n    @ActorID INT,\n    @MaCode VARCHAR(50),\n    @MoTa NVARCHAR(255) = NULL,\n    @LoaiGiamGia NVARCHAR(20),\n    @GiaTriGiam DECIMAL(18,2),\n    @DonHangToiThieu DECIMAL(18,2) = 0,\n    @GiamToiDa DECIMAL(18,2) = NULL,\n    @NgayBatDau DATETIME2,\n    @NgayKetThuc DATETIME2,\n    @SoLuong INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF EXISTS (SELECT 1 FROM dbo.KHUYENMAI WHERE MaCode = @MaCode)\n    BEGIN\n        ;THROW 50072, N''Mã khuyến mãi đã tồn tại.'', 1;\n    END\n\n    INSERT INTO dbo.KHUYENMAI (MaCode, MoTa, LoaiGiamGia, GiaTriGiam, DonHangToiThieu, GiamToiDa, NgayBatDau, NgayKetThuc, SoLuong, SoLuongDaDung, TrangThai)\n    VALUES (@MaCode, @MoTa, @LoaiGiamGia, @GiaTriGiam, @DonHangToiThieu, @GiamToiDa, @NgayBatDau, @NgayKetThuc, @SoLuong, 0, N''Hoạt động'');\n\n    SELECT [KhuyenMaiID], [MaCode], [MoTa], [LoaiGiamGia], [GiaTriGiam], [DonHangToiThieu], [GiamToiDa], [NgayBatDau], [NgayKetThuc], [SoLuong], [SoLuongDaDung], [TrangThai] FROM dbo.KHUYENMAI WHERE KhuyenMaiID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_Delete\n(\n    @ActorID INT,\n    @KhuyenMaiID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.KHUYENMAI WHERE KhuyenMaiID = @KhuyenMaiID)\n    BEGIN\n        ;THROW 50107, N''Khuyến mãi không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.DONDATVE WHERE KhuyenMaiID = @KhuyenMaiID)\n    BEGIN\n        ;THROW 50108, N''Khuyến mãi đã được dùng trong đơn hàng. Hãy chuyển trạng thái sang Tạm dừng thay vì xóa.'', 1;\n    END\n\n    DELETE FROM dbo.KHUYENMAI WHERE KhuyenMaiID = @KhuyenMaiID;\n    SELECT N''Đã xóa khuyến mãi.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_List\n\n    @ActorID INT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    SELECT\n        KhuyenMaiID,\n        MaCode,\n        MoTa,\n        LoaiGiamGia,\n        GiaTriGiam,\n        DonHangToiThieu,\n        GiamToiDa,\n        NgayBatDau,\n        NgayKetThuc,\n        SoLuong,\n        SoLuongDaDung,\n        TrangThai\n    FROM dbo.KHUYENMAI\n    ORDER BY NgayBatDau DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_Update\n(\n    @ActorID INT,\n    @KhuyenMaiID INT,\n    @MoTa NVARCHAR(255) = NULL,\n    @LoaiGiamGia NVARCHAR(20),\n    @GiaTriGiam DECIMAL(18,2),\n    @DonHangToiThieu DECIMAL(18,2) = 0,\n    @GiamToiDa DECIMAL(18,2) = NULL,\n    @NgayBatDau DATETIME2,\n    @NgayKetThuc DATETIME2,\n    @SoLuong INT,\n    @TrangThai NVARCHAR(50)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.KHUYENMAI WHERE KhuyenMaiID = @KhuyenMaiID)\n    BEGIN\n        ;THROW 50107, N''Khuyến mãi không tồn tại.'', 1;\n    END\n\n    UPDATE dbo.KHUYENMAI\n    SET MoTa = @MoTa,\n        LoaiGiamGia = @LoaiGiamGia,\n        GiaTriGiam = @GiaTriGiam,\n        DonHangToiThieu = @DonHangToiThieu,\n        GiamToiDa = @GiamToiDa,\n        NgayBatDau = @NgayBatDau,\n        NgayKetThuc = @NgayKetThuc,\n        SoLuong = @SoLuong,\n        TrangThai = @TrangThai\n    WHERE KhuyenMaiID = @KhuyenMaiID;\n\n    SELECT KhuyenMaiID, MaCode, MoTa, LoaiGiamGia, GiaTriGiam, DonHangToiThieu, GiamToiDa,\n           NgayBatDau, NgayKetThuc, SoLuong, SoLuongDaDung, TrangThai\n    FROM dbo.KHUYENMAI WHERE KhuyenMaiID = @KhuyenMaiID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Report_Revenue","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Report_Revenue\n(\n    @ActorID INT,\n    @TuNgay DATE = NULL,\n    @DenNgay DATE = NULL,\n    @RapID INT = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''XEM_BAO_CAO_TOANHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    -- Doanh thu chỉ tính THANHTOAN có TrangThai = ''Thành công'', theo ngày thanh toán\n    CREATE TABLE #DonDaThu (\n        DonDatVeID INT PRIMARY KEY,\n        RapID INT NOT NULL,\n        TongTienVe DECIMAL(18,2),\n        TongTienDoAn DECIMAL(18,2),\n        TienGiamGia DECIMAL(18,2),\n        TienDaThu DECIMAL(18,2),\n        SoVe INT\n    );\n\n    INSERT INTO #DonDaThu (DonDatVeID, RapID, TongTienVe, TongTienDoAn, TienGiamGia, TienDaThu, SoVe)\n    SELECT\n        ddv.DonDatVeID,\n        pc.RapID,\n        ddv.TongTienVe,\n        ddv.TongTienDoAn,\n        ddv.TienGiamGia,\n        SUM(tt.SoTien),\n        (SELECT COUNT(*) FROM dbo.CHITIETVE cv\n         WHERE cv.DonDatVeID = ddv.DonDatVeID AND cv.TrangThai <> N''Đã hủy'')\n    FROM dbo.DONDATVE ddv\n    INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n    INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n    INNER JOIN dbo.THANHTOAN tt ON tt.DonDatVeID = ddv.DonDatVeID AND tt.TrangThai = N''Thành công''\n    WHERE (@RapID IS NULL OR pc.RapID = @RapID)\n    GROUP BY ddv.DonDatVeID, pc.RapID, ddv.TongTienVe, ddv.TongTienDoAn, ddv.TienGiamGia\n    HAVING (@TuNgay IS NULL OR dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))) >= @TuNgay)\n       AND (@DenNgay IS NULL OR dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))) <= @DenNgay);\n\n    -- Recordset 1: Doanh thu theo từng rạp\n    SELECT\n        r.RapID,\n        r.TenRap,\n        r.ThanhPho,\n        COUNT(d.DonDatVeID) AS SoDon,\n        ISNULL(SUM(d.SoVe), 0) AS SoVeBan,\n        ISNULL(SUM(d.TongTienVe), 0) AS DoanhThuVe,\n        ISNULL(SUM(d.TongTienDoAn), 0) AS DoanhThuDoAn,\n        ISNULL(SUM(d.TienGiamGia), 0) AS TongTienGiam,\n        ISNULL(SUM(d.TienDaThu), 0) AS DoanhThuThucTe\n    FROM dbo.RAPCHIEUPHIM r\n    LEFT JOIN #DonDaThu d ON d.RapID = r.RapID\n    WHERE (@RapID IS NULL OR r.RapID = @RapID)\n    GROUP BY r.RapID, r.TenRap, r.ThanhPho;\n\n    -- Recordset 2: Tổng hợp toàn hệ thống\n    SELECT\n        COUNT(DonDatVeID) AS TongSoDonToanHeThong,\n        ISNULL(SUM(SoVe), 0) AS TongSoVeBan,\n        ISNULL(SUM(TongTienVe), 0) AS TongDoanhThuVe,\n        ISNULL(SUM(TongTienDoAn), 0) AS TongDoanhThuDoAn,\n        ISNULL(SUM(TienGiamGia), 0) AS TongTienGiam,\n        ISNULL(SUM(TienDaThu), 0) AS TongDoanhThuThucTe\n    FROM #DonDaThu;\n\n    DROP TABLE #DonDaThu;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_Create\n(\n    @ActorID INT,\n    @MaVaiTro VARCHAR(50),\n    @TenVaiTro NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_VAITRO'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    INSERT INTO dbo.VAITRO (MaVaiTro, TenVaiTro, MoTa)\n    VALUES (@MaVaiTro, @TenVaiTro, @MoTa);\n\n    SELECT VaiTroID, MaVaiTro, TenVaiTro, MoTa FROM dbo.VAITRO WHERE VaiTroID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_Delete\n(\n    @ActorID INT,\n    @VaiTroID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_VAITRO'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.VAITRO WHERE VaiTroID = @VaiTroID)\n    BEGIN\n        ;THROW 50090, N''Vai trò không tồn tại.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE VaiTroID = @VaiTroID)\n       OR EXISTS (SELECT 1 FROM dbo.VAITRO_QUYEN WHERE VaiTroID = @VaiTroID)\n    BEGIN\n        ;THROW 50091, N''Vai trò đang được gán cho người dùng hoặc quyền nên không thể xóa.'', 1;\n    END\n\n    DELETE FROM dbo.VAITRO WHERE VaiTroID = @VaiTroID;\n    SELECT N''Đã xóa vai trò.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_List\n\n    @ActorID INT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_VAITRO'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT VaiTroID, MaVaiTro, TenVaiTro, MoTa FROM dbo.VAITRO ORDER BY VaiTroID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_Update\n(\n    @ActorID INT,\n    @VaiTroID INT,\n    @TenVaiTro NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_VAITRO'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.VAITRO WHERE VaiTroID = @VaiTroID)\n    BEGIN\n        ;THROW 50090, N''Vai trò không tồn tại.'', 1;\n    END\n\n    UPDATE dbo.VAITRO SET TenVaiTro = @TenVaiTro, MoTa = @MoTa WHERE VaiTroID = @VaiTroID;\n\n    SELECT VaiTroID, MaVaiTro, TenVaiTro, MoTa FROM dbo.VAITRO WHERE VaiTroID = @VaiTroID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_RolePermission_Set","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/admin/admin_procedures.sql:156 (dbo.sp_Admin_RolePermission_Set)\nCREATE   PROCEDURE dbo.sp_Admin_RolePermission_Set\n(\n    @ActorID INT,\n    @VaiTroID INT,\n    @QuyenIdList VARCHAR(MAX) -- ''1,2,3,4''\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        DELETE FROM dbo.VAITRO_QUYEN WHERE VaiTroID = @VaiTroID;\n\n        INSERT INTO dbo.VAITRO_QUYEN (VaiTroID, QuyenID, NgayGan)\n        SELECT DISTINCT @VaiTroID, CAST(value AS INT), dbo.fn_BayGio()\n        FROM STRING_SPLIT(@QuyenIdList, '','')\n        WHERE LTRIM(RTRIM(value)) <> '''';\n\n        COMMIT TRANSACTION;\n\n        SELECT vq.VaiTroID, q.QuyenID, q.MaQuyen, q.TenQuyen\n        FROM dbo.VAITRO_QUYEN vq\n        INNER JOIN dbo.QUYEN q ON vq.QuyenID = q.QuyenID\n        WHERE vq.VaiTroID = @VaiTroID;\n\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_User_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/admin/admin_procedures.sql:75 (dbo.sp_Admin_User_Create)\nCREATE   PROCEDURE dbo.sp_Admin_User_Create\n(\n    @ActorID INT,\n    @HoTen NVARCHAR(100),\n    @Email VARCHAR(150),\n    @MatKhauHash VARCHAR(255),\n    @SoDienThoai VARCHAR(20) = NULL,\n    @VaiTroID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_NGUOIDUNG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @OwnTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n    IF @OwnTran = 1 BEGIN TRANSACTION ELSE SAVE TRANSACTION AdminCreateUser;\n    IF EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE Email = @Email)\n    BEGIN\n        ;THROW 50070, N''Email đã tồn tại.'', 1;\n    END\n\n    INSERT INTO dbo.NGUOIDUNG (VaiTroID, HoTen, Email, MatKhau, SoDienThoai, NgayTao, TrangThai)\n    VALUES (@VaiTroID, @HoTen, @Email, @MatKhauHash, @SoDienThoai, dbo.fn_BayGio(), N''Hoạt động'');\n\n    DECLARE @NewUserID INT = SCOPE_IDENTITY();\n    IF EXISTS (SELECT 1 FROM dbo.VAITRO WITH (HOLDLOCK) WHERE VaiTroID = @VaiTroID AND MaVaiTro = ''KHACH_HANG'')\n        INSERT dbo.HOSOKHACHHANG (NguoiDungID, NgaySinh, GioiTinh, DiemTichLuy)\n        VALUES (@NewUserID, NULL, NULL, 0);\n\n    IF @OwnTran = 1 COMMIT TRANSACTION;\n\n    SELECT\n        nd.NguoiDungID,\n        nd.HoTen,\n        nd.Email,\n        nd.SoDienThoai,\n        vt.MaVaiTro,\n        vt.TenVaiTro,\n        nd.TrangThai\n    FROM dbo.NGUOIDUNG nd\n    INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n    WHERE nd.NguoiDungID = @NewUserID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() = -1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE() = 1\n        BEGIN\n            IF @OwnTran = 1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION AdminCreateUser;\n        END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_User_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_User_List\n(\n    @ActorID INT,\n    @VaiTroID INT = NULL,\n    @TrangThai NVARCHAR(50) = NULL,\n    @SearchTerm NVARCHAR(100) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_NGUOIDUNG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    SELECT\n        nd.NguoiDungID,\n        nd.HoTen,\n        nd.Email,\n        nd.SoDienThoai,\n        nd.NgayTao,\n        nd.TrangThai,\n        vt.VaiTroID,\n        vt.MaVaiTro,\n        vt.TenVaiTro,\n        hk.DiemTichLuy\n    FROM dbo.NGUOIDUNG nd\n    INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n    LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\n    WHERE (@VaiTroID IS NULL OR nd.VaiTroID = @VaiTroID)\n      AND (@TrangThai IS NULL OR nd.TrangThai = @TrangThai)\n      AND (@SearchTerm IS NULL OR nd.HoTen LIKE ''%'' + @SearchTerm + ''%'' OR nd.Email LIKE ''%'' + @SearchTerm + ''%'' OR nd.SoDienThoai LIKE ''%'' + @SearchTerm + ''%'')\n    ORDER BY nd.NgayTao DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_User_UpdateStatus","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_User_UpdateStatus\n(\n    @ActorID INT,\n    @NguoiDungID INT,\n    @TrangThai NVARCHAR(50) -- ''Hoạt động'', ''Bị khóa''\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_NGUOIDUNG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    UPDATE dbo.NGUOIDUNG\n    SET TrangThai = @TrangThai\n    WHERE NguoiDungID = @NguoiDungID;\n\n    IF @@ROWCOUNT = 0 THROW 50403, N''Người dùng không tồn tại.'', 1;\n\n    SELECT NguoiDungID, HoTen, Email, TrangThai FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Auth_Login","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/auth/auth_procedures.sql:132 (dbo.sp_Auth_Login)\r\nCREATE   PROCEDURE dbo.sp_Auth_Login\r\n(\r\n    @Email VARCHAR(150)\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    -- Mật khẩu được băm (bcrypt) và so sánh ở backend. Thủ tục này chỉ trả về hash để backend đối chiếu.\r\n    -- Recordset 1: 0 dòng nếu email không tồn tại. Recordset 2, 3 chỉ có dữ liệu khi tài khoản đang hoạt động.\r\n\r\n    DECLARE @NguoiDungID INT;\r\n    DECLARE @VaiTroID INT;\r\n    DECLARE @TrangThai NVARCHAR(50);\r\n\r\n    SELECT @NguoiDungID = NguoiDungID, @VaiTroID = VaiTroID, @TrangThai = TrangThai\r\n    FROM dbo.NGUOIDUNG\r\n    WHERE Email = @Email;\r\n\r\n    -- Recordset 1: Thông tin người dùng + hash mật khẩu\r\n    SELECT\r\n        nd.NguoiDungID,\r\n        nd.HoTen,\r\n        nd.Email,\r\n        nd.SoDienThoai,\r\n        nd.MatKhau AS MatKhauHash,\r\n        nd.TrangThai,\r\n        vt.VaiTroID,\r\n        vt.MaVaiTro,\r\n        vt.TenVaiTro,\r\n        hk.DiemTichLuy\r\n    FROM dbo.NGUOIDUNG nd\r\n    INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\r\n    LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\r\n    WHERE nd.NguoiDungID = @NguoiDungID;\r\n\r\n    -- Recordset 2: Danh sách quyền (Permissions)\r\n    SELECT DISTINCT q.QuyenID, q.MaQuyen, q.TenQuyen\r\n    FROM dbo.VAITRO_QUYEN vq\r\n    INNER JOIN dbo.QUYEN q ON vq.QuyenID = q.QuyenID\r\n    WHERE vq.VaiTroID = @VaiTroID\r\n      AND @TrangThai = N''Hoạt động'';\r\n\r\n    -- Recordset 3: Danh sách rạp được phân công còn hiệu lực (Quản lý rạp)\r\n    SELECT\r\n        pcr.RapID,\r\n        r.TenRap,\r\n        r.ThanhPho,\r\n        pcr.NgayBatDau,\r\n        pcr.NgayKetThuc\r\n    FROM dbo.PHANCONG_RAP pcr\r\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\r\n    WHERE pcr.NguoiDungID = @NguoiDungID\r\n      AND @TrangThai = N''Hoạt động''\r\n      AND pcr.TrangThai = N''Hiệu lực''\r\n      AND dbo.fn_HomNay() >= pcr.NgayBatDau\r\n      AND (pcr.NgayKetThuc IS NULL OR dbo.fn_HomNay() <= pcr.NgayKetThuc);\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Auth_RegisterCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/auth/auth_procedures.sql:18 (dbo.sp_Auth_RegisterCustomer)\r\nCREATE   PROCEDURE dbo.sp_Auth_RegisterCustomer\r\n(\r\n    @HoTen NVARCHAR(100),\r\n    @Email VARCHAR(150),\r\n    @MatKhauHash VARCHAR(255),\r\n    @SoDienThoai VARCHAR(20) = NULL,\r\n    @NgaySinh DATE = NULL,\r\n    @GioiTinh NVARCHAR(10) = NULL,\r\n    @NewUserId INT OUTPUT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\n    IF @NgaySinh > dbo.fn_HomNay() THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n\r\n    -- Transaction lồng nhau đúng kỹ thuật:\r\n    --  * Gọi độc lập (@@TRANCOUNT = 0): thủ tục tự BEGIN/COMMIT/ROLLBACK.\r\n    --  * Gọi trong transaction của bên gọi: dùng SAVE TRANSACTION, khi lỗi chỉ rollback phần của mình,\r\n    --    không hủy transaction ngoài.\r\n    DECLARE @TuMoTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\r\n\r\n    BEGIN TRY\r\n        IF @TuMoTran = 1\r\n            BEGIN TRANSACTION;\r\n        ELSE\r\n            SAVE TRANSACTION sp_Auth_RegisterCustomer;\r\n\r\n        -- 1. Kiểm tra email đã tồn tại chưa\r\n        IF EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE Email = @Email)\r\n        BEGIN\r\n            ;THROW 50010, N''Email này đã được sử dụng trong hệ thống.'', 1;\r\n        END\r\n\r\n        -- 2. Kiểm tra số điện thoại (nếu có)\r\n        IF @SoDienThoai IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE SoDienThoai = @SoDienThoai)\r\n        BEGIN\r\n            ;THROW 50011, N''Số điện thoại này đã được sử dụng trong hệ thống.'', 1;\r\n        END\r\n\r\n        -- 3. Lấy VaiTroID của vai trò KHACH_HANG\r\n        DECLARE @VaiTroID INT;\r\n        SELECT @VaiTroID = VaiTroID FROM dbo.VAITRO WHERE MaVaiTro = ''KHACH_HANG'';\r\n\r\n        IF @VaiTroID IS NULL\r\n        BEGIN\r\n            ;THROW 50012, N''Vai trò KHACH_HANG chưa được cấu hình.'', 1;\r\n        END\r\n\r\n        -- 4. Thêm tài khoản mới vào NGUOIDUNG\r\n        INSERT INTO dbo.NGUOIDUNG (VaiTroID, HoTen, Email, MatKhau, SoDienThoai, NgayTao, TrangThai)\r\n        VALUES (@VaiTroID, @HoTen, @Email, @MatKhauHash, @SoDienThoai, dbo.fn_BayGio(), N''Hoạt động'');\r\n\r\n        SET @NewUserId = SCOPE_IDENTITY();\r\n\r\n        -- 5. Tạo bản ghi HOSOKHACHHANG tương ứng\r\n        INSERT INTO dbo.HOSOKHACHHANG (NguoiDungID, NgaySinh, GioiTinh, DiemTichLuy)\r\n        VALUES (@NewUserId, @NgaySinh, @GioiTinh, 0);\r\n\r\n        IF @TuMoTran = 1\r\n            COMMIT TRANSACTION;\r\n\r\n        -- Trả về thông tin tài khoản vừa tạo\r\n        SELECT\r\n            nd.NguoiDungID,\r\n            nd.HoTen,\r\n            nd.Email,\r\n            nd.SoDienThoai,\r\n            vt.MaVaiTro,\r\n            vt.TenVaiTro,\r\n            nd.TrangThai,\r\n            hk.DiemTichLuy\r\n        FROM dbo.NGUOIDUNG nd\r\n        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\r\n        LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\r\n        WHERE nd.NguoiDungID = @NewUserId;\r\n\r\n    END TRY\r\n    BEGIN CATCH\r\n        DECLARE @LoiSo INT = ERROR_NUMBER();\r\n        DECLARE @LoiMsg NVARCHAR(2048) = ERROR_MESSAGE();\r\n\r\n        SET @NewUserId = NULL;\r\n\r\n        IF XACT_STATE() = -1\r\n        BEGIN\r\n            -- Transaction đã không thể commit: bắt buộc rollback toàn bộ\r\n            ROLLBACK TRANSACTION;\r\n        END\r\n        ELSE IF XACT_STATE() = 1\r\n        BEGIN\r\n            IF @TuMoTran = 1\r\n                ROLLBACK TRANSACTION;\r\n            ELSE\r\n                ROLLBACK TRANSACTION sp_Auth_RegisterCustomer;\r\n        END\r\n\r\n        -- Hai yêu cầu đăng ký đồng thời có thể cùng qua bước kiểm tra; UNIQUE là chốt chặn cuối cùng\r\n        IF @LoiSo IN (2601, 2627) AND @LoiMsg LIKE N''%UQ_NGUOIDUNG_Email%''\r\n        BEGIN\r\n            ;THROW 50010, N''Email này đã được sử dụng trong hệ thống.'', 1;\r\n        END\r\n        IF @LoiSo IN (2601, 2627) AND @LoiMsg LIKE N''%UQ_NGUOIDUNG_SoDienThoai%''\r\n        BEGIN\r\n            ;THROW 50011, N''Số điện thoại này đã được sử dụng trong hệ thống.'', 1;\r\n        END\r\n\r\n        ;THROW;\r\n    END CATCH\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Booking_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/012_booking_limits_and_pricing.sql:253 (dbo.sp_Booking_Create)\nCREATE   PROCEDURE dbo.sp_Booking_Create\n(\n    @NguoiDungID INT,\n    @SuatChieuID INT,\n    @MaKhuyenMai VARCHAR(50) = NULL,\n    -- Danh sách ID ghế ngăn cách bởi dấu phẩy, ví dụ ''101,102''\n    @DanhSachGheId VARCHAR(MAX),\n    -- Chuỗi JSON danh sách đồ ăn: ''[{\"SanPhamID\":1,\"SoLuong\":2},{\"SanPhamID\":2,\"SoLuong\":1}]''\n    @DanhSachDoAnJson NVARCHAR(MAX) = NULL,\n    @NewDonDatVeID INT OUTPUT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''DAT_VE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    -- Gọi được cả độc lập lẫn trong transaction của bên gọi: chỉ COMMIT/ROLLBACK khi tự mở transaction,\n    -- ngược lại dùng SAVE TRANSACTION và chỉ rollback phần của mình.\n    DECLARE @TuMoTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n\n    BEGIN TRY\n        -- Sử dụng mức cô lập cao nhất để ngăn race condition (đặt trùng cùng 1 ghế)\n        IF @TuMoTran = 1\n            BEGIN TRANSACTION;\n        ELSE\n            SAVE TRANSACTION sp_Booking_Create;\n\n        -- 1. Kiểm tra tài khoản khách hàng hợp lệ. Khóa dòng khách (UPDLOCK, HOLDLOCK, gán vào biến, không phát\n        -- result set) TRƯỚC khóa suất chiếu: các đơn song song của cùng một khách bị xếp hàng, nên giới hạn số đơn\n        -- đang giữ chỗ bên dưới không thể bị vượt bằng race. Thứ tự khóa luôn là khách -> suất chiếu -> ghế.\n        DECLARE @KhoaKhach INT;\n        SELECT @KhoaKhach = NguoiDungID\n        FROM dbo.NGUOIDUNG WITH (UPDLOCK, HOLDLOCK)\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'';\n\n        IF @KhoaKhach IS NULL\n        BEGIN\n            ;THROW 50020, N''Tài khoản người dùng không tồn tại hoặc đã bị khóa.'', 1;\n        END\n\n        -- 1b. Tối đa fn_GioiHanDonDangGiu() đơn đang giữ chỗ (chưa thanh toán và chưa quá HanGiuCho) mỗi khách\n        IF (SELECT COUNT(*) FROM dbo.DONDATVE\n            WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Chờ thanh toán'' AND HanGiuCho > dbo.fn_BayGio())\n           >= dbo.fn_GioiHanDonDangGiu()\n        BEGIN\n            ;THROW 50028, N''Bạn đang giữ chỗ tối đa số đơn cho phép. Hãy thanh toán hoặc chờ đơn cũ hết hạn.'', 1;\n        END\n\n        -- 2. Kiểm tra suất chiếu hợp lệ (còn mở bán và chưa bắt đầu)\n        DECLARE @PhongID INT;\n        DECLARE @TrangThaiSuatChieu NVARCHAR(50);\n        DECLARE @ThoiGianBatDau DATETIME2;\n\n        SELECT\n            @PhongID = PhongID,\n            @TrangThaiSuatChieu = TrangThai,\n            @ThoiGianBatDau = ThoiGianBatDau\n        FROM dbo.SUATCHIEU WITH (UPDLOCK, HOLDLOCK)\n        WHERE SuatChieuID = @SuatChieuID;\n\n        IF @PhongID IS NULL\n        BEGIN\n            ;THROW 50021, N''Suất chiếu không tồn tại.'', 1;\n        END\n\n        IF @TrangThaiSuatChieu <> N''Mở bán'' OR @ThoiGianBatDau <= dbo.fn_BayGio()\n        BEGIN\n            ;THROW 50022, N''Suất chiếu đã kết thúc, đã đóng bán hoặc bị hủy.'', 1;\n        END\n\n        -- 2b. Giải phóng các đơn đã quá hạn giữ ghế của suất chiếu này (đã khóa suất chiếu ở trên)\n        EXEC dbo.sp_Order_ExpirePending @SuatChieuID = @SuatChieuID, @TraVeKetQua = 0;\n\n        -- 3. Tách danh sách ghế cần đặt vào bảng tạm\n        DECLARE @BangGheCanDat TABLE (GheID INT PRIMARY KEY);\n        INSERT INTO @BangGheCanDat (GheID)\n        SELECT DISTINCT CAST(value AS INT)\n        FROM STRING_SPLIT(@DanhSachGheId, '','')\n        WHERE LTRIM(RTRIM(value)) <> '''';\n\n        IF NOT EXISTS (SELECT 1 FROM @BangGheCanDat)\n        BEGIN\n            ;THROW 50023, N''Vui lòng chọn ít nhất một ghế để đặt vé.'', 1;\n        END\n\n        IF (SELECT COUNT(*) FROM @BangGheCanDat) > dbo.fn_GioiHanGheMoiDon()\n        BEGIN\n            ;THROW 50026, N''Mỗi đơn chỉ được đặt tối đa số ghế cho phép.'', 1;\n        END\n\n        -- 4. KHÓA CÁC GHẾ VÀ KIỂM TRA TOÀN VẸN:\n        -- Khóa hàng trong GHE để ngăn chặn xung đột giữa các giao dịch đồng thời\n        DECLARE @GheCount INT;\n        SELECT @GheCount = COUNT(*)\n        FROM dbo.GHE g WITH (UPDLOCK, HOLDLOCK)\n        INNER JOIN @BangGheCanDat bg ON g.GheID = bg.GheID\n        WHERE g.PhongID = @PhongID AND g.TrangThai = N''Hoạt động'';\n\n        IF @GheCount <> (SELECT COUNT(*) FROM @BangGheCanDat)\n        BEGIN\n            ;THROW 50024, N''Một số ghế được chọn không hợp lệ, không thuộc phòng chiếu này hoặc đang bảo trì.'', 1;\n        END\n\n        -- 5. KIỂM TRA TRÙNG GHẾ: Đảm bảo không có ghế nào trong danh sách đã được đặt trong đơn hợp lệ\n        IF EXISTS (\n            SELECT 1\n            FROM dbo.CHITIETVE cv WITH (UPDLOCK, HOLDLOCK)\n            INNER JOIN dbo.DONDATVE ddv ON cv.DonDatVeID = ddv.DonDatVeID\n            INNER JOIN @BangGheCanDat bg ON cv.GheID = bg.GheID\n            WHERE ddv.SuatChieuID = @SuatChieuID\n              AND cv.TrangThai <> N''Đã hủy''\n              AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\n        )\n        BEGIN\n            ;THROW 50025, N''Một hoặc nhiều ghế bạn chọn vừa được khách hàng khác đặt. Vui lòng chọn ghế khác.'', 1;\n        END\n\n        -- 6. TÍNH SNAPSHOT GIÁ VÉ CHO TỪNG GHẾ (dùng hàm fn_TinhGiaVe)\n        DECLARE @BangChiTietVe TABLE (\n            GheID INT,\n            GiaVe DECIMAL(18,2),\n            MaVe VARCHAR(100)\n        );\n\n        INSERT INTO @BangChiTietVe (GheID, GiaVe, MaVe)\n        SELECT\n            bg.GheID,\n            dbo.fn_TinhGiaVe(@SuatChieuID, bg.GheID),\n            CONCAT(''TK-'', FORMAT(dbo.fn_BayGio(), ''yyyyMMddHHmmss''), ''-'', CAST(bg.GheID AS VARCHAR(10)), ''-'', LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), ''-'', ''''), 6))\n        FROM @BangGheCanDat bg;\n\n        DECLARE @TongTienVe DECIMAL(18,2) = 0;\n        SELECT @TongTienVe = ISNULL(SUM(GiaVe), 0) FROM @BangChiTietVe;\n\n        -- 7. TÍNH SNAPSHOT ĐỒ ĂN (NẾU CÓ TRUYỀN JSON)\n        DECLARE @BangChiTietDoAn TABLE (\n            SanPhamID INT,\n            SoLuong INT,\n            DonGia DECIMAL(18,2)\n        );\n\n        IF @DanhSachDoAnJson IS NOT NULL\n        BEGIN\n            IF ISJSON(@DanhSachDoAnJson) <> 1 OR LEFT(LTRIM(@DanhSachDoAnJson), 1) <> ''[''\n                THROW 50402, N''Danh sách sản phẩm phải là mảng JSON hợp lệ.'', 1;\n            IF EXISTS (SELECT 1 FROM OPENJSON(@DanhSachDoAnJson) WHERE [type] <> 5)\n                THROW 50402, N''Mỗi sản phẩm phải là một object hợp lệ.'', 1;\n            IF EXISTS (\n                SELECT 1 FROM OPENJSON(@DanhSachDoAnJson) item\n                OUTER APPLY (SELECT [value], [type] FROM OPENJSON(item.value) WHERE [key]=''SanPhamID'') product\n                OUTER APPLY (SELECT [value], [type] FROM OPENJSON(item.value) WHERE [key]=''SoLuong'') quantity\n                WHERE product.[type] IS NULL OR product.[type] <> 2 OR quantity.[type] IS NULL OR quantity.[type] <> 2\n                  OR product.value LIKE ''%[^0-9]%'' OR quantity.value LIKE ''%[^0-9]%''\n                  OR TRY_CONVERT(INT, product.value) IS NULL OR TRY_CONVERT(INT, product.value) <= 0\n                  OR TRY_CONVERT(BIGINT, quantity.value) IS NULL OR TRY_CONVERT(BIGINT, quantity.value) <= 0\n                  OR (SELECT COUNT(*) FROM OPENJSON(item.value) WHERE [key]=''SanPhamID'') <> 1\n                  OR (SELECT COUNT(*) FROM OPENJSON(item.value) WHERE [key]=''SoLuong'') <> 1\n            ) THROW 50402, N''Mọi mã sản phẩm và số lượng phải là số nguyên hợp lệ.'', 1;\n\n            DECLARE @ProductInput TABLE (SanPhamID INT NOT NULL, SoLuong BIGINT NOT NULL);\n            INSERT @ProductInput(SanPhamID,SoLuong)\n            SELECT CONVERT(INT,product.value),CONVERT(BIGINT,quantity.value)\n            FROM OPENJSON(@DanhSachDoAnJson) item\n            CROSS APPLY (SELECT [value] FROM OPENJSON(item.value) WHERE [key]=''SanPhamID'') product\n            CROSS APPLY (SELECT [value] FROM OPENJSON(item.value) WHERE [key]=''SoLuong'') quantity;\n            -- Cộng dồn các dòng trùng sản phẩm TRƯỚC khi kiểm trần (không lách được bằng cách tách dòng).\n            -- SoLuong đọc BIGINT để giá trị ngoài miền INT bị chặn bởi trần thay vì gây lỗi tràn số.\n            IF EXISTS (\n                SELECT 1\n                FROM @ProductInput j\n                GROUP BY j.SanPhamID\n                HAVING SUM(j.SoLuong) > dbo.fn_GioiHanSoLuongSanPham()\n            )\n            BEGIN\n                ;THROW 50027, N''Số lượng mỗi sản phẩm vượt quá mức cho phép.'', 1;\n            END\n\n            DECLARE @ValidProducts INT;\n            SELECT @ValidProducts = COUNT(*) FROM dbo.SANPHAM sp WITH (UPDLOCK, HOLDLOCK)\n            INNER JOIN (SELECT DISTINCT SanPhamID FROM @ProductInput) requested ON requested.SanPhamID=sp.SanPhamID\n            WHERE sp.TrangThai=N''Đang bán'';\n            IF @ValidProducts <> (SELECT COUNT(DISTINCT SanPhamID) FROM @ProductInput)\n                THROW 50402, N''Một hoặc nhiều sản phẩm không tồn tại hoặc không đang bán.'', 1;\n\n            INSERT INTO @BangChiTietDoAn (SanPhamID, SoLuong, DonGia)\n            SELECT\n                j.SanPhamID,\n                CAST(SUM(j.SoLuong) AS INT),\n                sp.Gia\n            FROM @ProductInput j\n            INNER JOIN dbo.SANPHAM sp WITH (UPDLOCK, HOLDLOCK) ON j.SanPhamID = sp.SanPhamID\n            WHERE j.SoLuong > 0 AND sp.TrangThai = N''Đang bán''\n            GROUP BY j.SanPhamID, sp.Gia;\n        END\n\n        DECLARE @TongTienDoAn DECIMAL(18,2) = 0;\n        SELECT @TongTienDoAn = ISNULL(SUM(SoLuong * DonGia), 0) FROM @BangChiTietDoAn;\n\n        -- 8. TÍNH KHUYẾN MÃI (NẾU CÓ)\n        DECLARE @KhuyenMaiID INT = NULL;\n        DECLARE @TienGiamGia DECIMAL(18,2) = 0;\n        DECLARE @TongTruocGiam DECIMAL(18,2) = @TongTienVe + @TongTienDoAn;\n\n        IF @MaKhuyenMai IS NOT NULL AND LTRIM(RTRIM(@MaKhuyenMai)) <> ''''\n        BEGIN\n            DECLARE @LoaiGiamGia NVARCHAR(20);\n            DECLARE @GiaTriGiam DECIMAL(18,2);\n            DECLARE @IsValid BIT;\n            DECLARE @Msg NVARCHAR(255);\n\n            EXEC dbo.sp_Promotion_Validate\n                @NguoiDungID = @NguoiDungID,\n                @MaCode = @MaKhuyenMai,\n                @TongTienDon = @TongTruocGiam,\n                @KhuyenMaiID = @KhuyenMaiID OUTPUT,\n                @LoaiGiamGia = @LoaiGiamGia OUTPUT,\n                @GiaTriGiam = @GiaTriGiam OUTPUT,\n                @TienGiam = @TienGiamGia OUTPUT,\n                @IsValid = @IsValid OUTPUT,\n                @Message = @Msg OUTPUT;\n\n            IF @IsValid = 1 AND @KhuyenMaiID IS NOT NULL\n            BEGIN\n                -- Chặn cứng lần nữa: giảm tối đa 99% tổng tạm tính, tổng đơn luôn > 0\n                DECLARE @TranGiam DECIMAL(18,2) = ROUND(@TongTruocGiam * dbo.fn_GioiHanGiamGiaPhanTram() / 100.0, 2, 1);\n                IF @TienGiamGia > @TranGiam SET @TienGiamGia = @TranGiam;\n\n                -- Khóa và tăng số lượng đã dùng của khuyến mãi\n                UPDATE dbo.KHUYENMAI WITH (UPDLOCK, HOLDLOCK)\n                SET SoLuongDaDung = SoLuongDaDung + 1\n                WHERE KhuyenMaiID = @KhuyenMaiID;\n            END\n            ELSE\n            BEGIN\n                SET @KhuyenMaiID = NULL;\n                SET @TienGiamGia = 0;\n            END\n        END\n\n        -- 9. TẠO BẢN GHI DONDATVE\n        INSERT INTO dbo.DONDATVE\n        (\n            NguoiDungID,\n            SuatChieuID,\n            KhuyenMaiID,\n            NgayDat,\n            TongTienVe,\n            TongTienDoAn,\n            TienGiamGia,\n            TrangThai,\n            HanGiuCho\n        )\n        VALUES\n        (\n            @NguoiDungID,\n            @SuatChieuID,\n            @KhuyenMaiID,\n            dbo.fn_BayGio(),\n            @TongTienVe,\n            @TongTienDoAn,\n            @TienGiamGia,\n            N''Chờ thanh toán'',\n            DATEADD(MINUTE, dbo.fn_ThoiGianGiuChoPhut(), dbo.fn_BayGio())\n        );\n\n        SET @NewDonDatVeID = SCOPE_IDENTITY();\n\n        -- 10. TẠO CÁC BẢN GHI CHITIETVE\n        INSERT INTO dbo.CHITIETVE (DonDatVeID, GheID, GiaVe, MaVe, TrangThai)\n        SELECT\n            @NewDonDatVeID,\n            GheID,\n            GiaVe,\n            MaVe,\n            N''Đã đặt''\n        FROM @BangChiTietVe;\n\n        -- 11. TẠO CÁC BẢN GHI CHITIETDOAN (NẾU CÓ)\n        IF EXISTS (SELECT 1 FROM @BangChiTietDoAn)\n        BEGIN\n            INSERT INTO dbo.CHITIETDOAN (DonDatVeID, SanPhamID, SoLuong, DonGia)\n            SELECT\n                @NewDonDatVeID,\n                SanPhamID,\n                SoLuong,\n                DonGia\n            FROM @BangChiTietDoAn;\n        END\n\n        IF @TuMoTran = 1\n            COMMIT TRANSACTION;\n\n        -- Trả về kết quả chốt của đơn đặt vé\n        SELECT\n            ddv.DonDatVeID,\n            ddv.NguoiDungID,\n            ddv.SuatChieuID,\n            ddv.NgayDat,\n            ddv.TongTienVe,\n            ddv.TongTienDoAn,\n            ddv.TienGiamGia,\n            (ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia) AS TongThanhToan,\n            ddv.TrangThai,\n            ddv.HanGiuCho,\n            (SELECT COUNT(*) FROM dbo.CHITIETVE WHERE DonDatVeID = ddv.DonDatVeID) AS SoLuongVe\n        FROM dbo.DONDATVE ddv\n        WHERE ddv.DonDatVeID = @NewDonDatVeID;\n\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() = -1\n            ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE() = 1\n        BEGIN\n            IF @TuMoTran = 1\n                ROLLBACK TRANSACTION;\n            ELSE\n                ROLLBACK TRANSACTION sp_Booking_Create;\n        END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Cinema_GetImages","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Cinema_GetImages\r\n    @RapID INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    SELECT i.HinhAnhRapID, i.RapID, i.URL, i.MoTa, i.LaAnhDaiDien, i.ThuTuHienThi, i.TrangThai, i.NgayTao\r\n    FROM dbo.HINHANH_RAPCHIEUPHIM i\r\n    INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = i.RapID\r\n    WHERE i.RapID = @RapID AND r.TrangThai = N''Hoạt động'' AND i.TrangThai = N''Hoạt động''\r\n    ORDER BY i.ThuTuHienThi, i.HinhAnhRapID;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Cinema_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Cinema_List\r\n    @ThanhPho NVARCHAR(100) = NULL\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    SELECT r.RapID, r.TenRap, r.DiaChi, r.ThanhPho, r.SoDienThoai, r.MoTa, r.NgayHoatDong, r.TrangThai,\r\n           cover.URL AS AnhDaiDienURL\r\n    FROM dbo.RAPCHIEUPHIM r\r\n    OUTER APPLY\r\n    (\r\n        SELECT TOP (1) i.URL\r\n        FROM dbo.HINHANH_RAPCHIEUPHIM i\r\n        WHERE i.RapID = r.RapID AND i.LaAnhDaiDien = 1 AND i.TrangThai = N''Hoạt động''\r\n        ORDER BY i.HinhAnhRapID\r\n    ) cover\r\n    WHERE (@ThanhPho IS NULL OR r.ThanhPho = @ThanhPho) AND r.TrangThai = N''Hoạt động''\r\n    ORDER BY r.ThanhPho, r.TenRap;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Clock_GetNow","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Clock_GetNow\r\n    @PhimID INT = NULL\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    SELECT dbo.fn_BayGio() AS BayGio,(SELECT ThoiLuong FROM dbo.PHIM WHERE PhimID=@PhimID) AS ThoiLuong;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/003_complaint_order_ownership.sql:3 (dbo.sp_Complaint_Create)\nCREATE   PROCEDURE dbo.sp_Complaint_Create\n(\n    @NguoiDungID INT,\n    @DonDatVeID INT = NULL,\n    @LoaiKhieuNai NVARCHAR(100),\n    @TieuDe NVARCHAR(200),\n    @NoiDung NVARCHAR(MAX),\n    @MucDoUuTien NVARCHAR(50) = N''Trung bình''\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''GUI_KHIEU_NAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF @DonDatVeID IS NOT NULL AND NOT EXISTS\n    (\n        SELECT 1\n        FROM dbo.DONDATVE\n        WHERE DonDatVeID = @DonDatVeID\n          AND NguoiDungID = @NguoiDungID\n    )\n    BEGIN\n        -- Same non-disclosing error for a missing or foreign order reference.\n        ;THROW 50041, N''Đơn đặt vé tham chiếu không hợp lệ.'', 1;\n    END\n\n    INSERT INTO dbo.KHIEUNAI (NguoiDungID, DonDatVeID, LoaiKhieuNai, TieuDe, NoiDung, MucDoUuTien, NgayTao, TrangThai)\n    VALUES (@NguoiDungID, @DonDatVeID, @LoaiKhieuNai, @TieuDe, @NoiDung, @MucDoUuTien, dbo.fn_BayGio(), N''Mới'');\n\n    SELECT KhieuNaiID, NguoiDungID, DonDatVeID, LoaiKhieuNai, TieuDe, NoiDung, MucDoUuTien, NgayTao, TrangThai\n    FROM dbo.KHIEUNAI\n    WHERE KhieuNaiID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_GetByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_GetByCustomer\n(\n    @NguoiDungID INT,\n    @KhieuNaiID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID AND NguoiDungID = @NguoiDungID)\n    BEGIN\n        ;THROW 50042, N''Khiếu nại không tồn tại hoặc bạn không có quyền xem.'', 1;\n    END\n\n    -- Recordset 1: Chi tiết khiếu nại\n    SELECT\n        kn.KhieuNaiID,\n        kn.NguoiDungID,\n        kn.DonDatVeID,\n        kn.LoaiKhieuNai,\n        kn.TieuDe,\n        kn.NoiDung,\n        kn.MucDoUuTien,\n        kn.NgayTao,\n        kn.TrangThai\n    FROM dbo.KHIEUNAI kn\n    WHERE kn.KhieuNaiID = @KhieuNaiID;\n\n    -- Recordset 2: Các lần xử lý từ CSKH\n    SELECT\n        xl.XuLyID,\n        xl.NoiDungXuLy,\n        xl.NgayXuLy,\n        xl.TrangThaiSauXuLy\n    FROM dbo.XULY_KHIEUNAI xl\n    WHERE xl.KhieuNaiID = @KhieuNaiID\n    ORDER BY xl.NgayXuLy ASC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_ListByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_ListByCustomer\n(\n    @NguoiDungID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n\n    SELECT\n        KhieuNaiID,\n        NguoiDungID,\n        DonDatVeID,\n        LoaiKhieuNai,\n        TieuDe,\n        NoiDung,\n        MucDoUuTien,\n        NgayTao,\n        TrangThai\n    FROM dbo.KHIEUNAI\n    WHERE NguoiDungID = @NguoiDungID\n    ORDER BY NgayTao DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_DatVe","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Alias sp_DatVe cho sp_Booking_Create theo bảng hợp đồng Use Case\r\nCREATE   PROCEDURE dbo.sp_DatVe\r\n(\r\n    @NguoiDungID INT,\r\n    @SuatChieuID INT,\r\n    @MaKhuyenMai VARCHAR(50) = NULL,\r\n    @DanhSachGheId VARCHAR(MAX),\r\n    @DanhSachDoAnJson NVARCHAR(MAX) = NULL,\r\n    @NewDonDatVeID INT OUTPUT\r\n)\r\nAS\r\nBEGIN\r\n        SET NOCOUNT ON;\r\nEXEC dbo.sp_Booking_Create\r\n        @NguoiDungID = @NguoiDungID,\r\n        @SuatChieuID = @SuatChieuID,\r\n        @MaKhuyenMai = @MaKhuyenMai,\r\n        @DanhSachGheId = @DanhSachGheId,\r\n        @DanhSachDoAnJson = @DanhSachDoAnJson,\r\n        @NewDonDatVeID = @NewDonDatVeID OUTPUT;\r\nEND;\r\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Genre_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Genre_List\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    SELECT TheLoaiID, TenTheLoai FROM dbo.THELOAI ORDER BY TenTheLoai;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Dashboard","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:713 (dbo.sp_Manager_Dashboard)\nCREATE   PROCEDURE dbo.sp_Manager_Dashboard\n(\n    @NguoiDungID INT,\n    @RapID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XEM_BAO_CAO_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền truy cập rạp này.'', 1;\n    END\n\n    -- Chỉ số tổng hợp rạp\n    SELECT\n        r.RapID,\n        r.TenRap,\n        r.ThanhPho,\n        (SELECT COUNT(*) FROM dbo.PHONGCHIEU pc WHERE pc.RapID = @RapID AND pc.TrangThai = N''Hoạt động'') AS TongPhongChieu,\n        (SELECT COUNT(*) FROM dbo.GHE g INNER JOIN dbo.PHONGCHIEU pc ON g.PhongID = pc.PhongID WHERE pc.RapID = @RapID AND g.TrangThai = N''Hoạt động'') AS TongGhe,\n        (SELECT COUNT(*) FROM dbo.SUATCHIEU sc INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID WHERE pc.RapID = @RapID AND dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) = dbo.fn_HomNay() AND sc.TrangThai<>N''Đã hủy'') AS SuatChieuHomNay,\n        (SELECT COUNT(DISTINCT ddv.DonDatVeID)\n         FROM dbo.DONDATVE ddv\n         INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n         INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n         WHERE pc.RapID = @RapID\n           AND EXISTS(SELECT 1 FROM dbo.THANHTOAN tt WHERE tt.DonDatVeID=ddv.DonDatVeID AND tt.TrangThai=N''Thành công''\n                      GROUP BY tt.DonDatVeID HAVING dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan,tt.NgayTao)))=dbo.fn_HomNay())\n        ) AS DonDatVeHomNay\n    FROM dbo.RAPCHIEUPHIM r\n    WHERE r.RapID = @RapID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_ListAssignedCinemas","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:19 (dbo.sp_Manager_ListAssignedCinemas)\nCREATE   PROCEDURE dbo.sp_Manager_ListAssignedCinemas\n(\n    @NguoiDungID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n\n    SELECT\n        pcr.PhanCongID,\n        pcr.RapID,\n        r.TenRap,\n        r.DiaChi,\n        r.ThanhPho,\n        r.SoDienThoai,\n        pcr.NgayBatDau,\n        pcr.NgayKetThuc,\n        pcr.TrangThai AS TrangThaiPhanCong\n    FROM dbo.PHANCONG_RAP pcr\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\n    WHERE pcr.NguoiDungID = @NguoiDungID\n      AND pcr.TrangThai = N''Hiệu lực''\n      AND dbo.fn_HomNay() >= pcr.NgayBatDau\n      AND (pcr.NgayKetThuc IS NULL OR dbo.fn_HomNay() <= pcr.NgayKetThuc);\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Pricing_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Pricing_Create\n(\n    @NguoiDungID INT,\n    @RapID INT,\n    @LoaiGhe NVARCHAR(50),\n    @LoaiNgay NVARCHAR(50),\n    @DinhDang NVARCHAR(50),\n    @PhuThu DECIMAL(18,2),\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n\n    INSERT INTO dbo.BANGGIA (RapID, LoaiGhe, LoaiNgay, DinhDang, PhuThu, NgayBatDau, NgayKetThuc, TrangThai)\n    VALUES (@RapID, @LoaiGhe, @LoaiNgay, @DinhDang, @PhuThu, @NgayBatDau, @NgayKetThuc, N''Áp dụng'');\n\n    SELECT\n        GiaID,\n        RapID,\n        LoaiGhe,\n        LoaiNgay,\n        DinhDang,\n        PhuThu,\n        NgayBatDau,\n        NgayKetThuc,\n        TrangThai\n    FROM dbo.BANGGIA\n    WHERE GiaID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Pricing_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Pricing_List\n(\n    @NguoiDungID INT,\n    @RapID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n\n    SELECT\n        GiaID,\n        RapID,\n        LoaiGhe,\n        LoaiNgay,\n        DinhDang,\n        PhuThu,\n        NgayBatDau,\n        NgayKetThuc,\n        TrangThai\n    FROM dbo.BANGGIA\n    WHERE RapID = @RapID\n    ORDER BY NgayBatDau DESC, LoaiGhe, LoaiNgay;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Pricing_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Pricing_Update\n(\n    @NguoiDungID INT,\n    @GiaID INT,\n    @PhuThu DECIMAL(18,2),\n    @TrangThai NVARCHAR(50)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @RapID INT;\n    SELECT @RapID = RapID FROM dbo.BANGGIA WHERE GiaID = @GiaID;\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n\n    UPDATE dbo.BANGGIA\n    SET PhuThu = @PhuThu,\n        TrangThai = @TrangThai\n    WHERE GiaID = @GiaID;\n\n    SELECT GiaID, RapID, LoaiGhe, LoaiNgay, DinhDang, PhuThu, NgayBatDau, NgayKetThuc, TrangThai\n    FROM dbo.BANGGIA\n    WHERE GiaID = @GiaID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Revenue","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:752 (dbo.sp_Manager_Revenue)\nCREATE   PROCEDURE dbo.sp_Manager_Revenue\n(\n    @NguoiDungID INT,\n    @RapID INT,\n    @TuNgay DATE = NULL,\n    @DenNgay DATE = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XEM_BAO_CAO_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền truy cập báo cáo rạp này.'', 1;\n    END\n\n    IF @TuNgay IS NULL SET @TuNgay = DATEADD(DAY, -30, dbo.fn_HomNay());\n    IF @DenNgay IS NULL SET @DenNgay = dbo.fn_HomNay();\n\n    -- Doanh thu theo ngày thanh toán: chỉ tính THANHTOAN có TrangThai = ''Thành công''\n    ;WITH DonDaThu AS (\n        SELECT\n            ddv.DonDatVeID,\n            ddv.TongTienVe,\n            ddv.TongTienDoAn,\n            ddv.TienGiamGia,\n            SUM(tt.SoTien) AS TienDaThu,\n            dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))) AS NgayThu,\n            (SELECT COUNT(*) FROM dbo.CHITIETVE cv\n             WHERE cv.DonDatVeID = ddv.DonDatVeID AND cv.TrangThai <> N''Đã hủy'') AS SoVe\n        FROM dbo.DONDATVE ddv\n        INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n        INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n        INNER JOIN dbo.THANHTOAN tt ON tt.DonDatVeID = ddv.DonDatVeID AND tt.TrangThai = N''Thành công''\n        WHERE pc.RapID = @RapID\n        GROUP BY ddv.DonDatVeID, ddv.TongTienVe, ddv.TongTienDoAn, ddv.TienGiamGia\n    )\n    SELECT\n        NgayThu AS Ngay,\n        COUNT(*) AS SoDon,\n        SUM(SoVe) AS SoVeBan,\n        SUM(TongTienVe) AS DoanhThuVe,\n        SUM(TongTienDoAn) AS DoanhThuDoAn,\n        SUM(TienGiamGia) AS TienGiamGia,\n        SUM(TienDaThu) AS DoanhThuThucTe\n    FROM DonDaThu\n    WHERE NgayThu BETWEEN @TuNgay AND @DenNgay\n    GROUP BY NgayThu\n    ORDER BY Ngay DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_Create\n(\n    @NguoiDungID INT,\n    @RapID INT,\n    @TenPhong NVARCHAR(100),\n    @LoaiPhong NVARCHAR(50) = N''2D''\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp này.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE RapID = @RapID AND TenPhong = @TenPhong)\n    BEGIN\n        ;THROW 50051, N''Tên phòng chiếu đã tồn tại trong rạp này.'', 1;\n    END\n\n    INSERT INTO dbo.PHONGCHIEU (RapID, TenPhong, LoaiPhong, TrangThai)\n    VALUES (@RapID, @TenPhong, @LoaiPhong, N''Hoạt động'');\n\n    SELECT\n        PhongID,\n        RapID,\n        TenPhong,\n        LoaiPhong,\n        TrangThai\n    FROM dbo.PHONGCHIEU\n    WHERE PhongID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_Delete\n(\n    @NguoiDungID INT,\n    @PhongID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @RapID INT;\n    SELECT @RapID = RapID FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp này.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.SUATCHIEU WHERE PhongID = @PhongID)\n    BEGIN\n        ;THROW 50053, N''Không thể xóa phòng chiếu đã có lịch sử suất chiếu. Vui lòng chuyển trạng thái Ngưng hoạt động.'', 1;\n    END\n\n    DELETE FROM dbo.GHE WHERE PhongID = @PhongID;\n    DELETE FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n\n    SELECT N''Xóa phòng chiếu thành công.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_List\n(\n    @NguoiDungID INT,\n    @RapID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    -- Kiểm tra scope phân công\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp này.'', 1;\n    END\n\n    SELECT\n        pc.PhongID,\n        pc.RapID,\n        r.TenRap,\n        pc.TenPhong,\n        pc.LoaiPhong,\n        pc.TrangThai,\n        (SELECT COUNT(*) FROM dbo.GHE g WHERE g.PhongID = pc.PhongID) AS TongSoGhe\n    FROM dbo.PHONGCHIEU pc\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\n    WHERE pc.RapID = @RapID\n    ORDER BY pc.TenPhong;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_Update\n(\n    @NguoiDungID INT,\n    @PhongID INT,\n    @TenPhong NVARCHAR(100),\n    @LoaiPhong NVARCHAR(50),\n    @TrangThai NVARCHAR(50)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @RapID INT;\n    SELECT @RapID = RapID FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n\n    IF @RapID IS NULL\n    BEGIN\n        ;THROW 50052, N''Phòng chiếu không tồn tại.'', 1;\n    END\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp chứa phòng này.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE RapID = @RapID AND TenPhong = @TenPhong AND PhongID <> @PhongID)\n    BEGIN\n        ;THROW 50051, N''Tên phòng chiếu đã trùng với phòng khác trong cùng rạp.'', 1;\n    END\n\n    UPDATE dbo.PHONGCHIEU\n    SET TenPhong = @TenPhong,\n        LoaiPhong = @LoaiPhong,\n        TrangThai = @TrangThai\n    WHERE PhongID = @PhongID;\n\n    SELECT PhongID, RapID, TenPhong, LoaiPhong, TrangThai\n    FROM dbo.PHONGCHIEU\n    WHERE PhongID = @PhongID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_BatchCreate","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_BatchCreate\n(\n    @NguoiDungID INT,\n    @PhongID INT,\n    @NumRows INT = 8,      -- Số hàng ghế (A, B, C...)\n    @SeatsPerRow INT = 12, -- Số ghế mỗi hàng (1..12)\n    @VipRows INT = 3       -- Số hàng VIP ở giữa\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        DECLARE @RapID INT;\n        SELECT @RapID = RapID FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n        BEGIN\n            ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        END\n\n        -- Xóa sơ đồ ghế cũ nếu phòng chưa có vé\n        IF EXISTS (\n            SELECT 1 FROM dbo.CHITIETVE cv\n            INNER JOIN dbo.GHE g ON cv.GheID = g.GheID\n            WHERE g.PhongID = @PhongID\n        )\n        BEGIN\n            ;THROW 50055, N''Không thể tạo lại toàn bộ sơ đồ ghế vì phòng này đã có dữ liệu vé.'', 1;\n        END\n\n        DELETE FROM dbo.GHE WHERE PhongID = @PhongID;\n\n        DECLARE @r INT = 1;\n        DECLARE @c INT = 1;\n        DECLARE @HangChar CHAR(1);\n        DECLARE @LoaiGhe NVARCHAR(50);\n\n        WHILE @r <= @NumRows\n        BEGIN\n            SET @HangChar = CHAR(64 + @r); -- 65 = ''A''\n            SET @c = 1;\n\n            -- Xác định loại ghế: hàng giữa là VIP, hàng cuối có thể là Sweetbox\n            IF @r = @NumRows\n                SET @LoaiGhe = N''Sweetbox'';\n            ELSE IF @r > (@NumRows - @VipRows - 1) AND @r < @NumRows\n                SET @LoaiGhe = N''VIP'';\n            ELSE\n                SET @LoaiGhe = N''Thường'';\n\n            WHILE @c <= @SeatsPerRow\n            BEGIN\n                INSERT INTO dbo.GHE (PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai)\n                VALUES (@PhongID, @HangChar, @c, @LoaiGhe, N''Hoạt động'');\n\n                SET @c = @c + 1;\n            END\n\n            SET @r = @r + 1;\n        END\n\n        COMMIT TRANSACTION;\n\n        SELECT\n            COUNT(*) AS TongSoGheTao,\n            @PhongID AS PhongID\n        FROM dbo.GHE\n        WHERE PhongID = @PhongID;\n\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_Create\n(\n    @NguoiDungID INT,\n    @PhongID INT,\n    @HangGhe VARCHAR(10),\n    @SoGhe INT,\n    @LoaiGhe NVARCHAR(50) = N''Thường''\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @RapID INT;\n    SELECT @RapID = RapID FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.GHE WHERE PhongID = @PhongID AND HangGhe = @HangGhe AND SoGhe = @SoGhe)\n    BEGIN\n        ;THROW 50054, N''Vị trí ghế này đã tồn tại trong phòng chiếu.'', 1;\n    END\n\n    INSERT INTO dbo.GHE (PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai)\n    VALUES (@PhongID, @HangGhe, @SoGhe, @LoaiGhe, N''Hoạt động'');\n\n    SELECT GheID, PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai\n    FROM dbo.GHE\n    WHERE GheID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_Delete\n(\n    @NguoiDungID INT,\n    @GheID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @RapID INT;\n    SELECT @RapID = pc.RapID\n    FROM dbo.GHE g\n    INNER JOIN dbo.PHONGCHIEU pc ON g.PhongID = pc.PhongID\n    WHERE g.GheID = @GheID;\n\n    IF @RapID IS NULL\n    BEGIN\n        ;THROW 50109, N''Ghế không tồn tại.'', 1;\n    END\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n\n    IF EXISTS (SELECT 1 FROM dbo.CHITIETVE WHERE GheID = @GheID)\n    BEGIN\n        ;THROW 50110, N''Ghế đã có vé bán ra. Hãy chuyển trạng thái sang Hỏng/Bảo trì thay vì xóa.'', 1;\n    END\n\n    DELETE FROM dbo.GHE WHERE GheID = @GheID;\n    SELECT N''Đã xóa ghế.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_ListByRoom","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_ListByRoom\n(\n    @NguoiDungID INT,\n    @PhongID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @RapID INT;\n    SELECT @RapID = RapID FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp chứa phòng này.'', 1;\n    END\n\n    SELECT\n        GheID,\n        PhongID,\n        HangGhe,\n        SoGhe,\n        (HangGhe + CAST(SoGhe AS VARCHAR(10))) AS TenGhe,\n        LoaiGhe,\n        TrangThai\n    FROM dbo.GHE\n    WHERE PhongID = @PhongID\n    ORDER BY HangGhe, SoGhe;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_Update\n    @NguoiDungID INT, @GheID INT, @LoaiGhe NVARCHAR(50), @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTran BIT=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n        IF @OwnTran=1 BEGIN TRANSACTION ELSE SAVE TRANSACTION ManagerSeatUpdate;\n        DECLARE @RapID INT;\n        SELECT @RapID=pc.RapID FROM dbo.GHE g WITH (UPDLOCK,HOLDLOCK) INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID=g.PhongID WHERE g.GheID=@GheID;\n        IF @RapID IS NULL THROW 50109, N''Ghế không tồn tại.'', 1;\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID,@RapID)=0 THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        IF dbo.fn_GheCoVeHieuLucSuatTuongLai(@GheID)=1 THROW 50207, N''Ghế có vé hiệu lực ở suất chiếu tương lai.'', 1;\n        UPDATE dbo.GHE SET LoaiGhe=@LoaiGhe, TrangThai=@TrangThai WHERE GheID=@GheID;\n        IF @OwnTran=1 COMMIT TRANSACTION;\n        SELECT GheID,PhongID,HangGhe,SoGhe,LoaiGhe,TrangThai FROM dbo.GHE WHERE GheID=@GheID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE()=-1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE()=1 BEGIN IF @OwnTran=1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION ManagerSeatUpdate; END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_Cancel","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Showtime_Cancel\n    @NguoiDungID INT, @SuatChieuID INT, @LyDo NVARCHAR(255) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    EXEC dbo.sp_Showtime_CancelCascade @SuatChieuID = @SuatChieuID, @NguoiDungID = @NguoiDungID, @LyDo = @LyDo;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:396 (dbo.sp_Manager_Showtime_Create)\nCREATE   PROCEDURE dbo.sp_Manager_Showtime_Create\n(\n    @NguoiDungID INT,\n    @PhimID INT,\n    @PhongID INT,\n    @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50) = N''2D'',\n    @GiaVeCoBan DECIMAL(18,2)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    DECLARE @RapID INT;\n    SELECT @RapID = RapID FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n\n    IF @RapID IS NULL\n    BEGIN\n        ;THROW 50056, N''Phòng chiếu không tồn tại.'', 1;\n    END\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp chiếu này.'', 1;\n    END\n\n    IF @ThoiGianKetThuc <= @ThoiGianBatDau\n    BEGIN\n        ;THROW 50057, N''Thời gian kết thúc phải sau thời gian bắt đầu.'', 1;\n    END\n\n    -- Chèn bản ghi suất chiếu (Trigger TRG_SuatChieu_KiemTraTrungLich sẽ kiểm tra trùng lịch tự động)\n    EXEC dbo.sp_Showtime_ValidateTimes @PhimID=@PhimID,@ThoiGianBatDau=@ThoiGianBatDau,@ThoiGianKetThuc=@ThoiGianKetThuc;\n        INSERT INTO dbo.SUATCHIEU (PhimID, PhongID, ThoiGianBatDau, ThoiGianKetThuc, DinhDang, GiaVeCoBan, TrangThai)\n    VALUES (@PhimID, @PhongID, @ThoiGianBatDau, @ThoiGianKetThuc, @DinhDang, @GiaVeCoBan, N''Mở bán'');\n\n    DECLARE @NewSuatChieuID INT = SCOPE_IDENTITY();\n\n    EXEC dbo.sp_Showtime_GetDetail @SuatChieuID = @NewSuatChieuID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Phase 7: manager-scoped showtime listing. No raw backend query is permitted.\nCREATE   PROCEDURE dbo.sp_Manager_Showtime_List\n(\n    @NguoiDungID INT,\n    @RapID INT,\n    @TuNgay DATE = NULL,\n    @DenNgay DATE = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền truy cập rạp này.'', 1;\n\n    SELECT sc.SuatChieuID, sc.PhimID, p.TenPhim, sc.PhongID, pc.TenPhong, pc.RapID, r.TenRap,\n           sc.ThoiGianBatDau, sc.ThoiGianKetThuc, sc.DinhDang, sc.GiaVeCoBan, sc.TrangThai\n    FROM dbo.SUATCHIEU sc\n    INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\n    INNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\n    WHERE pc.RapID = @RapID\n      AND (@TuNgay IS NULL OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) >= @TuNgay)\n      AND (@DenNgay IS NULL OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) <= @DenNgay)\n    ORDER BY sc.ThoiGianBatDau DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:143 (dbo.sp_Manager_Showtime_Update)\nCREATE   PROCEDURE dbo.sp_Manager_Showtime_Update\n    @NguoiDungID INT, @SuatChieuID INT, @PhimID INT, @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2, @DinhDang NVARCHAR(50), @GiaVeCoBan DECIMAL(18,2), @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTran BIT=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n        IF @OwnTran=1 BEGIN TRANSACTION ELSE SAVE TRANSACTION ManagerShowtimeUpdate;\n        DECLARE @RapID INT, @OldPhim INT, @OldStart DATETIME2, @OldEnd DATETIME2, @OldRoom INT, @OldFormat NVARCHAR(50), @OldStatus NVARCHAR(50), @Now DATETIME2 = dbo.fn_BayGio();\n        SELECT @RapID = pc.RapID, @OldPhim = sc.PhimID, @OldStart = sc.ThoiGianBatDau, @OldEnd = sc.ThoiGianKetThuc,\n               @OldRoom = sc.PhongID, @OldFormat = sc.DinhDang, @OldStatus = sc.TrangThai\n        FROM dbo.SUATCHIEU sc WITH (UPDLOCK, HOLDLOCK)\n        INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID = sc.PhongID WHERE sc.SuatChieuID = @SuatChieuID;\n        IF @RapID IS NULL THROW 50058, N''Suất chiếu không tồn tại.'', 1;\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0 THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        IF @TrangThai = N''Đã hủy'' THROW 50123, N''Dùng route hủy suất chiếu riêng.'', 1;\n        IF EXISTS (SELECT 1 FROM dbo.DONDATVE d WHERE d.SuatChieuID = @SuatChieuID AND\n                   (d.TrangThai = N''Đã thanh toán'' OR (d.TrangThai = N''Chờ thanh toán'' AND d.HanGiuCho > @Now)))\n           AND (@PhimID <> @OldPhim OR @ThoiGianBatDau <> @OldStart OR @ThoiGianKetThuc <> @OldEnd OR @DinhDang <> @OldFormat)\n            THROW 50120, N''Suất chiếu đã có đơn; không thể đổi phim, giờ, phòng hoặc định dạng.'', 1;\n        IF @ThoiGianKetThuc <= @ThoiGianBatDau THROW 50057, N''Thời gian suất chiếu không hợp lệ.'', 1;\n        EXEC dbo.sp_Showtime_ValidateTimes @PhimID=@PhimID,@ThoiGianBatDau=@ThoiGianBatDau,@ThoiGianKetThuc=@ThoiGianKetThuc;\n        UPDATE dbo.SUATCHIEU SET PhimID=@PhimID, ThoiGianBatDau=@ThoiGianBatDau, ThoiGianKetThuc=@ThoiGianKetThuc,\n            DinhDang=@DinhDang, GiaVeCoBan=@GiaVeCoBan, TrangThai=@TrangThai WHERE SuatChieuID=@SuatChieuID;\n        IF @OwnTran=1 COMMIT TRANSACTION;\n        EXEC dbo.sp_Showtime_GetDetail @SuatChieuID = @SuatChieuID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE()=-1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE()=1 BEGIN IF @OwnTran=1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION ManagerShowtimeUpdate; END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Movie_GetDetail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Movie_GetDetail\r\n(\r\n    @PhimID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    -- Recordset 1: Thông tin cơ bản phim\r\n    SELECT\r\n        p.PhimID,\r\n        p.TenPhim,\r\n        p.ThoiLuong,\r\n        p.NgayKhoiChieu,\r\n        p.NgayKetThuc,\r\n        p.NgonNgu,\r\n        p.PhuDe,\r\n        p.DoTuoi,\r\n        p.DaoDien,\r\n        p.MoTa,\r\n        p.PosterURL,\r\n        p.TrailerURL,\r\n        p.TrangThai,\r\n        tp.DiemDanhGiaTrungBinh,\r\n        tp.SoLuotDanhGia\r\n    FROM dbo.PHIM p\r\n    LEFT JOIN dbo.vw_ThongKePhim tp ON p.PhimID = tp.PhimID\r\n    WHERE p.PhimID = @PhimID;\r\n\r\n    -- Recordset 2: Thể loại\r\n    SELECT t.TheLoaiID, t.TenTheLoai\r\n    FROM dbo.PHIM_THELOAI pt\r\n    INNER JOIN dbo.THELOAI t ON pt.TheLoaiID = t.TheLoaiID\r\n    WHERE pt.PhimID = @PhimID;\r\n\r\n    -- Recordset 3: Diễn viên\r\n    SELECT dv.DienVienID, dv.HoTen, dv.QuocTich, pd.VaiDien\r\n    FROM dbo.PHIM_DIENVIEN pd\r\n    INNER JOIN dbo.DIENVIEN dv ON pd.DienVienID = dv.DienVienID\r\n    WHERE pd.PhimID = @PhimID;\r\n\r\n    -- Recordset 4: Đánh giá gần đây\r\n    SELECT TOP 10\r\n        dg.DanhGiaID,\r\n        nd.HoTen AS NguoiDanhGia,\r\n        dg.SoSao,\r\n        dg.NoiDung,\r\n        dg.NgayDanhGia\r\n    FROM dbo.DANHGIAPHIM dg\r\n    INNER JOIN dbo.NGUOIDUNG nd ON dg.NguoiDungID = nd.NguoiDungID\r\n    WHERE dg.PhimID = @PhimID\r\n    ORDER BY dg.NgayDanhGia DESC;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Movie_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Movie_List\r\n(\r\n    @TrangThai NVARCHAR(50) = NULL,\r\n    @TheLoaiID INT = NULL,\r\n    @SearchTerm NVARCHAR(100) = NULL\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT DISTINCT\r\n        p.PhimID,\r\n        p.TenPhim,\r\n        p.ThoiLuong,\r\n        p.NgayKhoiChieu,\r\n        p.NgayKetThuc,\r\n        p.NgonNgu,\r\n        p.PhuDe,\r\n        p.DoTuoi,\r\n        p.DaoDien,\r\n        p.PosterURL,\r\n        p.TrailerURL,\r\n        p.TrangThai,\r\n        tp.DiemDanhGiaTrungBinh,\r\n        tp.SoLuotDanhGia,\r\n        STUFF((\r\n            SELECT '', '' + t.TenTheLoai\r\n            FROM dbo.PHIM_THELOAI pt\r\n            INNER JOIN dbo.THELOAI t ON pt.TheLoaiID = t.TheLoaiID\r\n            WHERE pt.PhimID = p.PhimID\r\n            FOR XML PATH(''''), TYPE\r\n        ).value(''.'', ''NVARCHAR(MAX)''), 1, 2, '''') AS DanhSachTheLoai\r\n    FROM dbo.PHIM p\r\n    LEFT JOIN dbo.vw_ThongKePhim tp ON p.PhimID = tp.PhimID\r\n    LEFT JOIN dbo.PHIM_THELOAI pt2 ON p.PhimID = pt2.PhimID\r\n    WHERE (@TrangThai IS NULL OR p.TrangThai = @TrangThai)\r\n      AND (@TheLoaiID IS NULL OR pt2.TheLoaiID = @TheLoaiID)\r\n      AND (@SearchTerm IS NULL OR p.TenPhim LIKE ''%'' + @SearchTerm + ''%'' OR p.DaoDien LIKE ''%'' + @SearchTerm + ''%'')\r\n    ORDER BY p.NgayKhoiChieu DESC;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_Cancel","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Order_Cancel\r\n(\r\n    @NguoiDungID INT,\r\n    @DonDatVeID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRY\r\n        BEGIN TRANSACTION;\r\n\r\n        DECLARE @TrangThai NVARCHAR(50);\r\n        DECLARE @KhuyenMaiID INT;\r\n\r\n        SELECT\r\n            @TrangThai = TrangThai,\r\n            @KhuyenMaiID = KhuyenMaiID\r\n        FROM dbo.DONDATVE WITH (UPDLOCK, HOLDLOCK)\r\n        WHERE DonDatVeID = @DonDatVeID AND NguoiDungID = @NguoiDungID;\r\n\r\n        IF @TrangThai IS NULL\r\n        BEGIN\r\n            ;THROW 50034, N''Đơn đặt vé không tồn tại hoặc bạn không có quyền thao tác.'', 1;\r\n        END\r\n\r\n        IF @TrangThai <> N''Chờ thanh toán''\r\n        BEGIN\r\n            ;THROW 50035, N''Chỉ có thể hủy đơn khi đang ở trạng thái Chờ thanh toán.'', 1;\r\n        END\r\n\r\n        -- Cập nhật đơn thành Đã hủy\r\n        UPDATE dbo.DONDATVE\r\n        SET TrangThai = N''Đã hủy''\r\n        WHERE DonDatVeID = @DonDatVeID;\r\n\r\n        -- Cập nhật vé thành Đã hủy để giải phóng ghế\r\n        UPDATE dbo.CHITIETVE\r\n        SET TrangThai = N''Đã hủy''\r\n        WHERE DonDatVeID = @DonDatVeID;\r\n\r\n        -- Hoàn lại lượt dùng mã khuyến mãi nếu có\r\n        IF @KhuyenMaiID IS NOT NULL\r\n        BEGIN\r\n            UPDATE dbo.KHUYENMAI\r\n            SET SoLuongDaDung = CASE WHEN SoLuongDaDung > 0 THEN SoLuongDaDung - 1 ELSE 0 END\r\n            WHERE KhuyenMaiID = @KhuyenMaiID;\r\n        END\r\n\r\n        COMMIT TRANSACTION;\r\n\r\n        SELECT N''Hủy đơn đặt vé thành công.'' AS [Message];\r\n\r\n    END TRY\r\n    BEGIN CATCH\r\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\r\n        ;THROW;\r\n    END CATCH\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_ExpirePending","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/system/system_procedures.sql:38 (dbo.sp_Order_ExpirePending)\r\nCREATE   PROCEDURE dbo.sp_Order_ExpirePending\r\n(\r\n    @SuatChieuID INT = NULL,\r\n    @TraVeKetQua BIT = 1   -- 0 khi gọi lồng trong thủ tục khác (không trả recordset)\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    DECLARE @TuMoTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\r\n    DECLARE @Het TABLE (DonDatVeID INT PRIMARY KEY, KhuyenMaiID INT NULL);\r\n    DECLARE @SoDon INT = 0;\r\n\r\n    BEGIN TRY\r\n        IF @TuMoTran = 1\r\n            BEGIN TRANSACTION;\r\n        ELSE\r\n            SAVE TRANSACTION sp_Order_ExpirePending;\r\n\r\n        UPDATE d\r\n        SET d.TrangThai = N''Hết hạn''\r\n        OUTPUT inserted.DonDatVeID, inserted.KhuyenMaiID INTO @Het (DonDatVeID, KhuyenMaiID)\r\n        FROM dbo.DONDATVE d\r\n        WHERE d.TrangThai = N''Chờ thanh toán''\r\n          AND (d.HanGiuCho IS NULL OR d.HanGiuCho <= dbo.fn_BayGio())\n          AND (@SuatChieuID IS NULL OR d.SuatChieuID = @SuatChieuID);\r\n\r\n        SET @SoDon = @@ROWCOUNT;\r\n\r\n        IF @SoDon > 0\r\n        BEGIN\r\n            UPDATE cv\r\n            SET cv.TrangThai = N''Đã hủy''\r\n            FROM dbo.CHITIETVE cv\r\n            INNER JOIN @Het h ON h.DonDatVeID = cv.DonDatVeID\r\n            WHERE cv.TrangThai <> N''Đã hủy'';\r\n\r\n            UPDATE km\r\n            SET km.SoLuongDaDung = CASE WHEN km.SoLuongDaDung >= x.SoLan THEN km.SoLuongDaDung - x.SoLan ELSE 0 END\r\n            FROM dbo.KHUYENMAI km\r\n            INNER JOIN (SELECT KhuyenMaiID, COUNT(*) AS SoLan FROM @Het WHERE KhuyenMaiID IS NOT NULL GROUP BY KhuyenMaiID) x\r\n                ON x.KhuyenMaiID = km.KhuyenMaiID;\r\n        END\r\n\r\n        IF @TuMoTran = 1\r\n            COMMIT TRANSACTION;\r\n    END TRY\r\n    BEGIN CATCH\r\n        IF XACT_STATE() = -1\r\n            ROLLBACK TRANSACTION;\r\n        ELSE IF XACT_STATE() = 1\r\n        BEGIN\r\n            IF @TuMoTran = 1\r\n                ROLLBACK TRANSACTION;\r\n            ELSE\r\n                ROLLBACK TRANSACTION sp_Order_ExpirePending;\r\n        END\r\n        ;THROW;\r\n    END CATCH\r\n\r\n    IF @TraVeKetQua = 1\r\n        SELECT @SoDon AS SoDonHetHan;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_GetDetailByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Order_GetDetailByCustomer @NguoiDungID INT, @DonDatVeID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.DONDATVE WHERE DonDatVeID=@DonDatVeID AND NguoiDungID=@NguoiDungID)\n        THROW 50033, N''Đơn đặt vé không tồn tại hoặc bạn không có quyền xem đơn này.'', 1;\n    DECLARE @SuatID INT = (SELECT SuatChieuID FROM dbo.DONDATVE WHERE DonDatVeID=@DonDatVeID);\n    EXEC dbo.sp_Order_ExpirePending @SuatChieuID=@SuatID, @TraVeKetQua=0;\n    SELECT v.[DonDatVeID], v.[NguoiDungID], v.[HoTenKhachHang], v.[Email], v.[SoDienThoai], v.[SuatChieuID], v.[PhimID], v.[TenPhim], v.[PosterURL], v.[DoTuoi], v.[ThoiLuong], v.[RapID], v.[TenRap], v.[DiaChiRap], v.[PhongID], v.[TenPhong], v.[LoaiPhong], v.[ThoiGianBatDau], v.[ThoiGianKetThuc], v.[DinhDang], v.[NgayDat], v.[TongTienVe], v.[TongTienDoAn], v.[TienGiamGia], v.[TongTienThanhToan], v.[TrangThaiDon], v.[HanGiuCho], v.[MaKhuyenMai], v.[MoTaKhuyenMai], v.[DanhSachGhe], v.[DanhSachMaVe],d.LyDoHuy,d.ThongBaoHuy\n        ,b.DiemBoiThuong,b.NgayBoiThuong\n    FROM dbo.vw_ChiTietDonDatVe v INNER JOIN dbo.DONDATVE d ON d.DonDatVeID=v.DonDatVeID\n    LEFT JOIN dbo.BOITHUONG_HUYSUAT b ON b.DonDatVeID=d.DonDatVeID WHERE v.DonDatVeID=@DonDatVeID;\n    SELECT cv.VeID,cv.MaVe,g.GheID,g.HangGhe,g.SoGhe,(g.HangGhe+CAST(g.SoGhe AS VARCHAR(10))) AS TenGhe,g.LoaiGhe,cv.GiaVe,cv.TrangThai AS TrangThaiVe\n    FROM dbo.CHITIETVE cv INNER JOIN dbo.GHE g ON g.GheID=cv.GheID WHERE cv.DonDatVeID=@DonDatVeID;\n    SELECT cda.ChiTietDoAnID,sp.SanPhamID,sp.TenSanPham,sp.LoaiSanPham,cda.SoLuong,cda.DonGia,cda.SoLuong*cda.DonGia AS ThanhTien\n    FROM dbo.CHITIETDOAN cda INNER JOIN dbo.SANPHAM sp ON sp.SanPhamID=cda.SanPhamID WHERE cda.DonDatVeID=@DonDatVeID;\n    SELECT ThanhToanID,PhuongThuc,SoTien,NgayTao,NgayThanhToan,MaGiaoDich,TrangThai,GhiChu FROM dbo.THANHTOAN WHERE DonDatVeID=@DonDatVeID ORDER BY ThanhToanID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_ListByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Order_ListByCustomer @NguoiDungID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    SELECT v.[DonDatVeID], v.[NguoiDungID], v.[HoTenKhachHang], v.[Email], v.[SoDienThoai], v.[SuatChieuID], v.[PhimID], v.[TenPhim], v.[PosterURL], v.[RapID], v.[TenRap], v.[TenPhong], v.[ThoiGianBatDau], v.[ThoiGianKetThuc], v.[DinhDang], v.[NgayDat], v.[TongTienVe], v.[TongTienDoAn], v.[TienGiamGia], v.[TongTienThanhToan], v.[TrangThaiDon], v.[HanGiuCho], v.[MaKhuyenMai], v.[SoLuongVe], v.[TrangThaiThanhToanMoiNhat],d.LyDoHuy,d.ThongBaoHuy\n    FROM dbo.vw_LichSuDatVe v INNER JOIN dbo.DONDATVE d ON d.DonDatVeID=v.DonDatVeID\n    WHERE v.NguoiDungID=@NguoiDungID ORDER BY v.NgayDat DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Payment_CreateAttempt","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:257 (dbo.sp_Payment_CreateAttempt)\nCREATE   PROCEDURE dbo.sp_Payment_CreateAttempt\n\n    @NguoiDungID INT,\n    @DonDatVeID INT, @PhuongThuc NVARCHAR(50), @ThanhToanID INT OUTPUT, @MaGiaoDich VARCHAR(100) OUTPUT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''THANH_TOAN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTran BIT=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n        IF @OwnTran=1 BEGIN TRANSACTION ELSE SAVE TRANSACTION PaymentCreateAttempt;\n        DECLARE @UserID INT, @SuatID INT, @RoomID INT, @ShowStatus NVARCHAR(50), @Starts DATETIME2,\n                @OrderStatus NVARCHAR(50), @Hold DATETIME2, @Amount DECIMAL(18,2), @Now DATETIME2;\n        SELECT @UserID=NguoiDungID,@SuatID=SuatChieuID FROM dbo.DONDATVE WHERE DonDatVeID=@DonDatVeID;\n        IF @UserID IS NULL THROW 50030, N''Đơn đặt vé không tồn tại.'', 1;\n        IF @UserID <> @NguoiDungID THROW 50033, N''Đơn đặt vé không tồn tại.'', 1;\n        DECLARE @LockedUser INT;\n        SELECT @LockedUser=NguoiDungID FROM dbo.NGUOIDUNG WITH (UPDLOCK,HOLDLOCK) WHERE NguoiDungID=@UserID;\n        SELECT @RoomID=PhongID,@ShowStatus=TrangThai,@Starts=ThoiGianBatDau\n        FROM dbo.SUATCHIEU WITH (UPDLOCK,HOLDLOCK) WHERE SuatChieuID=@SuatID;\n        SELECT @OrderStatus=TrangThai,@Hold=HanGiuCho,@Amount=TongTienVe+TongTienDoAn-TienGiamGia\n        FROM dbo.DONDATVE WITH (UPDLOCK,HOLDLOCK) WHERE DonDatVeID=@DonDatVeID;\n        SET @Now=dbo.fn_BayGio(); -- Re-read after waiting for all lifecycle locks.\n        IF @OrderStatus=N''Hết hạn'' OR (@OrderStatus=N''Chờ thanh toán'' AND (@Hold IS NULL OR @Hold<=@Now))\n        BEGIN\n            EXEC dbo.sp_Order_ExpirePending @SuatChieuID=@SuatID, @TraVeKetQua=0;\n            IF @OwnTran=1 COMMIT TRANSACTION;\n            THROW 50111, N''Đơn đã hết thời gian giữ ghế. Vui lòng đặt vé lại.'', 1;\n        END;\n        IF @OrderStatus<>N''Chờ thanh toán'' THROW 50031, N''Đơn hàng không ở trạng thái Chờ thanh toán.'', 1;\n        IF @RoomID IS NULL OR @ShowStatus<>N''Mở bán'' OR @Starts<=@Now THROW 50121, N''Suất chiếu không còn hợp lệ để thanh toán.'', 1;\n        SET @MaGiaoDich=CONCAT(''TXN-'',FORMAT(@Now,''yyyyMMddHHmmss''),''-'',CAST(@DonDatVeID AS VARCHAR(10)),''-'',LEFT(REPLACE(CONVERT(VARCHAR(36),NEWID()),''-'',''''),6));\n        INSERT dbo.THANHTOAN(DonDatVeID,PhuongThuc,SoTien,NgayTao,MaGiaoDich,TrangThai) VALUES(@DonDatVeID,@PhuongThuc,@Amount,@Now,@MaGiaoDich,N''Đang xử lý'');\n        SET @ThanhToanID=SCOPE_IDENTITY();\n        IF @OwnTran=1 COMMIT TRANSACTION;\n        SELECT tt.ThanhToanID,tt.DonDatVeID,tt.PhuongThuc,tt.SoTien,tt.NgayTao,tt.MaGiaoDich,tt.TrangThai,d.HanGiuCho\n        FROM dbo.THANHTOAN tt INNER JOIN dbo.DONDATVE d ON d.DonDatVeID=tt.DonDatVeID WHERE tt.ThanhToanID=@ThanhToanID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE()=-1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE()=1 BEGIN IF @OwnTran=1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION PaymentCreateAttempt; END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Payment_UpdateResult","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:293 (dbo.sp_Payment_UpdateResult)\nCREATE   PROCEDURE dbo.sp_Payment_UpdateResult\n\n    @NguoiDungID INT,\n    @ThanhToanID INT, @TrangThaiThanhToan NVARCHAR(50), @MaGiaoDichNgoai VARCHAR(100)=NULL, @GhiChu NVARCHAR(255)=NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''THANH_TOAN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTran BIT=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n        IF @TrangThaiThanhToan NOT IN (N''Thành công'',N''Thất bại'') THROW 50114, N''Kết quả thanh toán phải là Thành công hoặc Thất bại.'', 1;\n        IF @OwnTran=1 BEGIN TRANSACTION ELSE SAVE TRANSACTION PaymentUpdateResult;\n        DECLARE @UserID INT,@SuatID INT,@LockedUser INT,@ShowStatus NVARCHAR(50),@Starts DATETIME2,@DonID INT,\n            @Amount DECIMAL(18,2),@CurrentPayment NVARCHAR(50),@OrderStatus NVARCHAR(50),@Hold DATETIME2,\n            @Now DATETIME2;\n        SELECT @UserID=d.NguoiDungID,@SuatID=d.SuatChieuID FROM dbo.THANHTOAN t INNER JOIN dbo.DONDATVE d ON d.DonDatVeID=t.DonDatVeID WHERE t.ThanhToanID=@ThanhToanID;\n        IF @UserID IS NULL THROW 50032, N''Giao dịch thanh toán không tồn tại.'', 1;\n        IF @UserID <> @NguoiDungID THROW 50033, N''Đơn đặt vé không tồn tại.'', 1;\n        SELECT @LockedUser=NguoiDungID FROM dbo.NGUOIDUNG WITH (UPDLOCK,HOLDLOCK) WHERE NguoiDungID=@UserID;\n        SELECT @ShowStatus=TrangThai,@Starts=ThoiGianBatDau FROM dbo.SUATCHIEU WITH (UPDLOCK,HOLDLOCK) WHERE SuatChieuID=@SuatID;\n        SELECT @DonID=t.DonDatVeID,@Amount=t.SoTien,@CurrentPayment=t.TrangThai,@OrderStatus=d.TrangThai,@Hold=d.HanGiuCho\n        FROM dbo.THANHTOAN t WITH (UPDLOCK,HOLDLOCK) INNER JOIN dbo.DONDATVE d WITH (UPDLOCK,HOLDLOCK) ON d.DonDatVeID=t.DonDatVeID WHERE t.ThanhToanID=@ThanhToanID;\n        IF @CurrentPayment=@TrangThaiThanhToan\n        BEGIN\n            IF @OwnTran=1 COMMIT TRANSACTION;\n            SELECT d.DonDatVeID,d.TrangThai AS TrangThaiDon,t.ThanhToanID,t.MaGiaoDich,t.TrangThai AS TrangThaiThanhToan,t.NgayThanhToan FROM dbo.DONDATVE d JOIN dbo.THANHTOAN t ON t.DonDatVeID=d.DonDatVeID WHERE t.ThanhToanID=@ThanhToanID;\n            RETURN;\n        END\n        IF @CurrentPayment<>N''Đang xử lý'' THROW 50115, N''Giao dịch đã có kết quả cuối cùng, không thể đổi.'', 1;\n        SET @Now=dbo.fn_BayGio(); -- A lock wait must never extend the hold deadline.\n        IF @OrderStatus=N''Hết hạn'' OR (@OrderStatus=N''Chờ thanh toán'' AND (@Hold IS NULL OR @Hold<=@Now))\n        BEGIN\n            EXEC dbo.sp_Order_ExpirePending @SuatChieuID=@SuatID, @TraVeKetQua=0;\n            IF @OwnTran=1 COMMIT TRANSACTION;\n            THROW 50111, N''Đơn đã hết thời gian giữ ghế. Vui lòng đặt vé lại.'', 1;\n        END;\n        IF @TrangThaiThanhToan=N''Thành công''\n        BEGIN\n            IF @OrderStatus<>N''Chờ thanh toán'' THROW 50113, N''Đơn hàng không còn ở trạng thái có thể thanh toán.'', 1;\n            IF @ShowStatus<>N''Mở bán'' OR @Starts<=@Now THROW 50121, N''Suất chiếu không còn hợp lệ để thanh toán.'', 1;\n            UPDATE dbo.THANHTOAN SET TrangThai=N''Thành công'',NgayThanhToan=@Now,MaGiaoDich=ISNULL(@MaGiaoDichNgoai,MaGiaoDich),GhiChu=@GhiChu WHERE ThanhToanID=@ThanhToanID;\n            UPDATE dbo.DONDATVE SET TrangThai=N''Đã thanh toán'',HanGiuCho=NULL WHERE DonDatVeID=@DonID;\n            DECLARE @Points INT=CAST(@Amount/1000 AS INT);\n            IF @Points>0 UPDATE dbo.HOSOKHACHHANG SET DiemTichLuy=DiemTichLuy+@Points WHERE NguoiDungID=@UserID;\n        END\n        ELSE\n        BEGIN\n            UPDATE dbo.THANHTOAN SET TrangThai=N''Thất bại'',NgayThanhToan=NULL,MaGiaoDich=ISNULL(@MaGiaoDichNgoai,MaGiaoDich),GhiChu=@GhiChu WHERE ThanhToanID=@ThanhToanID;\n        END\n        IF @OwnTran=1 COMMIT TRANSACTION;\n        SELECT d.DonDatVeID,d.TrangThai AS TrangThaiDon,d.HanGiuCho,t.ThanhToanID,t.MaGiaoDich,t.TrangThai AS TrangThaiThanhToan,t.NgayThanhToan\n        FROM dbo.DONDATVE d JOIN dbo.THANHTOAN t ON t.DonDatVeID=d.DonDatVeID WHERE t.ThanhToanID=@ThanhToanID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE()=-1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE()=1 BEGIN IF @OwnTran=1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION PaymentUpdateResult; END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Product_ListActive","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Product_ListActive\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        SanPhamID,\r\n        TenSanPham,\r\n        LoaiSanPham,\r\n        Gia,\r\n        MoTa,\r\n        HinhAnh,\r\n        TrangThai\r\n    FROM dbo.SANPHAM\r\n    WHERE TrangThai = N''Đang bán''\r\n    ORDER BY LoaiSanPham, Gia;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Promotion_Validate","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/012_booking_limits_and_pricing.sql:151 (dbo.sp_Promotion_Validate)\nCREATE   PROCEDURE dbo.sp_Promotion_Validate\n(\n    @NguoiDungID INT,\n    @MaCode VARCHAR(50),\n    @TongTienDon DECIMAL(18,2),\n    @KhuyenMaiID INT OUTPUT,\n    @LoaiGiamGia NVARCHAR(20) OUTPUT,\n    @GiaTriGiam DECIMAL(18,2) OUTPUT,\n    @TienGiam DECIMAL(18,2) OUTPUT,\n    @IsValid BIT OUTPUT,\n    @Message NVARCHAR(255) OUTPUT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''DAT_VE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    SET @IsValid = 0;\n    SET @TienGiam = 0;\n    SET @KhuyenMaiID = NULL;\n\n    DECLARE @DonHangToiThieu DECIMAL(18,2);\n    DECLARE @GiamToiDa DECIMAL(18,2);\n    DECLARE @NgayBatDau DATETIME2;\n    DECLARE @NgayKetThuc DATETIME2;\n    DECLARE @SoLuong INT;\n    DECLARE @SoLuongDaDung INT;\n    DECLARE @TrangThai NVARCHAR(50);\n\n    SELECT\n        @KhuyenMaiID = KhuyenMaiID,\n        @LoaiGiamGia = LoaiGiamGia,\n        @GiaTriGiam = GiaTriGiam,\n        @DonHangToiThieu = DonHangToiThieu,\n        @GiamToiDa = GiamToiDa,\n        @NgayBatDau = NgayBatDau,\n        @NgayKetThuc = NgayKetThuc,\n        @SoLuong = SoLuong,\n        @SoLuongDaDung = SoLuongDaDung,\n        @TrangThai = TrangThai\n    FROM dbo.KHUYENMAI\n    WHERE MaCode = @MaCode;\n\n    IF @KhuyenMaiID IS NULL\n    BEGIN\n        SET @Message = N''Mã khuyến mãi không tồn tại.'';\n        RETURN;\n    END\n\n    IF @TrangThai <> N''Hoạt động''\n    BEGIN\n        SET @Message = N''Mã khuyến mãi không còn hoạt động.'';\n        RETURN;\n    END\n\n    IF dbo.fn_BayGio() < @NgayBatDau OR dbo.fn_BayGio() > @NgayKetThuc\n    BEGIN\n        SET @Message = N''Mã khuyến mãi chưa tới ngày áp dụng hoặc đã hết hạn.'';\n        RETURN;\n    END\n\n    IF @SoLuongDaDung >= @SoLuong\n    BEGIN\n        SET @Message = N''Mã khuyến mãi đã hết lượt sử dụng.'';\n        RETURN;\n    END\n\n    IF @TongTienDon < @DonHangToiThieu\n    BEGIN\n        SET @Message = N''Đơn hàng chưa đạt giá trị tối thiểu '' + FORMAT(@DonHangToiThieu, ''N0'') + '' đ để áp dụng mã này.'';\n        RETURN;\n    END\n\n    -- Tính tiền giảm\n    IF @LoaiGiamGia IN (N''Phần trăm'', N''PERCENT'')\n    BEGIN\n        SET @TienGiam = (@TongTienDon * @GiaTriGiam) / 100.0;\n        IF @GiamToiDa IS NOT NULL AND @TienGiam > @GiamToiDa\n            SET @TienGiam = @GiamToiDa;\n    END\n    ELSE\n    BEGIN\n        SET @TienGiam = @GiaTriGiam;\n    END\n\n    -- Mọi loại khuyến mãi: mức giảm tối đa 99% tổng tạm tính (cắt bớt, không làm tròn lên) để tổng đơn luôn > 0\n    DECLARE @TranGiam DECIMAL(18,2) = ROUND(@TongTienDon * dbo.fn_GioiHanGiamGiaPhanTram() / 100.0, 2, 1);\n    IF @TienGiam > @TranGiam\n        SET @TienGiam = @TranGiam;\n\n    SET @IsValid = 1;\n    SET @Message = N''Áp dụng mã khuyến mãi thành công.'';\n\n    SELECT\n        @IsValid AS IsValid,\n        @KhuyenMaiID AS KhuyenMaiID,\n        @MaCode AS MaCode,\n        @LoaiGiamGia AS LoaiGiamGia,\n        @GiaTriGiam AS GiaTriGiam,\n        @TienGiam AS TienGiam,\n        @Message AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_PhanCongQuanLyRap","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_PhanCongQuanLyRap\n(\n    @ActorID INT,\n    @NguoiDungID INT,\n    @RapID INT,\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL\n)\nAS\nBEGIN\n        SET NOCOUNT ON;\nEXEC dbo.sp_Admin_Assignment_Create\n        @ActorID = @ActorID,\n        @NguoiDungID = @NguoiDungID,\n        @RapID = @RapID,\n        @NgayBatDau = @NgayBatDau,\n        @NgayKetThuc = @NgayKetThuc;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_RBAC_GetPermissionsByUser","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_RBAC_GetPermissionsByUser\r\n(\r\n    @NguoiDungID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT DISTINCT q.QuyenID, q.MaQuyen, q.TenQuyen, q.MoTa\r\n    FROM dbo.NGUOIDUNG nd\r\n    INNER JOIN dbo.VAITRO_QUYEN vq ON nd.VaiTroID = vq.VaiTroID\r\n    INNER JOIN dbo.QUYEN q ON vq.QuyenID = q.QuyenID\r\n    WHERE nd.NguoiDungID = @NguoiDungID AND nd.TrangThai = N''Hoạt động'';\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Review_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/customer/customer_procedures.sql:1214 (dbo.sp_Review_Create)\nCREATE   PROCEDURE dbo.sp_Review_Create\n(\n    @NguoiDungID INT,\n    @PhimID INT,\n    @SoSao INT,\n    @NoiDung NVARCHAR(1000) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''KHACH_HANG''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''DANH_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    -- Kiểm tra đã đánh giá chưa\n    IF EXISTS (SELECT 1 FROM dbo.DANHGIAPHIM WHERE PhimID = @PhimID AND NguoiDungID = @NguoiDungID)\n    BEGIN\n        ;THROW 50040, N''Bạn đã đánh giá phim này rồi.'', 1;\n    END\n\n    -- Chèn bản ghi đánh giá (Trigger TRG_DanhGia_KiemTraDaXemPhim sẽ tự kiểm tra đã xem phim chưa)\n    INSERT INTO dbo.DANHGIAPHIM (PhimID, NguoiDungID, SoSao, NoiDung, NgayDanhGia)\n    VALUES (@PhimID, @NguoiDungID, @SoSao, @NoiDung, dbo.fn_BayGio());\n\n    SELECT\n        DanhGiaID,\n        PhimID,\n        NguoiDungID,\n        SoSao,\n        NoiDung,\n        NgayDanhGia\n    FROM dbo.DANHGIAPHIM\n    WHERE DanhGiaID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Review_ListByMovie","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Review_ListByMovie\r\n(\r\n    @PhimID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        dg.DanhGiaID,\r\n        dg.PhimID,\r\n        dg.NguoiDungID,\r\n        nd.HoTen AS NguoiDanhGia,\r\n        dg.SoSao,\r\n        dg.NoiDung,\r\n        dg.NgayDanhGia\r\n    FROM dbo.DANHGIAPHIM dg\r\n    INNER JOIN dbo.NGUOIDUNG nd ON dg.NguoiDungID = nd.NguoiDungID\r\n    WHERE dg.PhimID = @PhimID\r\n    ORDER BY dg.NgayDanhGia DESC;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Seat_ListByShowtime","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Seat_ListByShowtime\r\n(\r\n    @SuatChieuID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        GheID,\r\n        PhongID,\r\n        HangGhe,\r\n        SoGhe,\r\n        TenGhe,\r\n        LoaiGhe,\r\n        GiaVe,\r\n        TrangThaiGhe\r\n    FROM dbo.fn_DanhSachGheSuatChieu(@SuatChieuID)\r\n    ORDER BY HangGhe, SoGhe;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_CancelCascade","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:36 (dbo.sp_Showtime_CancelCascade)\nCREATE   PROCEDURE dbo.sp_Showtime_CancelCascade\n    @SuatChieuID INT,\n    @NguoiDungID INT,\n    @LyDo NVARCHAR(255) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    DECLARE @OwnTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n    DECLARE @Status NVARCHAR(50), @StartsAt DATETIME2, @RapID INT, @Now DATETIME2;\n    DECLARE @Dummy INT, @Cancelled INT = 0;\n    DECLARE @Orders TABLE (DonDatVeID INT PRIMARY KEY, NguoiDungID INT, KhuyenMaiID INT NULL, TrangThai NVARCHAR(50));\n    DECLARE @Credits TABLE (DonDatVeID INT, DiemBoiThuong INT);\n    BEGIN TRY\n        IF @OwnTran = 1 BEGIN TRANSACTION ELSE SAVE TRANSACTION ShowtimeCancelCascade;\n\n        -- Customer-first locking matches sp_Booking_Create and payment procedures.\n        -- The serializable scan also prevents a new customer row appearing mid-cancel.\n        SELECT @Dummy = MAX(NguoiDungID) FROM dbo.NGUOIDUNG WITH (UPDLOCK, HOLDLOCK);\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''ADMIN'', ''QUAN_LY_RAP''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n        SELECT @Status = sc.TrangThai, @StartsAt = sc.ThoiGianBatDau, @RapID = pc.RapID\n        FROM dbo.SUATCHIEU sc WITH (UPDLOCK, HOLDLOCK)\n        INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID = sc.PhongID\n        WHERE sc.SuatChieuID = @SuatChieuID;\n        IF @Status IS NULL THROW 50116, N''Suất chiếu không tồn tại.'', 1;\n        IF EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd JOIN dbo.VAITRO vt ON vt.VaiTroID=nd.VaiTroID WHERE nd.NguoiDungID=@NguoiDungID AND vt.MaVaiTro=''QUAN_LY_RAP'')\n           AND dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        SET @Now = dbo.fn_BayGio();\n        IF @Status = N''Đã hủy''\n        BEGIN\n            IF @OwnTran = 1 COMMIT TRANSACTION;\n            SELECT N''Suất chiếu đã được hủy.'' AS [Message], 0 AS SoDonDaHuy;\n            RETURN;\n        END;\n        IF @Status = N''Hoàn thành'' OR @StartsAt <= @Now\n            THROW 50119, N''Không thể hủy suất chiếu đã bắt đầu hoặc đã bị hủy.'', 1;\n\n        -- The customer/showtime locks serialize booking, payment and concurrent cancellation.\n        IF EXISTS (SELECT 1 FROM dbo.DONDATVE WITH (UPDLOCK, HOLDLOCK)\n                   WHERE SuatChieuID = @SuatChieuID AND TrangThai = N''Chờ thanh toán'' AND HanGiuCho > @Now)\n            THROW 50118, N''Không thể hủy suất chiếu vì còn đơn giữ ghế/chờ thanh toán còn hiệu lực.'', 1;\n\n        EXEC dbo.sp_Order_ExpirePending @SuatChieuID = @SuatChieuID, @TraVeKetQua = 0;\n\n        INSERT @Orders (DonDatVeID, NguoiDungID, KhuyenMaiID, TrangThai)\n        SELECT d.DonDatVeID, d.NguoiDungID, d.KhuyenMaiID, d.TrangThai\n        FROM dbo.DONDATVE d WITH (UPDLOCK, HOLDLOCK)\n        WHERE d.SuatChieuID = @SuatChieuID\n          AND d.TrangThai = N''Đã thanh toán'';\n\n        -- Release only promo uses still counted (unexpired holds and paid orders).\n        UPDATE km\n        SET SoLuongDaDung = CASE WHEN km.SoLuongDaDung >= x.SoLan THEN km.SoLuongDaDung - x.SoLan ELSE 0 END\n        FROM dbo.KHUYENMAI km\n        INNER JOIN (\n            SELECT KhuyenMaiID, COUNT(*) AS SoLan FROM @Orders\n            WHERE KhuyenMaiID IS NOT NULL AND TrangThai IN (N''Chờ thanh toán'', N''Đã thanh toán'')\n            GROUP BY KhuyenMaiID\n        ) x ON x.KhuyenMaiID = km.KhuyenMaiID;\n\n        -- No payment writes and no reversal of previously earned loyalty points.\n        -- Only the actual event points are persisted. Order snapshots stay in DONDATVE.\n        DECLARE @DonID INT, @TongTienVe DECIMAL(18,2), @TongTienDoAn DECIMAL(18,2),\n                @TienGiamGia DECIMAL(18,2), @TongTruocGiam DECIMAL(19,2),\n                @GiamChoVe DECIMAL(38,6), @TienVeThucTra DECIMAL(38,6), @DiemBoiThuong INT;\n        DECLARE CompensationOrders CURSOR LOCAL FAST_FORWARD FOR\n            SELECT d.DonDatVeID, d.TongTienVe, d.TongTienDoAn, d.TienGiamGia\n            FROM dbo.DONDATVE d INNER JOIN @Orders o ON o.DonDatVeID = d.DonDatVeID\n            WHERE EXISTS (SELECT 1 FROM dbo.THANHTOAN t WHERE t.DonDatVeID = d.DonDatVeID AND t.TrangThai = N''Thành công'')\n              AND NOT EXISTS (SELECT 1 FROM dbo.BOITHUONG_HUYSUAT b WITH (UPDLOCK, HOLDLOCK) WHERE b.DonDatVeID = d.DonDatVeID);\n        OPEN CompensationOrders;\n        FETCH NEXT FROM CompensationOrders INTO @DonID, @TongTienVe, @TongTienDoAn, @TienGiamGia;\n        WHILE @@FETCH_STATUS = 0\n        BEGIN\n            SET @TongTruocGiam = @TongTienVe + @TongTienDoAn;\n            SET @GiamChoVe = ISNULL(@TienGiamGia * @TongTienVe / NULLIF(@TongTruocGiam, 0), 0);\n            SET @TienVeThucTra = CASE WHEN @TongTruocGiam = 0 OR @GiamChoVe >= @TongTienVe THEN 0\n                                     ELSE @TongTienVe - @GiamChoVe END;\n            -- Preserve R2''s exact final FLOOR, including sub-point division boundaries.\n            -- The helper works from DECIMAL cents, so intermediate display precision cannot round points up.\n            SELECT @DiemBoiThuong = CONVERT(INT, c.DiemCong)\n            FROM dbo.fn_TinhBoiThuongVe(@TongTienVe, @TongTienDoAn, @TienGiamGia) c;\n            INSERT dbo.BOITHUONG_HUYSUAT (DonDatVeID, DiemBoiThuong, NgayBoiThuong, GhiChu)\n            OUTPUT inserted.DonDatVeID, inserted.DiemBoiThuong INTO @Credits\n            VALUES (@DonID, @DiemBoiThuong, @Now,\n                    CASE WHEN @NguoiDungID IS NULL THEN NULL ELSE CONCAT(N''Người thực hiện ID: '', @NguoiDungID) END);\n            FETCH NEXT FROM CompensationOrders INTO @DonID, @TongTienVe, @TongTienDoAn, @TienGiamGia;\n        END;\n        CLOSE CompensationOrders;\n        DEALLOCATE CompensationOrders;\n\n        INSERT dbo.HOSOKHACHHANG (NguoiDungID, DiemTichLuy)\n        SELECT DISTINCT o.NguoiDungID, 0 FROM @Credits c INNER JOIN @Orders o ON o.DonDatVeID=c.DonDatVeID\n        WHERE NOT EXISTS (SELECT 1 FROM dbo.HOSOKHACHHANG h WITH (UPDLOCK, HOLDLOCK) WHERE h.NguoiDungID = o.NguoiDungID);\n\n        UPDATE h SET DiemTichLuy = h.DiemTichLuy + c.Points\n        FROM dbo.HOSOKHACHHANG h\n        INNER JOIN (SELECT o.NguoiDungID, SUM(CONVERT(BIGINT, c.DiemBoiThuong)) AS Points\n                    FROM @Credits c INNER JOIN @Orders o ON o.DonDatVeID=c.DonDatVeID GROUP BY o.NguoiDungID) c\n            ON c.NguoiDungID = h.NguoiDungID;\n\n        UPDATE cv SET TrangThai = N''Đã hủy''\n        FROM dbo.CHITIETVE cv INNER JOIN @Orders o ON o.DonDatVeID = cv.DonDatVeID\n        WHERE cv.TrangThai <> N''Đã hủy'';\n\n        UPDATE d\n        SET TrangThai = N''Đã hủy'', HanGiuCho = NULL,\n            LyDoHuy = @LyDo,\n            ThongBaoHuy = N''Suất chiếu đã bị hủy. Điểm bồi thường phần vé đã được cộng vào tài khoản (1.000 VNĐ = 1 điểm).''\n        FROM dbo.DONDATVE d INNER JOIN @Orders o ON o.DonDatVeID = d.DonDatVeID;\n        SET @Cancelled = @@ROWCOUNT;\n\n        UPDATE dbo.SUATCHIEU SET TrangThai = N''Đã hủy'' WHERE SuatChieuID = @SuatChieuID;\n        IF @OwnTran = 1 COMMIT TRANSACTION;\n        SELECT CASE WHEN @NguoiDungID IS NULL THEN N''Đã hủy suất chiếu.'' ELSE N''Hủy suất chiếu thành công.'' END AS [Message], @Cancelled AS SoDonDaHuy;\n    END TRY\n    BEGIN CATCH\n        IF CURSOR_STATUS(''local'', ''CompensationOrders'') >= 0 CLOSE CompensationOrders;\n        IF CURSOR_STATUS(''local'', ''CompensationOrders'') >= -1 DEALLOCATE CompensationOrders;\n        IF XACT_STATE() = -1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE() = 1\n        BEGIN\n            IF @OwnTran = 1 ROLLBACK TRANSACTION;\n            ELSE ROLLBACK TRANSACTION ShowtimeCancelCascade;\n        END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_GetDetail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Showtime_GetDetail\r\n(\r\n    @SuatChieuID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        SuatChieuID,\r\n        PhimID,\r\n        TenPhim,\r\n        PosterURL,\r\n        ThoiLuong,\r\n        DoTuoi,\r\n        RapID,\r\n        TenRap,\r\n        DiaChiRap,\r\n        ThanhPho,\r\n        PhongID,\r\n        TenPhong,\r\n        LoaiPhong,\r\n        ThoiGianBatDau,\r\n        ThoiGianKetThuc,\r\n        NgayChieu,\r\n        GioBatDau,\r\n        GioKetThuc,\r\n        DinhDang,\r\n        GiaVeCoBan,\r\n        TrangThaiSuatChieu,\r\n        TongSoGhe,\r\n        SoGheDaDat,\r\n        (TongSoGhe - SoGheDaDat) AS SoGheConLai\r\n    FROM dbo.vw_LichChieuChiTiet\r\n    WHERE SuatChieuID = @SuatChieuID;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_ListByMovie","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/customer/customer_procedures.sql:164 (dbo.sp_Showtime_ListByMovie)\r\nCREATE   PROCEDURE dbo.sp_Showtime_ListByMovie\r\n(\r\n    @PhimID INT,\r\n    @RapID INT = NULL,\r\n    @NgayChieu DATE = NULL\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        SuatChieuID,\r\n        PhimID,\r\n        TenPhim,\r\n        PosterURL,\r\n        ThoiLuong,\r\n        DoTuoi,\r\n        RapID,\r\n        TenRap,\r\n        DiaChiRap,\r\n        ThanhPho,\r\n        PhongID,\r\n        TenPhong,\r\n        LoaiPhong,\r\n        ThoiGianBatDau,\r\n        ThoiGianKetThuc,\r\n        NgayChieu,\r\n        GioBatDau,\r\n        GioKetThuc,\r\n        DinhDang,\r\n        GiaVeCoBan,\r\n        TrangThaiSuatChieu,\r\n        TongSoGhe,\r\n        SoGheDaDat,\r\n        (TongSoGhe - SoGheDaDat) AS SoGheConLai\r\n    FROM dbo.vw_LichChieuChiTiet\r\n    WHERE PhimID = @PhimID\r\n      AND (@RapID IS NULL OR RapID = @RapID)\r\n      AND (@NgayChieu IS NULL OR NgayChieu = @NgayChieu)\r\n      AND TrangThaiSuatChieu = N''Mở bán''\r\n      AND ThoiGianBatDau > dbo.fn_BayGio()\r\n    ORDER BY ThoiGianBatDau ASC;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_ValidateTimes","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Showtime_ValidateTimes\r\n    @PhimID INT, @ThoiGianBatDau DATETIME2, @ThoiGianKetThuc DATETIME2\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    DECLARE @ThoiLuong INT = (SELECT ThoiLuong FROM dbo.PHIM WHERE PhimID=@PhimID);\r\n    DECLARE @Span DECIMAL(20,7)=DATEDIFF_BIG(SECOND,@ThoiGianBatDau,@ThoiGianKetThuc)\r\n        +(CONVERT(DECIMAL(20,7),DATEPART(NANOSECOND,@ThoiGianKetThuc))-DATEPART(NANOSECOND,@ThoiGianBatDau))/1000000000;\r\n    -- Unknown movie retains the existing FK/resource handling; no unrelated validation change.\r\n    IF @ThoiGianBatDau IS NULL OR @ThoiGianKetThuc IS NULL\r\n       OR @ThoiGianBatDau < dbo.fn_BayGio() OR @ThoiGianKetThuc <= @ThoiGianBatDau\r\n       OR @Span>28800\r\n       OR (@ThoiLuong IS NOT NULL AND\r\n           (@Span < CONVERT(BIGINT,@ThoiLuong)*60 OR @Span > (CONVERT(BIGINT,@ThoiLuong)+120)*60))\r\n        THROW 50216, N''Thời gian suất phải từ hiện tại, dài từ thời lượng phim đến thời lượng phim +120 phút và tối đa 8 giờ.'', 1;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_AddProcessing","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/006_support_procedure_authorization.sql:57 (dbo.sp_Support_Complaint_AddProcessing)\nCREATE   PROCEDURE dbo.sp_Support_Complaint_AddProcessing\n(\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @NoiDungXuLy NVARCHAR(MAX),\n    @TrangThaiSauXuLy NVARCHAR(50)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XULY_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (SELECT 1 FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID)\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n        INSERT INTO dbo.XULY_KHIEUNAI (KhieuNaiID, NguoiXuLyID, NoiDungXuLy, NgayXuLy, TrangThaiSauXuLy)\n        VALUES (@KhieuNaiID, @NguoiDungID, @NoiDungXuLy, dbo.fn_BayGio(), @TrangThaiSauXuLy);\n        COMMIT TRANSACTION;\n        SELECT XuLyID, KhieuNaiID, NguoiXuLyID, NoiDungXuLy, NgayXuLy, TrangThaiSauXuLy\n        FROM dbo.XULY_KHIEUNAI WHERE XuLyID = SCOPE_IDENTITY();\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_GetDetail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Phase 8 DBR-04: apply the same authorization and not-found guards that are\n-- present in the canonical support procedures. Migration 005 was already\n-- deployed before these guards were packaged, so this is deliberately separate.\nCREATE   PROCEDURE dbo.sp_Support_Complaint_GetDetail\n(\n    @NguoiDungID INT,\n    @KhieuNaiID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID)\n        THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n    SELECT kn.KhieuNaiID, kn.NguoiDungID AS NguoiGuiID, nd.HoTen AS HoTenNguoiGui,\n           nd.Email AS EmailNguoiGui, nd.SoDienThoai AS SoDienThoaiNguoiGui,\n           kn.DonDatVeID, kn.LoaiKhieuNai, kn.TieuDe, kn.NoiDung, kn.MucDoUuTien,\n           kn.NgayTao, kn.TrangThai AS TrangThaiKhieuNai\n    FROM dbo.KHIEUNAI kn INNER JOIN dbo.NGUOIDUNG nd ON kn.NguoiDungID = nd.NguoiDungID\n    WHERE kn.KhieuNaiID = @KhieuNaiID;\n    SELECT xl.XuLyID, xl.NguoiXuLyID, nd_xl.HoTen AS NguoiXuLy, xl.NoiDungXuLy,\n           xl.NgayXuLy, xl.TrangThaiSauXuLy\n    FROM dbo.XULY_KHIEUNAI xl INNER JOIN dbo.NGUOIDUNG nd_xl ON xl.NguoiXuLyID = nd_xl.NguoiDungID\n    WHERE xl.KhieuNaiID = @KhieuNaiID ORDER BY xl.NgayXuLy ASC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_GetOrderReference","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Support_Complaint_GetOrderReference\n(\n    @NguoiDungID INT,\n    @KhieuNaiID INT\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''TRA_CUU_DON'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID)\n        THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n    DECLARE @DonDatVeID INT;\n    SELECT @DonDatVeID = DonDatVeID FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID;\n    IF @DonDatVeID IS NULL\n    BEGIN\n        SELECT N''Khiếu nại này không gắn với đơn đặt vé tham chiếu cụ thể nào.'' AS [Message];\n        RETURN;\n    END;\n    SELECT DonDatVeID, NguoiDungID, HoTenKhachHang, Email, SoDienThoai, TenPhim, TenRap,\n           TenPhong, ThoiGianBatDau, ThoiGianKetThuc, DinhDang, NgayDat, TongTienVe,\n           TongTienDoAn, TienGiamGia, TongTienThanhToan, TrangThaiDon, DanhSachGhe, DanhSachMaVe\n    FROM dbo.vw_ChiTietDonDatVe WHERE DonDatVeID = @DonDatVeID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Support_Complaint_List\n(\n    @NguoiDungID INT,\n    @TrangThai NVARCHAR(50) = NULL,\n    @LoaiKhieuNai NVARCHAR(100) = NULL,\n    @SearchTerm NVARCHAR(100) = NULL\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n\n    SELECT\n        KhieuNaiID,\n        NguoiGuiID,\n        HoTenNguoiGui,\n        EmailNguoiGui,\n        SoDienThoaiNguoiGui,\n        DonDatVeID,\n        LoaiKhieuNai,\n        TieuDe,\n        NoiDung,\n        MucDoUuTien,\n        NgayTao,\n        TrangThaiKhieuNai,\n        SoLanXuLy,\n        NgayXuLyCuoi,\n        NguoiXuLyCuoi,\n        NoiDungXuLyCuoi\n    FROM dbo.vw_DanhSachKhieuNai\n    WHERE (@TrangThai IS NULL OR TrangThaiKhieuNai = @TrangThai)\n      AND (@LoaiKhieuNai IS NULL OR LoaiKhieuNai = @LoaiKhieuNai)\n      AND (@SearchTerm IS NULL OR TieuDe LIKE ''%'' + @SearchTerm + ''%'' OR HoTenNguoiGui LIKE ''%'' + @SearchTerm + ''%'' OR EmailNguoiGui LIKE ''%'' + @SearchTerm + ''%'')\n    ORDER BY\n        CASE MucDoUuTien WHEN N''Khẩn cấp'' THEN 1 WHEN N''Cao'' THEN 2 WHEN N''Trung bình'' THEN 3 ELSE 4 END ASC,\n        NgayTao DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_UpdateStatus","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/005_support_status_history_atomicity.sql:3 (dbo.sp_Support_Complaint_UpdateStatus)\nCREATE   PROCEDURE dbo.sp_Support_Complaint_UpdateStatus\n(\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @TrangThaiMoi NVARCHAR(50)\n)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XULY_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (SELECT 1 FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID)\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n        INSERT INTO dbo.XULY_KHIEUNAI (KhieuNaiID, NguoiXuLyID, NoiDungXuLy, NgayXuLy, TrangThaiSauXuLy)\n        VALUES (@KhieuNaiID, @NguoiDungID, N''Cập nhật trạng thái khiếu nại.'', dbo.fn_BayGio(), @TrangThaiMoi);\n        COMMIT TRANSACTION;\n        SELECT KhieuNaiID, TrangThai FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_System_HealthCheck","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_System_HealthCheck\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    SELECT\r\n        ''Healthy'' AS [Status],\r\n        dbo.fn_BayGio() AS [ServerTime],\n        DB_NAME() AS [DatabaseName],\r\n        @@VERSION AS [SQLVersion];\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_ThemSuatChieu","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_ThemSuatChieu\r\n(\r\n    @NguoiDungID INT,\r\n    @PhimID INT,\r\n    @PhongID INT,\r\n    @ThoiGianBatDau DATETIME2,\r\n    @ThoiGianKetThuc DATETIME2,\r\n    @DinhDang NVARCHAR(50) = N''2D'',\r\n    @GiaVeCoBan DECIMAL(18,2)\r\n)\r\nAS\r\nBEGIN\r\n        SET NOCOUNT ON;\r\nEXEC dbo.sp_Manager_Showtime_Create\r\n        @NguoiDungID = @NguoiDungID,\r\n        @PhimID = @PhimID,\r\n        @PhongID = @PhongID,\r\n        @ThoiGianBatDau = @ThoiGianBatDau,\r\n        @ThoiGianKetThuc = @ThoiGianKetThuc,\r\n        @DinhDang = @DinhDang,\r\n        @GiaVeCoBan = @GiaVeCoBan;\r\nEND;\r\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_ChangePassword","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_ChangePassword\r\n(\r\n    @NguoiDungID INT,\r\n    @NewPasswordHash VARCHAR(255)\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'')\r\n    BEGIN\r\n        ;THROW 50016, N''Tài khoản không tồn tại hoặc không hoạt động.'', 1;\r\n    END\r\n\r\n    UPDATE dbo.NGUOIDUNG\r\n    SET MatKhau = @NewPasswordHash\r\n    WHERE NguoiDungID = @NguoiDungID;\r\n\r\n    SELECT N''Đổi mật khẩu thành công.'' AS [Message];\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_GetCurrent","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_GetCurrent\r\n(\r\n    @NguoiDungID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        nd.NguoiDungID,\r\n        nd.HoTen,\r\n        nd.Email,\r\n        nd.SoDienThoai,\r\n        nd.NgayTao,\r\n        nd.TrangThai,\r\n        vt.MaVaiTro,\r\n        vt.TenVaiTro,\r\n        hk.NgaySinh,\r\n        hk.GioiTinh,\r\n        hk.DiemTichLuy\r\n    FROM dbo.NGUOIDUNG nd\r\n    INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\r\n    LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\r\n    WHERE nd.NguoiDungID = @NguoiDungID;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_GetPasswordHash","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_GetPasswordHash\r\n(\r\n    @NguoiDungID INT\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    SELECT NguoiDungID, MatKhau AS MatKhauHash\r\n    FROM dbo.NGUOIDUNG\r\n    WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động'';\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_UpdateProfile","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_UpdateProfile\r\n(\r\n    @NguoiDungID INT,\r\n    @HoTen NVARCHAR(100),\r\n    @SoDienThoai VARCHAR(20) = NULL,\r\n    @NgaySinh DATE = NULL,\r\n    @GioiTinh NVARCHAR(10) = NULL\r\n)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\n    IF @NgaySinh > dbo.fn_HomNay() THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n    BEGIN TRY\r\n        BEGIN TRANSACTION;\r\n\r\n        -- Kiểm tra trùng số điện thoại với tài khoản khác\r\n        IF @SoDienThoai IS NOT NULL AND EXISTS (\r\n            SELECT 1 FROM dbo.NGUOIDUNG\r\n            WHERE SoDienThoai = @SoDienThoai AND NguoiDungID <> @NguoiDungID\r\n        )\r\n        BEGIN\r\n            ;THROW 50015, N''Số điện thoại đã thuộc về một tài khoản khác.'', 1;\r\n        END\r\n\r\n        UPDATE dbo.NGUOIDUNG\r\n        SET HoTen = @HoTen,\r\n            SoDienThoai = @SoDienThoai\r\n        WHERE NguoiDungID = @NguoiDungID;\r\n\r\n        IF EXISTS (SELECT 1 FROM dbo.HOSOKHACHHANG WHERE NguoiDungID = @NguoiDungID)\r\n        BEGIN\r\n            UPDATE dbo.HOSOKHACHHANG\r\n            SET NgaySinh = @NgaySinh,\r\n                GioiTinh = @GioiTinh\r\n            WHERE NguoiDungID = @NguoiDungID;\r\n        END\r\n        ELSE\r\n        BEGIN\r\n            INSERT INTO dbo.HOSOKHACHHANG (NguoiDungID, NgaySinh, GioiTinh, DiemTichLuy)\r\n            VALUES (@NguoiDungID, @NgaySinh, @GioiTinh, 0);\r\n        END\r\n\r\n        COMMIT TRANSACTION;\r\n\r\n        -- Trả về dữ liệu sau cập nhật\r\n        EXEC dbo.sp_User_GetCurrent @NguoiDungID = @NguoiDungID;\r\n\r\n    END TRY\r\n    BEGIN CATCH\r\n        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;\r\n        ;THROW;\r\n    END CATCH\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_XuLyKhieuNai","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_XuLyKhieuNai\r\n(\r\n    @NguoiDungID INT,\r\n    @KhieuNaiID INT,\r\n    @NoiDungXuLy NVARCHAR(MAX),\r\n    @TrangThaiSauXuLy NVARCHAR(50)\r\n)\r\nAS\r\nBEGIN\r\n        SET NOCOUNT ON;\r\nEXEC dbo.sp_Support_Complaint_AddProcessing\r\n        @NguoiDungID = @NguoiDungID,\r\n        @KhieuNaiID = @KhieuNaiID,\r\n        @NoiDungXuLy = @NoiDungXuLy,\r\n        @TrangThaiSauXuLy = @TrangThaiSauXuLy;\r\nEND;\r\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_XuLyThanhToan","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_XuLyThanhToan\n(\n    @NguoiDungID INT,\n    @ThanhToanID INT,\n    @TrangThaiThanhToan NVARCHAR(50),\n    @MaGiaoDichNgoai VARCHAR(100) = NULL,\n    @GhiChu NVARCHAR(255) = NULL\n)\nAS\nBEGIN\n        SET NOCOUNT ON;\nEXEC dbo.sp_Payment_UpdateResult\n        @NguoiDungID = @NguoiDungID,\n        @ThanhToanID = @ThanhToanID,\n        @TrangThaiThanhToan = @TrangThaiThanhToan,\n        @MaGiaoDichNgoai = @MaGiaoDichNgoai,\n        @GhiChu = @GhiChu;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Assignment_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Assignment_Update\n\n    @ActorID INT,\n    @PhanCongID INT, @NguoiDungID INT, @RapID INT, @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL, @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''PHANCONG_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTran BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n        IF @OwnTran = 1 BEGIN TRANSACTION ELSE SAVE TRANSACTION AssignmentUpdate;\n        DECLARE @LockedRows BIGINT;\n        SELECT @LockedRows = COUNT_BIG(*) FROM dbo.PHANCONG_RAP WITH (TABLOCKX, HOLDLOCK);\n        IF NOT EXISTS (SELECT 1 FROM dbo.PHANCONG_RAP WITH (UPDLOCK, HOLDLOCK) WHERE PhanCongID = @PhanCongID)\n            THROW 50212, N''Phân công không tồn tại.'', 1;\n        IF NOT EXISTS (\n            SELECT 1 FROM dbo.NGUOIDUNG nd WITH (HOLDLOCK) INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n            WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro = ''QUAN_LY_RAP''\n        ) THROW 50071, N''Tài khoản được phân công phải có vai trò QUAN_LY_RAP.'', 1;\n        IF @NgayKetThuc IS NOT NULL AND @NgayKetThuc < @NgayBatDau\n            THROW 50213, N''Khoảng thời gian phân công không hợp lệ.'', 1;\n        IF EXISTS (SELECT 1 FROM dbo.PHANCONG_RAP WHERE PhanCongID <> @PhanCongID\n            AND NguoiDungID = @NguoiDungID AND RapID = @RapID AND NgayBatDau = @NgayBatDau\n            AND (NgayKetThuc = @NgayKetThuc OR (NgayKetThuc IS NULL AND @NgayKetThuc IS NULL))\n            AND TrangThai = @TrangThai) THROW 50401, N''Phân công hoàn toàn giống nhau đã tồn tại.'', 1;\n        UPDATE dbo.PHANCONG_RAP\n        SET NguoiDungID = @NguoiDungID, RapID = @RapID, NgayBatDau = @NgayBatDau,\n            NgayKetThuc = @NgayKetThuc, TrangThai = @TrangThai\n        WHERE PhanCongID = @PhanCongID;\n        IF @OwnTran = 1 COMMIT TRANSACTION;\n        SELECT p.PhanCongID, p.NguoiDungID, nd.HoTen AS TenQuanLy, nd.Email, p.RapID, r.TenRap,\n               p.NgayBatDau, p.NgayKetThuc, p.TrangThai\n        FROM dbo.PHANCONG_RAP p INNER JOIN dbo.NGUOIDUNG nd ON nd.NguoiDungID = p.NguoiDungID\n        INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = p.RapID WHERE p.PhanCongID = @PhanCongID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() = -1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE() = 1\n        BEGIN\n            IF @OwnTran = 1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION AssignmentUpdate;\n        END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Cinema_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Cinema_List\n\n    @ActorID INT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT RapID, TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, NgayHoatDong, TrangThai\n    FROM dbo.RAPCHIEUPHIM\n    ORDER BY ThanhPho, TenRap;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- BUG-003: the key-range lock used to be a bare SELECT, which sent an extra\n-- result set to the client ahead of the final image DTO. The backend reads the\n-- first result set, so create returned null and set-cover returned a lock row.\n-- The lock is now taken by assigning to a variable (it still scans, and so\n-- locks, every image row of the cinema); the DTO is the only result set.\n-- Transaction, lock and one-cover-per-cinema logic are otherwise unchanged.\nCREATE   PROCEDURE dbo.usp_Admin_CinemaImage_Create\n\n    @ActorID INT,\n    @RapID INT,\n    @URL NVARCHAR(500),\n    @MoTa NVARCHAR(255) = NULL,\n    @LaAnhDaiDien BIT = 0,\n    @ThuTuHienThi INT = 0,\n    @TrangThai NVARCHAR(50) = N''Hoạt động''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF LEN(LTRIM(RTRIM(ISNULL(@URL, N'''')))) = 0 THROW 50220, N''URL ảnh không được để trống.'', 1;\n    IF @ThuTuHienThi < 0 THROW 50221, N''Thứ tự hiển thị phải lớn hơn hoặc bằng 0.'', 1;\n    DECLARE @OwnTransaction BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n    DECLARE @LockedImageID INT;\n    BEGIN TRY\n        IF @OwnTransaction = 1 BEGIN TRANSACTION; ELSE SAVE TRANSACTION CinemaImageCreate;\n        IF NOT EXISTS (SELECT 1 FROM dbo.RAPCHIEUPHIM WITH (UPDLOCK, HOLDLOCK) WHERE RapID = @RapID)\n            THROW 50200, N''Rạp không tồn tại.'', 1;\n        SELECT @LockedImageID = HinhAnhRapID FROM dbo.HINHANH_RAPCHIEUPHIM WITH (UPDLOCK, HOLDLOCK) WHERE RapID = @RapID;\n        IF @LaAnhDaiDien = 1\n            UPDATE dbo.HINHANH_RAPCHIEUPHIM SET LaAnhDaiDien = 0 WHERE RapID = @RapID AND LaAnhDaiDien = 1;\n        INSERT dbo.HINHANH_RAPCHIEUPHIM (RapID, URL, MoTa, LaAnhDaiDien, ThuTuHienThi, TrangThai)\n        VALUES (@RapID, @URL, @MoTa, @LaAnhDaiDien, @ThuTuHienThi, @TrangThai);\n        DECLARE @HinhAnhRapID INT = SCOPE_IDENTITY();\n        IF @OwnTransaction = 1 COMMIT TRANSACTION;\n        SELECT HinhAnhRapID, RapID, URL, MoTa, LaAnhDaiDien, ThuTuHienThi, TrangThai, NgayTao\n        FROM dbo.HINHANH_RAPCHIEUPHIM WHERE HinhAnhRapID = @HinhAnhRapID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() <> 0\n        BEGIN\n            IF @OwnTransaction = 1 OR XACT_STATE() = -1 ROLLBACK TRANSACTION;\n            ELSE ROLLBACK TRANSACTION CinemaImageCreate;\n        END;\n        THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_CinemaImage_Delete\n\n    @ActorID INT,\n    @RapID INT,\n    @HinhAnhRapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DELETE dbo.HINHANH_RAPCHIEUPHIM WHERE HinhAnhRapID = @HinhAnhRapID AND RapID = @RapID;\n    IF @@ROWCOUNT = 0 THROW 50230, N''Ảnh rạp không tồn tại trong phạm vi rạp.'', 1;\n    SELECT N''Đã xóa ảnh rạp.'' AS [Message];\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_CinemaImage_List\n\n    @ActorID INT,\n    @RapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.RAPCHIEUPHIM WHERE RapID = @RapID)\n        THROW 50200, N''Rạp không tồn tại.'', 1;\n    SELECT HinhAnhRapID, RapID, URL, MoTa, LaAnhDaiDien, ThuTuHienThi, TrangThai, NgayTao\n    FROM dbo.HINHANH_RAPCHIEUPHIM\n    WHERE RapID = @RapID\n    ORDER BY ThuTuHienThi, HinhAnhRapID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_SetCover","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_CinemaImage_SetCover\n\n    @ActorID INT,\n    @RapID INT,\n    @HinhAnhRapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTransaction BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n    DECLARE @LockedImageID INT;\n    BEGIN TRY\n        IF @OwnTransaction = 1 BEGIN TRANSACTION; ELSE SAVE TRANSACTION CinemaImageSetCover;\n        -- Key-range locking serializes cover changes for one cinema.\n        SELECT @LockedImageID = HinhAnhRapID FROM dbo.HINHANH_RAPCHIEUPHIM WITH (UPDLOCK, HOLDLOCK) WHERE RapID = @RapID;\n        IF NOT EXISTS (SELECT 1 FROM dbo.HINHANH_RAPCHIEUPHIM WITH (UPDLOCK, HOLDLOCK) WHERE RapID = @RapID AND HinhAnhRapID = @HinhAnhRapID)\n            THROW 50230, N''Ảnh rạp không tồn tại trong phạm vi rạp.'', 1;\n        IF EXISTS (SELECT 1 FROM dbo.HINHANH_RAPCHIEUPHIM WHERE RapID = @RapID AND HinhAnhRapID = @HinhAnhRapID AND TrangThai <> N''Hoạt động'')\n            THROW 50232, N''Chỉ ảnh đang hoạt động mới có thể là ảnh đại diện.'', 1;\n        UPDATE dbo.HINHANH_RAPCHIEUPHIM SET LaAnhDaiDien = 0 WHERE RapID = @RapID AND LaAnhDaiDien = 1;\n        UPDATE dbo.HINHANH_RAPCHIEUPHIM SET LaAnhDaiDien = 1 WHERE RapID = @RapID AND HinhAnhRapID = @HinhAnhRapID;\n        IF @OwnTransaction = 1 COMMIT TRANSACTION;\n        SELECT HinhAnhRapID, RapID, URL, MoTa, LaAnhDaiDien, ThuTuHienThi, TrangThai, NgayTao\n        FROM dbo.HINHANH_RAPCHIEUPHIM WHERE HinhAnhRapID = @HinhAnhRapID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() <> 0\n        BEGIN\n            IF @OwnTransaction = 1 OR XACT_STATE() = -1 ROLLBACK TRANSACTION;\n            ELSE ROLLBACK TRANSACTION CinemaImageSetCover;\n        END;\n        THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- usp_Admin_CinemaImage_Update (migration 009) ran without a transaction or the\n-- cinema-wide key-range lock that Create/SetCover take. Its row-level UPDATE locks\n-- were acquired in a different order than SetCover''s, so concurrent Update and\n-- SetCover on one cinema could deadlock (one request failed with HTTP 500).\n-- It now takes the same lock first, assigned to a variable so that no extra result\n-- set reaches the client. Validation order, error numbers/messages, the \"disabling\n-- an image clears its cover flag\" rule and the single DTO result set are unchanged.\nCREATE   PROCEDURE dbo.usp_Admin_CinemaImage_Update\n\n    @ActorID INT,\n    @RapID INT,\n    @HinhAnhRapID INT,\n    @URL NVARCHAR(500),\n    @MoTa NVARCHAR(255) = NULL,\n    @ThuTuHienThi INT = 0,\n    @TrangThai NVARCHAR(50) = N''Hoạt động''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF LEN(LTRIM(RTRIM(ISNULL(@URL, N'''')))) = 0 THROW 50220, N''URL ảnh không được để trống.'', 1;\n    IF @ThuTuHienThi < 0 THROW 50221, N''Thứ tự hiển thị phải lớn hơn hoặc bằng 0.'', 1;\n    DECLARE @OwnTransaction BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;\n    DECLARE @LockedImageID INT;\n    BEGIN TRY\n        IF @OwnTransaction = 1 BEGIN TRANSACTION; ELSE SAVE TRANSACTION CinemaImageUpdate;\n        -- Same key-range lock (and order) as Create/SetCover: serialises all image changes of one cinema.\n        SELECT @LockedImageID = HinhAnhRapID FROM dbo.HINHANH_RAPCHIEUPHIM WITH (UPDLOCK, HOLDLOCK) WHERE RapID = @RapID;\n        IF NOT EXISTS (SELECT 1 FROM dbo.HINHANH_RAPCHIEUPHIM WITH (UPDLOCK, HOLDLOCK) WHERE HinhAnhRapID = @HinhAnhRapID AND RapID = @RapID)\n            THROW 50230, N''Ảnh rạp không tồn tại trong phạm vi rạp.'', 1;\n        -- Disabling a cover clears it; no replacement is automatically selected.\n        UPDATE dbo.HINHANH_RAPCHIEUPHIM\n        SET URL = @URL, MoTa = @MoTa, ThuTuHienThi = @ThuTuHienThi, TrangThai = @TrangThai,\n            LaAnhDaiDien = CASE WHEN @TrangThai = N''Hoạt động'' THEN LaAnhDaiDien ELSE 0 END\n        WHERE HinhAnhRapID = @HinhAnhRapID AND RapID = @RapID;\n        IF @OwnTransaction = 1 COMMIT TRANSACTION;\n        SELECT HinhAnhRapID, RapID, URL, MoTa, LaAnhDaiDien, ThuTuHienThi, TrangThai, NgayTao\n        FROM dbo.HINHANH_RAPCHIEUPHIM WHERE HinhAnhRapID = @HinhAnhRapID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() <> 0\n        BEGIN\n            IF @OwnTransaction = 1 OR XACT_STATE() = -1 ROLLBACK TRANSACTION;\n            ELSE ROLLBACK TRANSACTION CinemaImageUpdate;\n        END;\n        THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Movie_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Movie_List\n\n    @ActorID INT,\n    @TrangThai NVARCHAR(50) = NULL, @TheLoaiID INT = NULL, @SearchTerm NVARCHAR(100) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT DISTINCT p.PhimID, p.TenPhim, p.ThoiLuong, p.NgayKhoiChieu, p.NgayKetThuc, p.NgonNgu,\n           p.PhuDe, p.DoTuoi, p.DaoDien, p.MoTa, p.PosterURL, p.TrailerURL, p.TrangThai,\n           STUFF((SELECT '','' + CAST(pt.TheLoaiID AS VARCHAR(12)) FROM dbo.PHIM_THELOAI pt\n                  WHERE pt.PhimID = p.PhimID ORDER BY pt.TheLoaiID FOR XML PATH(''''), TYPE).value(''.'', ''NVARCHAR(MAX)''), 1, 1, '''') AS TheLoaiIdList,\n           (SELECT pd.DienVienID AS actorId, pd.VaiDien AS [role] FROM dbo.PHIM_DIENVIEN pd\n            WHERE pd.PhimID = p.PhimID ORDER BY pd.DienVienID FOR JSON PATH) AS DanhSachDienVienJson\n    FROM dbo.PHIM p\n    LEFT JOIN dbo.PHIM_THELOAI ptFilter ON ptFilter.PhimID = p.PhimID\n    WHERE (@TrangThai IS NULL OR p.TrangThai = @TrangThai)\n      AND (@TheLoaiID IS NULL OR ptFilter.TheLoaiID = @TheLoaiID)\n      AND (@SearchTerm IS NULL OR p.TenPhim LIKE ''%'' + @SearchTerm + ''%'' OR p.DaoDien LIKE ''%'' + @SearchTerm + ''%'')\n    ORDER BY p.NgayKhoiChieu DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Pricing_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Pricing_Create\n\n    @ActorID INT,\n    @RapID INT, @LoaiGhe NVARCHAR(50), @LoaiNgay NVARCHAR(50), @DinhDang NVARCHAR(50),\n    @PhuThu DECIMAL(18,2), @NgayBatDau DATE, @NgayKetThuc DATE = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.RAPCHIEUPHIM WHERE RapID = @RapID)\n        THROW 50208, N''Rạp không tồn tại.'', 1;\n    IF @PhuThu < 0 OR (@NgayKetThuc IS NOT NULL AND @NgayKetThuc < @NgayBatDau)\n        THROW 50209, N''Khoảng ngày hoặc phụ thu không hợp lệ.'', 1;\n    INSERT dbo.BANGGIA (RapID, LoaiGhe, LoaiNgay, DinhDang, PhuThu, NgayBatDau, NgayKetThuc, TrangThai)\n    VALUES (@RapID, @LoaiGhe, @LoaiNgay, @DinhDang, @PhuThu, @NgayBatDau, @NgayKetThuc, N''Áp dụng'');\n    SELECT GiaID, RapID, LoaiGhe, LoaiNgay, DinhDang, PhuThu, NgayBatDau, NgayKetThuc, TrangThai\n    FROM dbo.BANGGIA WHERE GiaID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Pricing_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Pricing_List\n    @ActorID INT,\n    @RapID INT = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT bg.GiaID, bg.RapID, r.TenRap, bg.LoaiGhe, bg.LoaiNgay, bg.DinhDang,\n           bg.PhuThu, bg.NgayBatDau, bg.NgayKetThuc, bg.TrangThai\n    FROM dbo.BANGGIA bg INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = bg.RapID\n    WHERE @RapID IS NULL OR bg.RapID = @RapID\n    ORDER BY r.TenRap, bg.NgayBatDau DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Pricing_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Pricing_Update\n    @ActorID INT,\n    @GiaID INT, @PhuThu DECIMAL(18,2), @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.BANGGIA WHERE GiaID = @GiaID)\n        THROW 50210, N''Bảng giá không tồn tại.'', 1;\n    IF @PhuThu < 0 THROW 50209, N''Phụ thu không hợp lệ.'', 1;\n    UPDATE dbo.BANGGIA SET PhuThu = @PhuThu, TrangThai = @TrangThai WHERE GiaID = @GiaID;\n    SELECT GiaID, RapID, LoaiGhe, LoaiNgay, DinhDang, PhuThu, NgayBatDau, NgayKetThuc, TrangThai\n    FROM dbo.BANGGIA WHERE GiaID = @GiaID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Product_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Product_List\n\n    @ActorID INT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT SanPhamID, TenSanPham, LoaiSanPham, Gia, MoTa, HinhAnh, TrangThai\n    FROM dbo.SANPHAM\n    ORDER BY TenSanPham;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_RolePermission_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_RolePermission_List\n    @ActorID INT,\n    @VaiTroID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.VAITRO WHERE VaiTroID = @VaiTroID)\n        THROW 50214, N''Vai trò không tồn tại.'', 1;\n    SELECT vq.VaiTroID, q.QuyenID, q.MaQuyen, q.TenQuyen\n    FROM dbo.VAITRO_QUYEN vq INNER JOIN dbo.QUYEN q ON q.QuyenID = vq.QuyenID\n    WHERE vq.VaiTroID = @VaiTroID ORDER BY q.MaQuyen;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_Create\n\n    @ActorID INT,\n    @RapID INT, @TenPhong NVARCHAR(100), @LoaiPhong NVARCHAR(50) = N''2D''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.RAPCHIEUPHIM WHERE RapID = @RapID)\n        THROW 50200, N''Rạp không tồn tại.'', 1;\n    IF EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE RapID = @RapID AND TenPhong = @TenPhong)\n        THROW 50201, N''Tên phòng đã tồn tại trong rạp.'', 1;\n    INSERT dbo.PHONGCHIEU (RapID, TenPhong, LoaiPhong, TrangThai)\n    VALUES (@RapID, @TenPhong, @LoaiPhong, N''Hoạt động'');\n    SELECT PhongID, RapID, TenPhong, LoaiPhong, TrangThai FROM dbo.PHONGCHIEU WHERE PhongID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_Delete\n    @ActorID INT,\n    @PhongID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WITH (UPDLOCK, HOLDLOCK) WHERE PhongID = @PhongID)\n            THROW 50202, N''Phòng không tồn tại.'', 1;\n        IF EXISTS (SELECT 1 FROM dbo.SUATCHIEU WHERE PhongID = @PhongID)\n            THROW 50203, N''Phòng đã có lịch sử suất chiếu; hãy đổi trạng thái thay vì xóa.'', 1;\n        DELETE dbo.GHE WHERE PhongID = @PhongID;\n        DELETE dbo.PHONGCHIEU WHERE PhongID = @PhongID;\n        COMMIT TRANSACTION;\n        SELECT N''Đã xóa phòng.'' AS [Message];\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_List\n\n    @ActorID INT,\n    @RapID INT = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT pc.PhongID, pc.RapID, r.TenRap, pc.TenPhong, pc.LoaiPhong, pc.TrangThai,\n           (SELECT COUNT(*) FROM dbo.GHE g WHERE g.PhongID = pc.PhongID) AS TongSoGhe\n    FROM dbo.PHONGCHIEU pc\n    INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = pc.RapID\n    WHERE @RapID IS NULL OR pc.RapID = @RapID\n    ORDER BY r.TenRap, pc.TenPhong;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_Update\n\n    @ActorID INT,\n    @PhongID INT, @TenPhong NVARCHAR(100), @LoaiPhong NVARCHAR(50), @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @RapID INT = (SELECT RapID FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID);\n    IF @RapID IS NULL THROW 50202, N''Phòng không tồn tại.'', 1;\n    IF EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE RapID = @RapID AND TenPhong = @TenPhong AND PhongID <> @PhongID)\n        THROW 50201, N''Tên phòng đã tồn tại trong rạp.'', 1;\n    UPDATE dbo.PHONGCHIEU SET TenPhong = @TenPhong, LoaiPhong = @LoaiPhong, TrangThai = @TrangThai WHERE PhongID = @PhongID;\n    SELECT PhongID, RapID, TenPhong, LoaiPhong, TrangThai FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_Create\n\n    @ActorID INT,\n    @PhongID INT, @HangGhe VARCHAR(10), @SoGhe INT, @LoaiGhe NVARCHAR(50) = N''Thường''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID)\n        THROW 50204, N''Phòng không tồn tại.'', 1;\n    IF EXISTS (SELECT 1 FROM dbo.GHE WHERE PhongID = @PhongID AND HangGhe = @HangGhe AND SoGhe = @SoGhe)\n        THROW 50205, N''Vị trí ghế đã tồn tại trong phòng.'', 1;\n    INSERT dbo.GHE (PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai)\n    VALUES (@PhongID, @HangGhe, @SoGhe, @LoaiGhe, N''Hoạt động'');\n    SELECT GheID, PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai FROM dbo.GHE WHERE GheID = SCOPE_IDENTITY();\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_Delete\n    @ActorID INT,\n    @GheID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (SELECT 1 FROM dbo.GHE WITH (UPDLOCK, HOLDLOCK) WHERE GheID = @GheID)\n            THROW 50206, N''Ghế không tồn tại.'', 1;\n        IF EXISTS (SELECT 1 FROM dbo.CHITIETVE WHERE GheID = @GheID)\n            THROW 50207, N''Ghế có lịch sử vé; hãy vô hiệu hóa thay vì xóa.'', 1;\n        DELETE dbo.GHE WHERE GheID = @GheID;\n        COMMIT TRANSACTION;\n        SELECT N''Đã xóa ghế.'' AS [Message];\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_List\n\n    @ActorID INT,\n    @PhongID INT = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT g.GheID, g.PhongID, pc.RapID, r.TenRap, g.HangGhe, g.SoGhe,\n           g.HangGhe + CAST(g.SoGhe AS VARCHAR(10)) AS TenGhe, g.LoaiGhe, g.TrangThai\n    FROM dbo.GHE g\n    INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID = g.PhongID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = pc.RapID\n    WHERE @PhongID IS NULL OR g.PhongID = @PhongID\n    ORDER BY r.TenRap, pc.TenPhong, g.HangGhe, g.SoGhe;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_Update\n\n    @ActorID INT,\n    @GheID INT, @LoaiGhe NVARCHAR(50), @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTran BIT=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n        IF @OwnTran=1 BEGIN TRANSACTION ELSE SAVE TRANSACTION AdminSeatUpdate;\n        IF NOT EXISTS (SELECT 1 FROM dbo.GHE WITH (UPDLOCK,HOLDLOCK) WHERE GheID=@GheID) THROW 50206, N''Ghế không tồn tại.'', 1;\n        IF dbo.fn_GheCoVeHieuLucSuatTuongLai(@GheID)=1 THROW 50207, N''Ghế có vé hiệu lực ở suất chiếu tương lai.'', 1;\n        UPDATE dbo.GHE SET LoaiGhe=@LoaiGhe, TrangThai=@TrangThai WHERE GheID=@GheID;\n        IF @OwnTran=1 COMMIT TRANSACTION;\n        SELECT GheID,PhongID,HangGhe,SoGhe,LoaiGhe,TrangThai FROM dbo.GHE WHERE GheID=@GheID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE()=-1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE()=1 BEGIN IF @OwnTran=1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION AdminSeatUpdate; END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_Cancel","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Showtime_Cancel\n    @ActorID INT,\n    @SuatChieuID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    EXEC dbo.sp_Showtime_CancelCascade @SuatChieuID = @SuatChieuID, @NguoiDungID = @ActorID, @LyDo = NULL;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/008_admin_global_portal.sql:266 (dbo.usp_Admin_Showtime_Create)\nCREATE   PROCEDURE dbo.usp_Admin_Showtime_Create\n\n    @ActorID INT,\n    @PhimID INT, @PhongID INT, @ThoiGianBatDau DATETIME2, @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50) = N''2D'', @GiaVeCoBan DECIMAL(18,2)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @NewSuatChieuID INT;\n    IF @ThoiGianKetThuc <= @ThoiGianBatDau THROW 50211, N''Thời gian suất chiếu không hợp lệ.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.PHONGCHIEU WHERE PhongID = @PhongID)\n        THROW 50056, N''Phòng chiếu không tồn tại.'', 1;\n    EXEC dbo.sp_Showtime_ValidateTimes @PhimID=@PhimID,@ThoiGianBatDau=@ThoiGianBatDau,@ThoiGianKetThuc=@ThoiGianKetThuc;\n        INSERT dbo.SUATCHIEU (PhimID, PhongID, ThoiGianBatDau, ThoiGianKetThuc, DinhDang, GiaVeCoBan, TrangThai)\n    VALUES (@PhimID, @PhongID, @ThoiGianBatDau, @ThoiGianKetThuc, @DinhDang, @GiaVeCoBan, N''Mở bán'');\n    SET @NewSuatChieuID = SCOPE_IDENTITY();\n    EXEC dbo.sp_Showtime_GetDetail @SuatChieuID = @NewSuatChieuID;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Showtime_List\n\n    @ActorID INT,\n    @RapID INT = NULL, @TuNgay DATE = NULL, @DenNgay DATE = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT sc.SuatChieuID, sc.PhimID, p.TenPhim, sc.PhongID, pc.TenPhong, pc.RapID, r.TenRap,\n           sc.ThoiGianBatDau, sc.ThoiGianKetThuc, sc.DinhDang, sc.GiaVeCoBan, sc.TrangThai\n    FROM dbo.SUATCHIEU sc\n    INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID = sc.PhongID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = pc.RapID\n    INNER JOIN dbo.PHIM p ON p.PhimID = sc.PhimID\n    WHERE (@RapID IS NULL OR pc.RapID = @RapID)\n      AND (@TuNgay IS NULL OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) >= @TuNgay)\n      AND (@DenNgay IS NULL OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) <= @DenNgay)\n    ORDER BY sc.ThoiGianBatDau DESC;\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:178 (dbo.usp_Admin_Showtime_Update)\nCREATE   PROCEDURE dbo.usp_Admin_Showtime_Update\n\n    @ActorID INT,\n    @SuatChieuID INT, @PhimID INT, @ThoiGianBatDau DATETIME2, @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50), @GiaVeCoBan DECIMAL(18,2), @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG WHERE NguoiDungID = @ActorID AND TrangThai = N''Hoạt động'')\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (SELECT 1 FROM dbo.NGUOIDUNG nd INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n                   WHERE nd.NguoiDungID = @ActorID AND vt.MaVaiTro IN (''ADMIN''))\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @OwnTran BIT=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;\n    BEGIN TRY\n        IF @OwnTran=1 BEGIN TRANSACTION ELSE SAVE TRANSACTION AdminShowtimeUpdate;\n        DECLARE @OldPhim INT, @OldStart DATETIME2, @OldEnd DATETIME2, @OldFormat NVARCHAR(50), @Now DATETIME2 = dbo.fn_BayGio();\n        SELECT @OldPhim=PhimID, @OldStart=ThoiGianBatDau, @OldEnd=ThoiGianKetThuc, @OldFormat=DinhDang\n        FROM dbo.SUATCHIEU WITH (UPDLOCK, HOLDLOCK) WHERE SuatChieuID=@SuatChieuID;\n        IF @OldPhim IS NULL THROW 50058, N''Suất chiếu không tồn tại.'', 1;\n        IF @TrangThai=N''Đã hủy'' THROW 50123, N''Dùng route hủy suất chiếu riêng.'', 1;\n        IF EXISTS (SELECT 1 FROM dbo.DONDATVE d WHERE d.SuatChieuID=@SuatChieuID AND\n                   (d.TrangThai=N''Đã thanh toán'' OR (d.TrangThai=N''Chờ thanh toán'' AND d.HanGiuCho>@Now)))\n           AND (@PhimID<>@OldPhim OR @ThoiGianBatDau<>@OldStart OR @ThoiGianKetThuc<>@OldEnd OR @DinhDang<>@OldFormat)\n            THROW 50120, N''Suất chiếu đã có đơn; không thể đổi phim, giờ, phòng hoặc định dạng.'', 1;\n        IF @ThoiGianKetThuc<=@ThoiGianBatDau THROW 50211, N''Thời gian suất chiếu không hợp lệ.'', 1;\n        EXEC dbo.sp_Showtime_ValidateTimes @PhimID=@PhimID,@ThoiGianBatDau=@ThoiGianBatDau,@ThoiGianKetThuc=@ThoiGianKetThuc;\n        UPDATE dbo.SUATCHIEU SET PhimID=@PhimID, ThoiGianBatDau=@ThoiGianBatDau, ThoiGianKetThuc=@ThoiGianKetThuc,\n            DinhDang=@DinhDang, GiaVeCoBan=@GiaVeCoBan, TrangThai=@TrangThai WHERE SuatChieuID=@SuatChieuID;\n        IF @OwnTran=1 COMMIT TRANSACTION;\n        EXEC dbo.sp_Showtime_GetDetail @SuatChieuID=@SuatChieuID;\n    END TRY\n    BEGIN CATCH\n        IF XACT_STATE()=-1 ROLLBACK TRANSACTION;\n        ELSE IF XACT_STATE()=1 BEGIN IF @OwnTran=1 ROLLBACK TRANSACTION ELSE ROLLBACK TRANSACTION AdminShowtimeUpdate; END\n        ;THROW;\n    END CATCH\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"PK_BANGGIA","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_BOITHUONG_HUYSUAT","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_CHITIETDOAN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_CHITIETVE","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_DANHGIAPHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_DIENVIEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_DONDATVE","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_GHE","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_HINHANH_RAPCHIEUPHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_HOSOKHACHHANG","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_KHIEUNAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_KHUYENMAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_NGUOIDUNG","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHANCONG_RAP","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHIM_DIENVIEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHIM_THELOAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHONGCHIEU","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_QUYEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_RAPCHIEUPHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_SANPHAM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_SUATCHIEU","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_THANHTOAN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_THELOAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_VAITRO","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_VAITRO_QUYEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_XULY_KHIEUNAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"TRG_BangGia_KiemTraChongLan","type":"TR","type_desc":"SQL_TRIGGER","definition":"-- ---------------------------------------------------------------------------------------------\r\n-- (1) Overlapping pricing rules.\r\n-- \"Overlap\" = same RapID, same (LoaiGhe, LoaiNgay, DinhDang) values (N''Tất cả'' counts as a value of its own),\r\n-- both TrangThai = N''Áp dụng'', and validity ranges that intersect (NgayKetThuc NULL = open ended; the end day is\r\n-- inclusive, as in fn_TinhGiaVe). A N''Tất cả'' rule and a specific rule that differ in a column are two different\r\n-- conditions and may coexist: they are deliberate layers (e.g. VIP +15,000 together with weekend +10,000).\r\n--\r\n-- A trigger is used (like TRG_SuatChieu_KiemTraTrungLich) so that every write path is covered: the admin and\r\n-- manager procedures and direct DML. The trigger takes an UPDLOCK/HOLDLOCK on the cinema row first (assigned to a\r\n-- variable, no result set, rows locked in RapID order), so two concurrent writers for one cinema are queued and\r\n-- the second one sees the first one''s committed row (the database runs READ_COMMITTED_SNAPSHOT, so its read does\r\n-- not block on the other transaction''s uncommitted row: no lock cycle). Existing overlapping rows are never\r\n-- modified; only rows being inserted/updated to \"Áp dụng\" are checked.\r\n-- ---------------------------------------------------------------------------------------------\r\nCREATE   TRIGGER dbo.TRG_BangGia_KiemTraChongLan\r\nON dbo.BANGGIA\r\nAFTER INSERT, UPDATE\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    IF NOT EXISTS (SELECT 1 FROM inserted WHERE TrangThai = N''Áp dụng'') RETURN;\r\n\r\n    DECLARE @KhoaRap INT;\r\n    SELECT @KhoaRap = r.RapID\r\n    FROM dbo.RAPCHIEUPHIM r WITH (UPDLOCK, HOLDLOCK)\r\n    WHERE r.RapID IN (SELECT RapID FROM inserted WHERE TrangThai = N''Áp dụng'');\r\n\r\n    -- against the rows already in the table\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM inserted i\r\n        INNER JOIN dbo.BANGGIA b\r\n            ON b.RapID = i.RapID AND b.GiaID <> i.GiaID\r\n           AND b.LoaiGhe = i.LoaiGhe AND b.LoaiNgay = i.LoaiNgay AND b.DinhDang = i.DinhDang\r\n        WHERE i.TrangThai = N''Áp dụng'' AND b.TrangThai = N''Áp dụng''\r\n          AND i.NgayBatDau <= ISNULL(b.NgayKetThuc, ''9999-12-31'')\r\n          AND b.NgayBatDau <= ISNULL(i.NgayKetThuc, ''9999-12-31'')\r\n    )\r\n    BEGIN\r\n        ;THROW 50215, N''Lỗi ràng buộc: Bảng giá đang áp dụng đã có cùng điều kiện trong khoảng thời gian này.'', 1;\r\n    END\r\n\r\n    -- within the statement itself (multi-row insert/update)\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM inserted i1\r\n        INNER JOIN inserted i2\r\n            ON i1.GiaID < i2.GiaID AND i1.RapID = i2.RapID\r\n           AND i1.LoaiGhe = i2.LoaiGhe AND i1.LoaiNgay = i2.LoaiNgay AND i1.DinhDang = i2.DinhDang\r\n        WHERE i1.TrangThai = N''Áp dụng'' AND i2.TrangThai = N''Áp dụng''\r\n          AND i1.NgayBatDau <= ISNULL(i2.NgayKetThuc, ''9999-12-31'')\r\n          AND i2.NgayBatDau <= ISNULL(i1.NgayKetThuc, ''9999-12-31'')\r\n    )\r\n    BEGIN\r\n        ;THROW 50215, N''Lỗi ràng buộc: Bảng giá đang áp dụng đã có cùng điều kiện trong khoảng thời gian này.'', 1;\r\n    END\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_ChiTietVe_KiemTraGheDungPhong","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE   TRIGGER dbo.TRG_ChiTietVe_KiemTraGheDungPhong\r\nON dbo.CHITIETVE\r\nAFTER INSERT, UPDATE\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM INSERTED i\r\n        INNER JOIN dbo.DONDATVE ddv ON i.DonDatVeID = ddv.DonDatVeID\r\n        INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\r\n        INNER JOIN dbo.GHE g ON i.GheID = g.GheID\r\n        WHERE g.PhongID <> sc.PhongID\r\n    )\r\n    BEGIN\r\n        ;THROW 50002, N''Lỗi ràng buộc [BR03]: Ghế được chọn không thuộc phòng chiếu của suất chiếu này.'', 1;\r\n    END\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_ChiTietVe_KiemTraTrungGhe","type":"TR","type_desc":"SQL_TRIGGER","definition":"-- Baseline: triggers/04_triggers.sql:87 (dbo.TRG_ChiTietVe_KiemTraTrungGhe)\r\nCREATE   TRIGGER dbo.TRG_ChiTietVe_KiemTraTrungGhe\r\nON dbo.CHITIETVE\r\nAFTER INSERT, UPDATE\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    -- Kiểm tra giữa dòng mới với vé hiện có trong cơ sở dữ liệu\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM INSERTED i\r\n        INNER JOIN dbo.DONDATVE ddv_new ON i.DonDatVeID = ddv_new.DonDatVeID\r\n        INNER JOIN dbo.CHITIETVE cv_exist ON i.GheID = cv_exist.GheID AND i.VeID <> cv_exist.VeID\r\n        INNER JOIN dbo.DONDATVE ddv_exist ON cv_exist.DonDatVeID = ddv_exist.DonDatVeID\r\n        WHERE ddv_new.SuatChieuID = ddv_exist.SuatChieuID\r\n          AND i.TrangThai <> N''Đã hủy''\r\n          AND cv_exist.TrangThai <> N''Đã hủy''\r\n          AND ddv_new.TrangThai NOT IN (N''Đã hủy'', N''Hết hạn'')\r\n          AND dbo.fn_DonDangGiuGhe(ddv_exist.TrangThai, ddv_exist.HanGiuCho, dbo.fn_BayGio()) = 1\r\n    )\r\n    BEGIN\r\n        ;THROW 50003, N''Lỗi xung đột [BR02]: Ghế này đã được đặt hoặc đang được giữ bởi một đơn khác cho cùng suất chiếu.'', 1;\r\n    END\r\n\r\n    -- Kiểm tra trùng lặp trong chính tập INSERTED\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM INSERTED i1\r\n        INNER JOIN dbo.DONDATVE ddv1 ON i1.DonDatVeID = ddv1.DonDatVeID\r\n        INNER JOIN INSERTED i2 ON i1.GheID = i2.GheID AND i1.VeID <> i2.VeID\r\n        INNER JOIN dbo.DONDATVE ddv2 ON i2.DonDatVeID = ddv2.DonDatVeID\r\n        WHERE ddv1.SuatChieuID = ddv2.SuatChieuID\r\n          AND i1.TrangThai <> N''Đã hủy''\r\n          AND i2.TrangThai <> N''Đã hủy''\r\n    )\r\n    BEGIN\r\n        ;THROW 50003, N''Lỗi xung đột [BR02]: Phát hiện chọn trùng cùng một ghế nhiều lần trong cùng một đơn.'', 1;\r\n    END\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_DanhGia_KiemTraDaXemPhim","type":"TR","type_desc":"SQL_TRIGGER","definition":"-- Baseline: triggers/04_triggers.sql:133 (dbo.TRG_DanhGia_KiemTraDaXemPhim)\r\nCREATE   TRIGGER dbo.TRG_DanhGia_KiemTraDaXemPhim\r\nON dbo.DANHGIAPHIM\r\nAFTER INSERT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM INSERTED i\r\n        WHERE NOT EXISTS (\r\n            SELECT 1\r\n            FROM dbo.DONDATVE ddv\r\n            INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\r\n            WHERE ddv.NguoiDungID = i.NguoiDungID\r\n              AND sc.PhimID = i.PhimID\r\n              AND ddv.TrangThai IN (N''Đã thanh toán'', N''Hoàn thành'')\r\n              AND sc.ThoiGianBatDau <= dbo.fn_BayGio()\r\n        )\r\n    )\r\n    BEGIN\r\n        ;THROW 50004, N''Lỗi nghiệp vụ [BR05]: Khách hàng chỉ có thể đánh giá sau khi đã mua vé xem phim và suất chiếu đã diễn ra.'', 1;\r\n    END\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_SuatChieu_KiemTraTrungLich","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE   TRIGGER dbo.TRG_SuatChieu_KiemTraTrungLich\r\nON dbo.SUATCHIEU\r\nAFTER INSERT, UPDATE\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    -- Kiểm tra giao nhau giữa bản ghi mới/sửa với các suất chiếu đã có trong bảng\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM INSERTED i\r\n        INNER JOIN dbo.SUATCHIEU sc ON i.PhongID = sc.PhongID AND i.SuatChieuID <> sc.SuatChieuID\r\n        WHERE i.TrangThai <> N''Đã hủy''\r\n          AND sc.TrangThai <> N''Đã hủy''\r\n          AND i.ThoiGianBatDau < sc.ThoiGianKetThuc\r\n          AND i.ThoiGianKetThuc > sc.ThoiGianBatDau\r\n    )\r\n    BEGIN\r\n        ;THROW 50001, N''Lỗi ràng buộc [BR01]: Phòng chiếu đã có suất chiếu khác trong khoảng thời gian này.'', 1;\r\n    END\r\n\r\n    -- Kiểm tra giao nhau giữa các dòng trong chính tập INSERTED (phòng trường hợp insert/update theo lô)\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM INSERTED i1\r\n        INNER JOIN INSERTED i2 ON i1.PhongID = i2.PhongID AND i1.SuatChieuID <> i2.SuatChieuID\r\n        WHERE i1.TrangThai <> N''Đã hủy''\r\n          AND i2.TrangThai <> N''Đã hủy''\r\n          AND i1.ThoiGianBatDau < i2.ThoiGianKetThuc\r\n          AND i1.ThoiGianKetThuc > i2.ThoiGianBatDau\r\n    )\r\n    BEGIN\r\n        ;THROW 50001, N''Lỗi ràng buộc [BR01]: Tập suất chiếu mới có khoảng thời gian trùng nhau trong cùng phòng.'', 1;\r\n    END\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_XuLyKhieuNai_CapNhatTrangThaiKhieuNai","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE   TRIGGER dbo.TRG_XuLyKhieuNai_CapNhatTrangThaiKhieuNai\r\nON dbo.XULY_KHIEUNAI\r\nAFTER INSERT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    UPDATE kn\r\n    SET kn.TrangThai = i.TrangThaiSauXuLy\r\n    FROM dbo.KHIEUNAI kn\r\n    INNER JOIN INSERTED i ON kn.KhieuNaiID = i.KhieuNaiID;\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_XuLyKhieuNai_KiemTraVaiTro","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE   TRIGGER dbo.TRG_XuLyKhieuNai_KiemTraVaiTro\r\nON dbo.XULY_KHIEUNAI\r\nAFTER INSERT, UPDATE\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    IF EXISTS (\r\n        SELECT 1\r\n        FROM INSERTED i\r\n        INNER JOIN dbo.NGUOIDUNG nd ON i.NguoiXuLyID = nd.NguoiDungID\r\n        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\r\n        WHERE vt.MaVaiTro NOT IN (''CSKH'', ''ADMIN'')\r\n           OR nd.TrangThai <> N''Hoạt động''\r\n    )\r\n    BEGIN\r\n        ;THROW 50005, N''Lỗi bảo mật [BR07]: Chỉ nhân viên Chăm sóc khách hàng hoặc Quản trị viên mới được ghi nhận lịch sử xử lý khiếu nại.'', 1;\r\n    END\r\nEND;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"BANGGIA","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"BOITHUONG_HUYSUAT","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"CHITIETDOAN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"CHITIETVE","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"DANHGIAPHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"DIENVIEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"DONDATVE","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"GHE","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"HINHANH_RAPCHIEUPHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"HOSOKHACHHANG","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"KHIEUNAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"KHUYENMAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"NGUOIDUNG","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHANCONG_RAP","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHIM_DIENVIEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHIM_THELOAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHONGCHIEU","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"QUYEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"RAPCHIEUPHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"SANPHAM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"SUATCHIEU","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"THANHTOAN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"THELOAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"VAITRO","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"VAITRO_QUYEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"XULY_KHIEUNAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_BOITHUONG_HUYSUAT_Don","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_CHITIETDOAN_Don_SanPham","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_CHITIETVE_MaVe","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_DANHGIAPHIM_Phim_User","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_GHE_ViTri","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_KHUYENMAI_MaCode","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_NGUOIDUNG_Email","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_PHONGCHIEU_TenPhong","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_QUYEN_MaQuyen","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_THELOAI_TenTheLoai","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_VAITRO_MaVaiTro","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"vw_ChiTietDonDatVe","type":"V ","type_desc":"VIEW","definition":"-- Baseline: views/03_views.sql:106 (dbo.vw_ChiTietDonDatVe)\r\nCREATE   VIEW dbo.vw_ChiTietDonDatVe\r\nAS\r\nSELECT\r\n    ddv.DonDatVeID,\r\n    ddv.NguoiDungID,\r\n    nd.HoTen AS HoTenKhachHang,\r\n    nd.Email,\r\n    nd.SoDienThoai,\r\n    sc.SuatChieuID,\r\n    p.PhimID,\r\n    p.TenPhim,\r\n    p.PosterURL,\r\n    p.DoTuoi,\r\n    p.ThoiLuong,\r\n    r.RapID,\r\n    r.TenRap,\r\n    r.DiaChi AS DiaChiRap,\r\n    pc.PhongID,\r\n    pc.TenPhong,\r\n    pc.LoaiPhong,\r\n    sc.ThoiGianBatDau,\r\n    sc.ThoiGianKetThuc,\r\n    sc.DinhDang,\r\n    ddv.NgayDat,\r\n    ddv.TongTienVe,\r\n    ddv.TongTienDoAn,\r\n    ddv.TienGiamGia,\r\n    (ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia) AS TongTienThanhToan,\r\n    CASE WHEN ddv.TrangThai = N''Chờ thanh toán'' AND ddv.HanGiuCho <= dbo.fn_BayGio() THEN N''Hết hạn'' ELSE ddv.TrangThai END AS TrangThaiDon,\r\n    ddv.HanGiuCho,\r\n    km.MaCode AS MaKhuyenMai,\r\n    km.MoTa AS MoTaKhuyenMai,\r\n    -- Danh sách ghế dạng chuỗi (A1, A2...)\r\n    STUFF((\r\n        SELECT '', '' + (g.HangGhe + CAST(g.SoGhe AS VARCHAR(10)))\r\n        FROM dbo.CHITIETVE cv2\r\n        INNER JOIN dbo.GHE g ON cv2.GheID = g.GheID\r\n        WHERE cv2.DonDatVeID = ddv.DonDatVeID AND cv2.TrangThai <> N''Đã hủy''\r\n        FOR XML PATH(''''), TYPE\r\n    ).value(''.'', ''NVARCHAR(MAX)''), 1, 2, '''') AS DanhSachGhe,\r\n    -- Danh sách mã vé dạng chuỗi\r\n    STUFF((\r\n        SELECT '', '' + cv3.MaVe\r\n        FROM dbo.CHITIETVE cv3\r\n        WHERE cv3.DonDatVeID = ddv.DonDatVeID AND cv3.TrangThai <> N''Đã hủy''\r\n        FOR XML PATH(''''), TYPE\r\n    ).value(''.'', ''NVARCHAR(MAX)''), 1, 2, '''') AS DanhSachMaVe\r\nFROM dbo.DONDATVE ddv\r\nINNER JOIN dbo.NGUOIDUNG nd ON ddv.NguoiDungID = nd.NguoiDungID\r\nINNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\r\nINNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\r\nINNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\r\nINNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\r\nLEFT JOIN dbo.KHUYENMAI km ON ddv.KhuyenMaiID = km.KhuyenMaiID;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_DanhSachKhieuNai","type":"V ","type_desc":"VIEW","definition":"CREATE   VIEW dbo.vw_DanhSachKhieuNai\r\nAS\r\nSELECT\r\n    kn.KhieuNaiID,\r\n    kn.NguoiDungID AS NguoiGuiID,\r\n    nd.HoTen AS HoTenNguoiGui,\r\n    nd.Email AS EmailNguoiGui,\r\n    nd.SoDienThoai AS SoDienThoaiNguoiGui,\r\n    kn.DonDatVeID,\r\n    kn.LoaiKhieuNai,\r\n    kn.TieuDe,\r\n    kn.NoiDung,\r\n    kn.MucDoUuTien,\r\n    kn.NgayTao,\r\n    kn.TrangThai AS TrangThaiKhieuNai,\r\n    (SELECT COUNT(*) FROM dbo.XULY_KHIEUNAI xl WHERE xl.KhieuNaiID = kn.KhieuNaiID) AS SoLanXuLy,\r\n    (SELECT TOP 1 xl.NgayXuLy\r\n     FROM dbo.XULY_KHIEUNAI xl\r\n     WHERE xl.KhieuNaiID = kn.KhieuNaiID\r\n     ORDER BY xl.XuLyID DESC) AS NgayXuLyCuoi,\r\n    (SELECT TOP 1 nd_xl.HoTen\r\n     FROM dbo.XULY_KHIEUNAI xl\r\n     INNER JOIN dbo.NGUOIDUNG nd_xl ON xl.NguoiXuLyID = nd_xl.NguoiDungID\r\n     WHERE xl.KhieuNaiID = kn.KhieuNaiID\r\n     ORDER BY xl.XuLyID DESC) AS NguoiXuLyCuoi,\r\n    (SELECT TOP 1 xl.NoiDungXuLy\r\n     FROM dbo.XULY_KHIEUNAI xl\r\n     WHERE xl.KhieuNaiID = kn.KhieuNaiID\r\n     ORDER BY xl.XuLyID DESC) AS NoiDungXuLyCuoi\r\nFROM dbo.KHIEUNAI kn\r\nINNER JOIN dbo.NGUOIDUNG nd ON kn.NguoiDungID = nd.NguoiDungID;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_DoanhThuTheoRap","type":"V ","type_desc":"VIEW","definition":"CREATE   VIEW dbo.vw_DoanhThuTheoRap\r\nAS\r\n-- Doanh thu tính từ THANHTOAN có TrangThai = ''Thành công'' (không dựa vào trạng thái đơn).\r\n-- Giao dịch ''Thất bại'' / ''Đang xử lý'' / ''Đã hoàn tiền'' không được tính.\r\nWITH DonDaThu AS (\r\n    SELECT\r\n        ddv.DonDatVeID,\r\n        pc.RapID,\r\n        ddv.TongTienVe,\r\n        ddv.TongTienDoAn,\r\n        ddv.TienGiamGia,\r\n        SUM(tt.SoTien) AS TienDaThu,\r\n        (SELECT COUNT(*) FROM dbo.CHITIETVE cv\r\n         WHERE cv.DonDatVeID = ddv.DonDatVeID AND cv.TrangThai <> N''Đã hủy'') AS SoVeCuaDon\r\n    FROM dbo.DONDATVE ddv\r\n    INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\r\n    INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\r\n    INNER JOIN dbo.THANHTOAN tt ON tt.DonDatVeID = ddv.DonDatVeID AND tt.TrangThai = N''Thành công''\r\n    GROUP BY ddv.DonDatVeID, pc.RapID, ddv.TongTienVe, ddv.TongTienDoAn, ddv.TienGiamGia\r\n),\r\nSuatChieuTheoRap AS (\r\n    SELECT\r\n        pc.RapID,\r\n        COUNT(DISTINCT sc.SuatChieuID) AS TongSoSuatChieu\r\n    FROM dbo.PHONGCHIEU pc\r\n    LEFT JOIN dbo.SUATCHIEU sc ON pc.PhongID = sc.PhongID\r\n    GROUP BY pc.RapID\r\n)\r\nSELECT\r\n    r.RapID,\r\n    r.TenRap,\r\n    r.ThanhPho,\r\n    COUNT(dh.DonDatVeID) AS TongSoDon,\r\n    ISNULL(sc_rap.TongSoSuatChieu, 0) AS TongSoSuatChieu,\r\n    ISNULL(SUM(dh.SoVeCuaDon), 0) AS TongSoVeBan,\r\n    ISNULL(SUM(dh.TongTienVe), 0) AS DoanhThuVe,\r\n    ISNULL(SUM(dh.TongTienDoAn), 0) AS DoanhThuDoAn,\r\n    ISNULL(SUM(dh.TienGiamGia), 0) AS TongTienGiam,\r\n    ISNULL(SUM(dh.TienDaThu), 0) AS DoanhThuThucTe\r\nFROM dbo.RAPCHIEUPHIM r\r\nLEFT JOIN DonDaThu dh ON r.RapID = dh.RapID\r\nLEFT JOIN SuatChieuTheoRap sc_rap ON r.RapID = sc_rap.RapID\r\nGROUP BY r.RapID, r.TenRap, r.ThanhPho, sc_rap.TongSoSuatChieu;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_LichChieuChiTiet","type":"V ","type_desc":"VIEW","definition":"-- Baseline: views/03_views.sql:18 (dbo.vw_LichChieuChiTiet)\r\nCREATE   VIEW dbo.vw_LichChieuChiTiet\r\nAS\r\nSELECT\r\n    sc.SuatChieuID,\r\n    p.PhimID,\r\n    p.TenPhim,\r\n    p.ThoiLuong,\r\n    p.DoTuoi,\r\n    p.PosterURL,\r\n    p.TrailerURL,\r\n    p.TrangThai AS TrangThaiPhim,\r\n    r.RapID,\r\n    r.TenRap,\r\n    r.ThanhPho,\r\n    r.DiaChi AS DiaChiRap,\r\n    pc.PhongID,\r\n    pc.TenPhong,\r\n    pc.LoaiPhong,\r\n    sc.ThoiGianBatDau,\r\n    sc.ThoiGianKetThuc,\r\n    dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) AS NgayChieu,\n    CONVERT(varchar(5), CONVERT(time, dbo.fn_GioRap(sc.ThoiGianBatDau)), 108) AS GioBatDau,\n    CONVERT(varchar(5), CONVERT(time, dbo.fn_GioRap(sc.ThoiGianKetThuc)), 108) AS GioKetThuc,\n    sc.DinhDang,\r\n    sc.GiaVeCoBan,\r\n    sc.TrangThai AS TrangThaiSuatChieu,\r\n    (SELECT COUNT(*) FROM dbo.GHE g WHERE g.PhongID = pc.PhongID AND g.TrangThai = N''Hoạt động'') AS TongSoGhe,\r\n    (SELECT COUNT(*)\r\n     FROM dbo.CHITIETVE cv\r\n     INNER JOIN dbo.DONDATVE ddv ON cv.DonDatVeID = ddv.DonDatVeID\r\n     WHERE ddv.SuatChieuID = sc.SuatChieuID\r\n       AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\r\n       AND cv.TrangThai <> N''Đã hủy''\r\n    ) AS SoGheDaDat\r\nFROM dbo.SUATCHIEU sc\r\nINNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\r\nINNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\r\nINNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_LichSuDatVe","type":"V ","type_desc":"VIEW","definition":"-- Baseline: views/03_views.sql:62 (dbo.vw_LichSuDatVe)\r\nCREATE   VIEW dbo.vw_LichSuDatVe\r\nAS\r\nSELECT\r\n    ddv.DonDatVeID,\r\n    ddv.NguoiDungID,\r\n    nd.HoTen AS HoTenKhachHang,\r\n    nd.Email,\r\n    nd.SoDienThoai,\r\n    sc.SuatChieuID,\r\n    p.PhimID,\r\n    p.TenPhim,\r\n    p.PosterURL,\r\n    r.RapID,\r\n    r.TenRap,\r\n    pc.TenPhong,\r\n    sc.ThoiGianBatDau,\r\n    sc.ThoiGianKetThuc,\r\n    sc.DinhDang,\r\n    ddv.NgayDat,\r\n    ddv.TongTienVe,\r\n    ddv.TongTienDoAn,\r\n    ddv.TienGiamGia,\r\n    (ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia) AS TongTienThanhToan,\r\n    CASE WHEN ddv.TrangThai = N''Chờ thanh toán'' AND ddv.HanGiuCho <= dbo.fn_BayGio() THEN N''Hết hạn'' ELSE ddv.TrangThai END AS TrangThaiDon,\r\n    ddv.HanGiuCho,\r\n    km.MaCode AS MaKhuyenMai,\r\n    (SELECT COUNT(*) FROM dbo.CHITIETVE cv WHERE cv.DonDatVeID = ddv.DonDatVeID AND cv.TrangThai <> N''Đã hủy'') AS SoLuongVe,\r\n    (SELECT TOP 1 tt.TrangThai\r\n     FROM dbo.THANHTOAN tt\r\n     WHERE tt.DonDatVeID = ddv.DonDatVeID\r\n     ORDER BY tt.ThanhToanID DESC) AS TrangThaiThanhToanMoiNhat\r\nFROM dbo.DONDATVE ddv\r\nINNER JOIN dbo.NGUOIDUNG nd ON ddv.NguoiDungID = nd.NguoiDungID\r\nINNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\r\nINNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\r\nINNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\r\nINNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\r\nLEFT JOIN dbo.KHUYENMAI km ON ddv.KhuyenMaiID = km.KhuyenMaiID;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_ThongKePhim","type":"V ","type_desc":"VIEW","definition":"CREATE   VIEW dbo.vw_ThongKePhim\r\nAS\r\nSELECT\r\n    p.PhimID,\r\n    p.TenPhim,\r\n    p.ThoiLuong,\r\n    p.NgayKhoiChieu,\r\n    p.DoTuoi,\r\n    p.PosterURL,\r\n    p.TrangThai,\r\n    ISNULL(dg.SoLuotDanhGia, 0) AS SoLuotDanhGia,\n    ISNULL(dg.DiemDanhGiaTrungBinh, 0.0) AS DiemDanhGiaTrungBinh,\n    ISNULL(sc.TongSoSuatChieu, 0) AS TongSoSuatChieu\nFROM dbo.PHIM p\r\nLEFT JOIN (SELECT PhimID, COUNT(*) AS SoLuotDanhGia, ROUND(AVG(CAST(SoSao AS FLOAT)), 1) AS DiemDanhGiaTrungBinh\n           FROM dbo.DANHGIAPHIM GROUP BY PhimID) dg ON p.PhimID = dg.PhimID\nLEFT JOIN (SELECT PhimID, COUNT(*) AS TongSoSuatChieu FROM dbo.SUATCHIEU GROUP BY PhimID) sc ON p.PhimID = sc.PhimID;\n","uses_ansi_nulls":true,"uses_quoted_identifier":true}]';
SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[name] COLLATE DATABASE_DEFAULT AS [name],[type] COLLATE DATABASE_DEFAULT AS [type] INTO #Expected_objects FROM OPENJSON(@expected) WITH ([schemaName] nvarchar(4000) '$.schemaName',[name] nvarchar(4000) '$.name',[type] nvarchar(4000) '$.type');
SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[name] COLLATE DATABASE_DEFAULT AS [name],[type] COLLATE DATABASE_DEFAULT AS [type] INTO #Actual_objects FROM (SELECT s.name schemaName,o.name,o.type,o.type_desc,m.definition,m.uses_ansi_nulls,m.uses_quoted_identifier FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.is_ms_shipped=0) actual;
IF EXISTS (SELECT * FROM #Expected_objects EXCEPT SELECT * FROM #Actual_objects) OR EXISTS (SELECT * FROM #Actual_objects EXCEPT SELECT * FROM #Expected_objects)
BEGIN
 SELECT 'Missing or changed' AS Difference,* FROM (SELECT * FROM #Expected_objects EXCEPT SELECT * FROM #Actual_objects) missing;
 SELECT 'Unexpected or changed' AS Difference,* FROM (SELECT * FROM #Actual_objects EXCEPT SELECT * FROM #Expected_objects) extra;
 THROW 51001, 'Verify objects failed.', 1;
END;
DROP TABLE #Expected_objects; DROP TABLE #Actual_objects;
PRINT 'PASS objects';
GO
